static dma_particle_s *DebrisParticleAt(debkeydatatype_s *key, i16 index, u8 particle_type) {
    if (particle_type == 7)
        return &key->particle_chunks[index / 12]->particles[index % 12];
    return &key->particle_chunks[index / 32]->particles[index % 32];
}

