namespace {

    // Target NewScanRot 0x378fb0 uses 0.1f on both horizontal axes when
    // selecting the terrain shapes that can contain the cast point.
    const f32 SHADOW_SCAN_HALF_EXTENT = 0.1f;

    static bool ShadowBoundsOverlap(f32 min_x, f32 min_z, f32 max_x, f32 max_z, const NUVEC &minimum,
                                    const NUVEC &maximum) {
        return max_x >= minimum.x && max_z >= minimum.z && maximum.x >= min_x && maximum.z > min_z;
    }

    static void ShadowFinishGroup(ShadowScanWriter *writer, i32 group_index) {
        if (writer->shape_count == 0) {
            return;
        }

        i16 *header = reinterpret_cast<i16 *>(writer->group_header);
        header[0] = static_cast<i16>(writer->shape_count);
        header[1] = static_cast<i16>(group_index);
        writer->group_header = reinterpret_cast<u8 *>(writer->cursor);
        writer->cursor = reinterpret_cast<TERRAIN_SHAPE **>(writer->group_header + sizeof(TERRAIN_SHAPE *));
        writer->shape_count = 0;
    }

} // namespace

static inline i32 InstallExtraTerrainPlatform(TERRSET *terrain, TERRAIN_GROUP *source, NUMTX *matrix, NUMTX *previous,
                                              i32 rotating, i32 index, TERRAIN_PLATFORM &platform, i16 group_index,
                                              i32 index_count) {
    TERRAIN_GROUP &group = terrain->groups[group_index];
    group = *source;
    group.scene_index = index;
    group.chunk_type = 1;
    platform.scene_object = matrix;
    if (rotating != 0) {
        platform.previous_matrix = *previous;
        platform.flags |= TERRAIN_PLATFORM_FLAG_ROTATING;
    } else {
        if (previous != NULL) {
            platform.previous_matrix.m30 = previous->m30;
            platform.previous_matrix.m31 = previous->m31;
            platform.previous_matrix.m32 = previous->m32;
        } else {
            platform.previous_matrix.m30 = matrix->m30;
            platform.previous_matrix.m31 = matrix->m31;
            platform.previous_matrix.m32 = matrix->m32;
        }
        platform.flags &= ~TERRAIN_PLATFORM_FLAG_ROTATING;
    }
    group.origin.x = matrix->m30;
    group.origin.y = matrix->m31;
    group.origin.z = matrix->m32;
    platform.terrain_group_index = group_index;
    platform.scene_object_index = 0;
    platform.scene_transform = NULL;
    terrain->group_indices[index_count] = group_index;
    terrain->group_index_count = index_count + 1;
    platform.flags &= ~TERRAIN_PLATFORM_FLAG_COLLIDED;
    platform.bounce_impulse = 0.0f;
    platform.bounce_offset = 0.0f;
    platform.bounce_velocity = 0.0f;
    platform.bounce_damping = 0.0f;
    platform.bounce_spring = 0.0f;
    if (terrain->active_platform_count < 96)
        terrain->active_platform_groups[terrain->active_platform_count++] = terrain->group_count;
    ++terrain->cells[TERRAIN_PLATFORM_CELL].group_count;
    ++terrain->group_count;
    terrain->removed_platforms[terrain->removed_platform_count++] = index;
    return index;
}

// Original 0x378fb0: the optimized rotating scan shares the terrain engine state.

namespace {
    static bool TerrainHandleVerticesOverlap(const TerrainScanBounds &bounds, const TERRAIN_SHAPE &shape);
    static bool TerrainHandleWallOverlap(const TerrainScanBounds &bounds, const TERRAIN_WALL_POINT *wall);

    static bool TerrainBeginHandle(TerrainScanWriter *writer) {
        u8 *begin = static_cast<u8 *>(TempScanStack);
        u8 *end = begin + 0x2000;
        u8 *start = static_cast<u8 *>(TempStackPtr);
        const usize slot = sizeof(void *);
        if (start < begin || start > end - slot * 2)
            return false;
        writer->cursor = reinterpret_cast<TERRAIN_SHAPE **>(start + slot);
        writer->group_header = start;
        const usize available = static_cast<usize>(end - start);
        writer->limit = start + (MIN(static_cast<usize>(0x800 - slot * 3), available - slot * 2));
        writer->group_shape_count = 0;
        writer->scaled_shape_count = 0;
        return true;
    }

} // namespace

namespace {
    static TerrainScanBounds TerrainHandleBounds(const NUVEC &position, const NUVEC &movement, f32 radius) {
        TerrainScanBounds bounds;
        if (movement.x > 0.0f) {
            bounds.max_x = movement.x + position.x + 0.02f + radius;
            bounds.min_x = position.x - 0.02f - radius;
        } else {
            bounds.max_x = position.x + 0.02f + radius;
            bounds.min_x = movement.x + position.x - 0.02f - radius;
        }
        if (movement.y > 0.0f) {
            bounds.max_y = movement.y + position.y + 0.02f + radius;
            bounds.min_y = position.y - 0.02f - radius;
        } else {
            bounds.max_y = position.y + 0.02f + radius;
            bounds.min_y = movement.y + position.y - 0.02f - radius;
        }
        if (!(movement.z > 0.0f)) {
            bounds.min_z = movement.z + position.z - 0.02f - radius;
            bounds.max_z = position.z + 0.02f + radius;
        } else {
            bounds.min_z = position.z - 0.02f - radius;
            bounds.max_z = movement.z + position.z + 0.02f + radius;
        }
        return bounds;
    }

    static bool TerrainHandleVerticesOverlap(const TerrainScanBounds &bounds, const TERRAIN_SHAPE &shape) {
        return (shape.vectors[0].x > bounds.min_x || shape.vectors[1].x > bounds.min_x ||
                shape.vectors[2].x > bounds.min_x || shape.vectors[3].x > bounds.min_x) &&
               (shape.vectors[0].x < bounds.max_x || shape.vectors[1].x < bounds.max_x ||
                shape.vectors[2].x < bounds.max_x || shape.vectors[3].x < bounds.max_x) &&
               (shape.vectors[0].z > bounds.min_z || shape.vectors[1].z > bounds.min_z ||
                shape.vectors[2].z > bounds.min_z || shape.vectors[3].z > bounds.min_z) &&
               (shape.vectors[0].z < bounds.max_z || shape.vectors[1].z < bounds.max_z ||
                shape.vectors[2].z < bounds.max_z || shape.vectors[3].z < bounds.max_z);
    }

    static bool TerrainHandleWallOverlap(const TerrainScanBounds &bounds, const TERRAIN_WALL_POINT *wall) {
        return ((wall[0].position.x >= bounds.min_x && wall[1].position.x <= bounds.max_x) ||
                (wall[1].position.x >= bounds.min_x && wall[0].position.x <= bounds.max_x)) &&
               ((wall[0].position.z >= bounds.min_z && wall[1].position.z <= bounds.max_z) ||
                (wall[1].position.z >= bounds.min_z && wall[0].position.z <= bounds.max_z));
    }
} // namespace

