    if (edptl_torus_menu == NULL)
        return;

    eduiMenuAddItem(edptl_torus_menu,
                    eduiItemSliderCreate(0, colours, 0, cbChangeTorusLife, 0.0f, 5.0f * edptl_superscale,
                                         effect->torus_lifetime, "Torus Life"));
