static void cbPtlTypeMenu(eduimenu_s *parent, eduiitem_s *, u32) {
    i32 count = 0;
    for (i32 index = 1; index < EDPP_MAX_TYPES; ++index) {
        if (debtab[index] == NULL)
            continue;
        if (edpp_effect_list == 1) {
            if (debtab[index]->category == 1 && debtab[index]->page == edbits_particle_level_page)
                ++count;
        } else if (debtab[index]->category == edpp_effect_list) {
            ++count;
        }
    }

    char title[40];
    sprintf(title, "Particle Types (%d)", count);
    ptltypemenu = eduiMenuCreate(70, 70, 180, 250, ed_fnt, cbPtlCancelTypeMenu, title);
    if (ptltypemenu == NULL)
        return;

    i32 found_selected = 0;
    for (i32 index = 1; index < EDPP_MAX_TYPES; ++index) {
        debinftype *effect = debtab[index];
        if (effect == NULL)
            continue;
        if (edpp_effect_list == 1) {
            if (effect->category != 1 || effect->page != edbits_particle_level_page)
                continue;
        } else if (effect->category != edpp_effect_list) {
            continue;
        }

        bool placed = false;
        for (const edpp_particle_s &particle : edpp_ptls) {
            if (particle.instance_id != -1 && particle.instance_id != 99999 && particle.effect_index == index) {
                placed = true;
                break;
            }
        }
        const i32 selected = index == edpp_create_type;
        if (placed)
            eduiMenuAddItem(ptltypemenu, eduiItemCheckCreate(index, edblack, selected, 1, cbPtlSelType, effect->name));
        else
            eduiMenuAddItem(ptltypemenu,
                            eduiItemCheckCreate(index, eddarkred, selected, 1, cbPtlSelType, effect->name));
        if (selected == 1) {
            found_selected = 1;
            ptltypemenu->selected = edui_last_item;
        }
    }
    eduiMenuSortItemsByTxt(ptltypemenu);
    eduiMenuAddItemFirst(ptltypemenu, eduiItemSelCreate(1, edblack, 0, 0, cbPtlAddEffect, "Add Effect"));
    eduiMenuAttach(parent, ptltypemenu);
    ptltypemenu->x = parent->x + 10;
    ptltypemenu->y = parent->y + 40;
    if (found_selected)
        ptltypemenu->field_0c = ptltypemenu->selected;
}

