void CRC_Init(VARIPTR *buffer_start) {
    if (g_crc_initialised) {
        return;
    }

    g_crc_table = reinterpret_cast<i32 *>(ALIGN(buffer_start->addr, alignof(i32)));
    buffer_start->addr = reinterpret_cast<usize>(g_crc_table + 0x100);

    for (u32 i = 0; i < 0x100; i++) {
        u32 crc = i << 24;

        for (i32 j = 0; j < 8; j++) {
            u32 top_bit = crc & 0x80000000U;
            crc <<= 1;
            if (top_bit != 0) {
                crc ^= CRC32_POLY;
            }
        }
        g_crc_table[i] = crc;
    }

    g_crc_initialised = 1;
}

u32 CRC_Process(const void *data, u32 size) {
    const u8 *bytes = static_cast<const u8 *>(data);
    u32 crc = 0;
    for (u32 i = 0; i < size; ++i) {
        crc = g_crc_table[(crc >> 24) ^ bytes[i]] ^ (crc << 8);
    }
    return crc;
}

u32 CRC_ProcessString(const char *str) {
    u32 crc = 0;
    for (i32 i = 0; str[i] != '\0'; ++i) {
        crc = g_crc_table[(crc >> 24) ^ str[i]] ^ (crc << 8);
    }
    return crc;
}

u32 CRC_ProcessStringN(const char *str, u32 size) {
    u32 crc = 0;
    for (u32 i = 0; str[i] != '\0' && i < size; ++i) {
        crc = g_crc_table[(crc >> 24) ^ str[i]] ^ (crc << 8);
    }
    return crc;
}

u32 CRC_ProcessStringIgnoreCase(const char *str) {
    u32 crc = 0;
    for (char c = *str++; c != '\0'; c = *str++) {
        const u32 table_index = static_cast<u32>(static_cast<i32>(CRC_ToUpper(c))) ^ (crc >> 24);
        crc = (crc << 8) ^ g_crc_table[table_index];
    }
    return crc;
}

u32 CRC_ProcessStringNIgnoreCase(const char *str, u32 size) {
    u32 crc = 0;
    for (u32 i = 0; str[i] != '\0' && i < size; ++i) {
        const u32 table_index = static_cast<u32>(static_cast<i32>(CRC_ToUpper(str[i]))) ^ (crc >> 24);
        crc = (crc << 8) ^ g_crc_table[table_index];
    }
    return crc;
}

void SetSfxBit_OnEx(i32 sound) {
    if (static_cast<u32>(sound) < 1600) {
        SfxBits[sound >> 4] |= 1 << (sound & 15);
    }
}

void SetSfxBit_OffEx(i32 sound) {
    if (static_cast<u32>(sound) < 1600) {
        SfxBits[sound >> 4] &= ~(1 << (sound & 15));
    }
}

i32 SfxBitEx(i32 sound) {
    if (static_cast<u32>(sound) >= 1600) {
        return -1;
    }
    const u16 mask = static_cast<u16>(1u << (sound & 15));
    return (SfxBits[sound >> 4] & mask) != 0;
}

extern "C" {
    void SetSfxBit_On(i32 sound) {
        if (sound >= 0)
            SetSfxBit_OnEx(g_soundInfo[sound].index);
    }

    void SetSfxBit_Off(i32 sound) {
        if (sound >= 0) {
            SetSfxBit_OffEx(g_soundInfo[sound].index);
        }
    }

    i32 SfxBit(i32 sound) {
        if (sound < 0) {
            return 0;
        }
        return SfxBitEx(g_soundInfo[sound].index);
    }

}

void SetSfxBitTab_OnEx(SoundTable *table, i32 sound) {
    if (static_cast<u32>(sound) < 1600) {
        table->bits[sound >> 4] |= 1 << (sound & 15);
    }
}

void SetSfxBitTab_OffEx(SoundTable *table, i32 sound) {
    if (static_cast<u32>(sound) < 1600) {
        table->bits[sound >> 4] &= ~(1 << (sound & 15));
    }
}

i32 SfxBitTabEx(SoundTable const *table, i32 sound) {
    if (static_cast<u32>(sound) >= 1600) {
        return -1;
    }
    const u16 mask = static_cast<u16>(1u << (sound & 15));
    return (table->bits[sound >> 4] & mask) != 0;
}

extern "C" {
    void SetSfxBitTab_On(SoundTable *table, i32 sound) {
        if (sound >= 0) {
            SetSfxBitTab_OnEx(table, g_soundInfo[sound].index);
        }
    }

    void SetSfxBitTab_Off(SoundTable *table, i32 sound) {
        if (sound >= 0) {
            SetSfxBitTab_OffEx(table, g_soundInfo[sound].index);
        }
    }

    i32 SfxBitTab(const SoundTable *table, i32 sound) {
        if (sound < 0) {
            return 0;
        }
        return SfxBitTabEx(table, g_soundInfo[sound].index);
    }

    void SfxBitsSetAll(u16 *bits) {
        memset(bits, 0xff, sizeof(SfxBits));
    }

    void SfxBitsStore(SoundTable *table) {
        memmove(table->bits, SfxBits, sizeof(SfxBits));
    }

    void SfxBitsRestore(SoundTable *table) {
        memmove(SfxBits, table->bits, sizeof(SfxBits));
    }

    void SfxBitMaskTable(u16 *bits, const u16 *mask) {
        for (i32 i = 0; i < 100; i++) {
            bits[i] &= mask[i];
        }
    }

extern "C" void ResetSounds(void) {
    memcpy(SfxBits, GlobalSfxBits, sizeof(SfxBits));
}

extern "C" void PrepareSounds(const u16 *sounds) {
    for (i32 i = 0; i < 100; ++i) {
        SfxBits[i] |= sounds[i];
    }
}

    void PrepareAllSounds(void) {
        for (i32 i = 0; i < 100; ++i) {
            SfxBits[i] = 0xffff;
        }
    }

extern "C" void MaskSounds(const u16 *mask) {
    for (i32 i = 0; i < 100; ++i) {
        SfxBits[i] &= mask[i];
    }
}

}

void GroupBuffer_MoveToEnd(i32 group_id) {
    i32 buffer_length = g_lenGroupBuffer;
    i32 first_sample = g_groups[group_id].first_sample;
    i16 sample_count = g_groups[group_id].sample_count;
    i32 group_end = sample_count + first_sample;
    if (buffer_length == group_end) {
        return;
    }

    g_groups[group_id].first_sample = static_cast<i16>(buffer_length);
    memmove(&g_groupBuffer[buffer_length], &g_groupBuffer[first_sample],
            static_cast<usize>(sample_count) * sizeof(i16));
    memmove(&g_groupBuffer[first_sample], &g_groupBuffer[group_end],
            static_cast<usize>(buffer_length - first_sample) * sizeof(i16));

    for (i32 i = 0; i < g_numGroups; i++) {
        if (g_groups[i].first_sample > first_sample) {
            g_groups[i].first_sample -= sample_count;
        }
    }
}

void GroupBuffer_AddToGroup(i32 group_id, i32 sample_id) {
    if (g_lenGroupBuffer == 512) {
        return;
    }

    g_groupBuffer[g_lenGroupBuffer++] = static_cast<i16>(sample_id);
    g_groups[group_id].sample_count++;
    g_groups[group_id].field_0x4 = 0;
    g_soundInfo[sample_id].group = static_cast<i16>(group_id);
}

void GroupBuffer_RemoveFromGroup(i32 group_id, i32 sample_id) {
    i32 first_sample = g_groups[group_id].first_sample;
    i16 sample_count = g_groups[group_id].sample_count;
    i32 end = first_sample + sample_count;
    i32 index = -1;
    for (i32 i = first_sample; i < end; i++) {
        if (g_groupBuffer[i] == sample_id) {
            index = i;
            break;
        }
    }
    if (index == -1) {
        return;
    }

    i32 buffer_length = g_lenGroupBuffer;
    memmove(&g_groupBuffer[index], &g_groupBuffer[index + 1],
            static_cast<usize>(buffer_length - index - 1) * sizeof(i16));
    g_lenGroupBuffer = buffer_length - 1;
    g_groups[group_id].sample_count = sample_count - 1;
    g_groups[group_id].field_0x4 = 0;
}

void GroupBuffer_RemoveGroup(i32 group_id) {
    if (group_id == -1) {
        return;
    }

    i32 first_sample = g_groups[group_id].first_sample;
    i16 sample_count = g_groups[group_id].sample_count;
    i32 buffer_length = g_lenGroupBuffer;
    memmove(&g_groupBuffer[first_sample], &g_groupBuffer[first_sample + sample_count],
            static_cast<usize>(buffer_length - first_sample - sample_count) * sizeof(i16));
    g_lenGroupBuffer = buffer_length - sample_count;

    i32 num_groups = g_numGroups;
    for (i32 i = 0; i < num_groups; i++) {
        if (g_groups[i].first_sample > first_sample) {
            g_groups[i].first_sample -= sample_count;
        }
    }

    memmove(&g_groups[group_id], &g_groups[group_id + 1], static_cast<usize>(num_groups - 1) * sizeof(SoundGroup));
    g_numGroups = num_groups - 1;

    for (i32 i = SFX_MUSIC_COUNT; i < NumSfxInst; i++) {
        if (g_soundInfo[i].group > group_id) {
            g_soundInfo[i].group--;
        } else if (g_soundInfo[i].group == group_id) {
            g_soundInfo[i].group = -1;
        }
    }
}

i32 GroupBuffer_MakeGroup(i32 sample_id) {
    if (g_numGroups == 128 || g_lenGroupBuffer == 512) {
        return -1;
    }

    i32 group_id = g_numGroups;
    g_groups[group_id].first_sample = static_cast<i16>(g_lenGroupBuffer);
    g_groups[group_id].sample_count = 1;
    g_groups[group_id].field_0x4 = 0;
    g_soundInfo[sample_id].group = static_cast<i16>(group_id);
    g_groupBuffer[g_lenGroupBuffer++] = static_cast<i16>(sample_id);
    g_numGroups++;
    return group_id;
}

i32 GroupBuffer_InGroup(i32 group_id, i32 sample_id) {
    i32 index = g_groups[group_id].first_sample;
    i32 end = index + g_groups[group_id].sample_count;
    while (index < end) {
        if (g_groupBuffer[index] == sample_id) {
            return 1;
        }
        index++;
    }
    return 0;
}

i32 GroupBuffer_GetSample(i32 group_id, i32 sequential) {
    i32 loaded_samples[32];
    i16 sample_count = g_groups[group_id].sample_count;
    i32 first_sample = g_groups[group_id].first_sample;
    memset(loaded_samples, 0, sizeof(loaded_samples));
    i32 loaded_count = 0;

    for (i32 i = 0; i < sample_count; i++) {
        i32 sample_id = g_groupBuffer[first_sample + i];
        if (NuSound3IsSampleLoaded(g_soundInfo[sample_id].index)) {
            loaded_samples[loaded_count++] = g_groupBuffer[first_sample + i];
        }
    }

    if (loaded_count == 0) {
        return -1;
    }

    i32 index;
    if (sequential == 0) {
        seed = NuRandIntSeeded(&seed);
        index = static_cast<i32>((seed >> 16) % static_cast<u32>(loaded_count));
    } else {
        index = g_groups[group_id].field_0x4++;
        if (g_groups[group_id].field_0x4 >= loaded_count) {
            g_groups[group_id].field_0x4 = 0;
        }
    }

    return loaded_samples[index];
}

i32 GroupBuffer_GetNumInGroup(i32 group_id) {
    return g_groups[group_id].sample_count;
}

i32 GroupBuffer_GetSampleByIndex(i32 group_id, i32 sample_index) {
    return g_groupBuffer[g_groups[group_id].first_sample + sample_index];
}

extern "C" {
    void SetSoundBitsBySingleId(i32 sound_id, SoundBitCallback set_bit) {
        if (sound_id >= 0) {
            set_bit(sound_id);

            i32 group_id = g_soundInfo[sound_id].group;
            if (group_id != -1) {
                i32 sample_count = GroupBuffer_GetNumInGroup(group_id);
                for (i32 i = 0; i < sample_count; ++i) {
                    set_bit(GroupBuffer_GetSampleByIndex(group_id, i));
                }
            }
        }
    }

    void SetSoundBitsById(const i32 *sound_ids, SoundBitCallback set_bit) {
        while (true) {
            i32 sound_id = *sound_ids++;
            if (sound_id == -1) {
                break;
            }
            if (sound_id >= 0) {
                set_bit(sound_id);

                i32 group_id = g_soundInfo[sound_id].group;
                if (group_id != -1) {
                    i32 sample_count = GroupBuffer_GetNumInGroup(group_id);
                    for (i32 i = 0; i < sample_count; ++i) {
                        set_bit(GroupBuffer_GetSampleByIndex(group_id, i));
                    }
                }
            }
        }
    }

}

i32 GetSfxId(const char *name) {
    if (name != NULL) {
        u32 hash = CRC_ProcessStringIgnoreCase(name) & 0xff;
        if (g_soundMap != NULL) {
            for (i32 index = g_soundMap[hash]; index != -1; index = g_soundInfo[index].next) {
                if (NuStrNICmp(name, g_soundInfo[index].sfx_name, 32) == 0) {
                    return index;
                }
            }
        }
    }

    return -1;
}

static void fnAudioGroup(nufpar_s *fpar) {
    i32 group_id = -1;
    i32 first = 1;

    while (NuFParGetWord(fpar) != 0) {
        i32 sfx_id = GetSfxId(fpar->word_buf);
        if (first) {
            if (sfx_id == -1) {
                return;
            }
            group_id = GroupBuffer_MakeGroup(sfx_id);
        } else {
            sfx_id = GetSfxId(fpar->word_buf);
            if (sfx_id != -1) {
                GroupBuffer_AddToGroup(group_id, sfx_id);
            }
        }
        first = 0;
    }
}

extern "C" {
    void RegisterSounds(SoundTable *table) {
        const char **names = table->names;
        memset(table->bits, 0, sizeof(table->bits));
        if (names == NULL) {
            return;
        }
        for (const char **name = names; *name != NULL; ++name) {
            i32 id = GetSfxId(*name);
            table->bits[id >> 4] |= static_cast<u16>(1 << (id & 0xf));
        }
    }

    i32 GetSfxIdN(char *name, i32 length) {
        for (i32 index = 0; index < 1600; ++index) {
            if (NuStrNICmp(name, g_soundInfo[index].sfx_name, length) == 0) {
                return index;
            }
        }
        return -1;
    }

    char *GetSfxName(i32 sfx_id) {
        return sfx_id < 0 ? NULL : const_cast<char *>(g_soundInfo[sfx_id].sfx_name);
    }

    void SetSoundVolume(f32 volume) {
        MASTERVOLUME = volume;
    }

    f32 GetSoundVolume(void) {
        return MASTERVOLUME;
    }

    void SetAudioFadeLevel(f32 level) {
        AUDIOFADELEVEL = level;
    }

}

f32 GetAudioFadeLevel() {
    return AUDIOFADELEVEL;
}

extern "C" {
    i32 IsSfxLooping(i32 sfx_id) {
        return sfx_id == -1 ? -1 : g_soundInfo[sfx_id].loop;
    }

}

bool HandleGroupLimit(i32 group_id) {
    SoundGroup *group = &g_groups[group_id];
    i32 voice_count = 0;
    NuSoundVoice *oldest_voice = NULL;
    // The original starts from FLT_MAX, so the "oldest" test below never
    // selects a voice.
    f32 oldest_position = 3.4028234663852886e+38f;

    for (i32 i = 0; i < group->sample_count; i++) {
        i32 sfx_id = g_groupBuffer[group->first_sample + i];
        i32 sample_index = g_soundInfo[sfx_id].index;
        voice_count += NuSound3CountVoices(sample_index);

        f32 playback_position = 0.0f;
        NuSoundVoice *voice = NuSound3FindOldestVoice(sample_index, &playback_position);
        if (voice != NULL && oldest_position < playback_position) {
            oldest_position = playback_position;
            oldest_voice = voice;
        }
    }

    if (voice_count < g_NuSoundMaxVoicesPerSample) {
        return true;
    }

    i32 first_sfx = g_groupBuffer[group->first_sample];
    if (g_soundInfo[first_sfx].field29_0x40 == 1) {
        NuSound3StopVoice(oldest_voice);
        return true;
    }
    return false;
}

extern "C" {
extern "C" void PlaySfxByIdEx(i32 sfx_id, nuvec_s *position, f32 volume, f32 pitch) {
    static nuvec_s pos;

    if (__builtin_expect(sfx_id == -1, 0)) {
        return;
    }

    if (g_soundInfo[sfx_id].disabled != 0 || g_soundInfo[sfx_id].comment != 0) {
        return;
    }

    i8 priority = g_soundInfo[sfx_id].priority;
    if (g_soundInfo[sfx_id].group != -1) {
        sfx_id = GroupBuffer_GetSample(g_soundInfo[sfx_id].group, g_soundInfo[sfx_id].seq);
        if (sfx_id == -1) {
            return;
        }
    }

    i32 sample_index = g_soundInfo[sfx_id].index;
    f32 pan = g_soundInfo[sfx_id].pan;
    u8 loop = static_cast<u8>(g_soundInfo[sfx_id].loop);
    f32 buzz_timer = g_soundInfo[sfx_id].buzz_timer;
    f32 rumble_sustain = g_soundInfo[sfx_id].rumble_sustain;
    i32 rumble_strength = g_soundInfo[sfx_id].rumble_strength;
    f32 rumble_release = g_soundInfo[sfx_id].rumble_release;

    f32 falloff_far = g_soundInfo[sfx_id].falloff_far;
    f32 falloff_near = g_soundInfo[sfx_id].falloff_near;
    f32 saved_fade_start = 0.0f;
    f32 saved_fade_end = 0.0f;
    if (__builtin_expect(!(g_soundInfo[sfx_id].falloff_near != 0.0f || g_soundInfo[sfx_id].falloff_far != 0.0f), 0)) {
        falloff_near = 2.0f;
        falloff_far = 15.0f;
    } else {
        saved_fade_start = nusound_fade_start;
        saved_fade_end = nusound_fade_end;
        nusound_fade_start = falloff_near * saved_fade_start * 0.5f;
        nusound_fade_end = falloff_far * saved_fade_end / 15.0f;
    }

    const NUMTX *listener = reinterpret_cast<const NUMTX *>(NuSound3GetListener());
    if (listener == NULL) {
        return;
    }

    if (position != NULL) {
        f32 dx = position->x - listener->m30;
        f32 dy = position->y - listener->m31;
        f32 dz = position->z - listener->m32;
        f32 max_distance_squared = nusound_fade_end * nusound_fade_end;
        if (dx * dx + dy * dy + dz * dz > max_distance_squared) {
            if (g_soundInfo[sfx_id].falloff_near != 0.0f || g_soundInfo[sfx_id].falloff_far != 0.0f) {
                nusound_fade_start = saved_fade_start;
                nusound_fade_end = saved_fade_end;
            }
            return;
        }
    }

    if (g_soundInfo[sfx_id].group != -1 && !HandleGroupLimit(g_soundInfo[sfx_id].group)) {
        return;
    }

    f32 volume_scale;
    if (__builtin_expect(volume != 1.0f, 1)) {
        if (volume > 1.0f) {
            volume = 1.0f;
        }
        volume_scale = static_cast<f32>(g_soundInfo[sfx_id].volume) * volume;
    } else {
        volume_scale = static_cast<f32>(g_soundInfo[sfx_id].volume);
    }

    if (g_soundInfo[sfx_id].nofade == 0) {
        volume_scale *= AUDIOFADELEVEL;
        volume_scale *= numusicGetDuckVolume();
    }
    i32 voice_volume = static_cast<i32>(volume_scale * MASTERVOLUME);

    if (g_soundInfo[sfx_id].pitch_rnd != 0.0f) {
        f32 pitch_variation = NuRandFloatSeeded(&seed) * g_soundInfo[sfx_id].pitch_rnd;
        if (__builtin_expect((NuRandIntSeeded(&seed) & 1) == 0, 1)) {
            pitch_variation *= 0.5f;
            pitch_variation = 1.0f - pitch_variation;
        } else {
            pitch_variation = 1.0f + pitch_variation;
        }
        pitch = pitch_variation * pitch;
    }

    if (g_soundInfo[sfx_id].volume_rnd != 0.0f) {
        voice_volume = static_cast<i32>(static_cast<f32>(voice_volume) *
                                        (1.0f + NuRandFloatSeeded(&seed) * g_soundInfo[sfx_id].volume_rnd));
    }

    if (static_cast<u32>(sample_index) <= 1599) {
        if (position == NULL) {
            i32 volume_left =
                pan < 0.0f ? voice_volume : static_cast<i32>((1.0f - pan) * static_cast<f32>(voice_volume));
            i32 volume_right =
                pan > 0.0f ? voice_volume : static_cast<i32>((1.0f + pan) * static_cast<f32>(voice_volume));

            if (loop) {
                listener = reinterpret_cast<const NUMTX *>(NuSound3GetListener());
                pos.x = listener->m30;
                pos.y = listener->m31;
                pos.z = listener->m32;
                nuvec_s *forward = reinterpret_cast<nuvec_s *>(const_cast<f32 *>(&listener->m20));
                NuVecAdd(&pos, &pos, forward);
                NuSound3Play3dLoopSfx(&pos, sample_index, falloff_near, falloff_far, volume_left, volume_right, pitch,
                                      buzz_timer, rumble_strength, rumble_sustain, rumble_release);
            } else if (priority == 0) {
                NuSound3Play(sample_index, volume_left, volume_right, pitch, buzz_timer, rumble_strength,
                             rumble_sustain, rumble_release);
            } else {
                NuSound3PlayPri(sample_index, volume_left, volume_right, pitch, buzz_timer, rumble_strength,
                                rumble_sustain, rumble_release, priority);
            }
        } else {
            if (loop) {
                NuSound3Play3dLoopSfx(position, sample_index, falloff_near, falloff_far, voice_volume, voice_volume,
                                      pitch, buzz_timer, rumble_strength, rumble_sustain, rumble_release);
            } else if (priority == 0) {
                NuSound3Play3d(position, sample_index, falloff_near, falloff_far, voice_volume, voice_volume, pitch,
                               buzz_timer, rumble_strength, rumble_sustain, rumble_release);
            } else {
                NuSound3Play3dPri(position, sample_index, falloff_near, falloff_far, voice_volume, voice_volume, pitch,
                                  buzz_timer, rumble_strength, rumble_sustain, rumble_release, priority);
            }
        }
    }

    if (__builtin_expect(g_soundInfo[sfx_id].falloff_near != 0.0f || g_soundInfo[sfx_id].falloff_far != 0.0f, 0)) {
        nusound_fade_start = saved_fade_start;
        nusound_fade_end = saved_fade_end;
    }
}

    void PlaySfxByIdAndSetVolumeAndPitch(i32 sfx_id, nuvec_s *position, f32 volume, f32 pitch) {
        PlaySfxByIdEx(sfx_id, position, volume, pitch);
    }

    void PlaySfxByIdAndSetPitch(i32 sfx_id, nuvec_s *position, f32 pitch) {
        PlaySfxByIdEx(sfx_id, position, 1.0f, pitch);
    }

    void PlaySfxByIdAndSetVolume(i32 sfx_id, nuvec_s *position, f32 volume) {
        PlaySfxByIdEx(sfx_id, position, volume, 1.0f);
    }

    void PlaySfxById(i32 sfx_id, nuvec_s *position) {
        PlaySfxByIdEx(sfx_id, position, 1.0f, 1.0f);
    }

    void PlaySfx(char *name, struct nuvec_s *position) {
        i32 sfx_id = GetSfxId(name);
        if (sfx_id != -1) {
            PlaySfxById(sfx_id, position);
        }
    }

    void PlaySfxAndSetVolume(char *name, nuvec_s *position, f32 volume) {
        i32 id = GetSfxId(name);
        if (id != -1) {
            PlaySfxByIdEx(id, position, volume, 1.0f);
        }
    }

    void PlaySfxAndSetPitch(char *name, nuvec_s *position, f32 pitch) {
        i32 sfx_id = GetSfxId(name);
        if (sfx_id != -1) {
            PlaySfxByIdEx(sfx_id, position, 1.0f, pitch);
        }
    }

    void PlaySfxAndSetVolumeAndPitch(char *name, nuvec_s *position, f32 volume, f32 pitch) {
        i32 sfx_id = GetSfxId(name);
        if (sfx_id != -1) {
            PlaySfxByIdEx(sfx_id, position, volume, pitch);
        }
    }

}

void InitSoundInfo(i32 index) {
    NUSOUNDINFO *info = &g_soundInfo[index];
    info->index = -1;
    info->flag_bytes[1] &= 0x7f;
    info->priority = 0;
    info->volume = 0x3fff;
    info->pan = 0.0;
    info->group = -1;
    info->pitch_rnd = 0.0;
    info->rumble_strength = 0;
    info->sfx_name = sfx_name[NumSfxInst];
    u8 flags = info->flag_bytes[2];
    info->category = 0;
    flags &= 0x88;
    info->field29_0x40 = 0;
    info->volume_rnd = 0.0;
    info->flag_bytes[2] = flags;
    info->falloff_near = 0.0;
    info->falloff_far = 0.0;
    info->buzz_timer = 0.0;
    info->rumble_sustain = 0.0;
    info->rumble_release = 0.0;

    g_revertSoundInfo[index] = *info;
}

static void fnAudioSample(nufpar_s *fpar) {
    InitSoundInfo(NumSfxInst);

    NUSOUND_FILENAME_INFO *finfo = NULL;
    while (true) {
        if (NuFParGetWord(fpar) == 0) {
            NUSOUNDINFO *sinfo = &g_soundInfo[NumSfxInst];
            sinfo->dirty = 0;
            sinfo->revertable = 1;
            memmove(&g_revertSoundInfo[NumSfxInst], sinfo, sizeof(NUSOUNDINFO));
            NumSfxInst++;
            return;
        }

        if (NuStrICmp(fpar->word_buf, "disable") == 0) {
            g_soundInfo[NumSfxInst].disabled = 1;
        } else if (NuStrICmp(fpar->word_buf, "comment") == 0) {
            g_soundInfo[NumSfxInst].comment = 1;
        } else if (NuStrICmp(fpar->word_buf, "maxvoicesbehaviour") == 0) {
            NuFParGetWord(fpar);
            if (NuStrICmp(fpar->word_buf, "noplay") == 0) {
                g_soundInfo[NumSfxInst].field29_0x40 = 0;
            } else if (NuStrICmp(fpar->word_buf, "replace") == 0) {
                g_soundInfo[NumSfxInst].field29_0x40 = 1;
            }
        } else if (NuStrICmp(fpar->word_buf, "name") == 0) {
            NuFParGetWord(fpar);
            NuStrNCpy(sfx_name[NumSfxInst], fpar->word_buf, 0x20);

            const char *str = sfx_name[NumSfxInst];
            g_soundInfo[NumSfxInst].sfx_name = str;
            u32 hash = CRC_ProcessStringIgnoreCase(str);

            i16 *id = &g_soundMap[hash & 0xff];
            if (*id == -1) {
                *id = NumSfxInst;
                g_soundInfo[NumSfxInst].next = -1;
            } else {
                g_soundInfo[NumSfxInst].next = *id;
                *id = NumSfxInst;
            }
        } else if (NuStrICmp(fpar->word_buf, "fname") == 0) {
            NuFParGetWord(fpar);

            if (g_soundInfo[NumSfxInst].disabled == 0 && g_soundInfo[NumSfxInst].comment == 0) {
                i32 i = 0;
                for (; i < NumSfx; i++) {
                    if (NuStrICmp(SfxInfo[i].filename, fpar->word_buf) == 0) {
                        finfo = &SfxInfo[i];
                        g_soundInfo[NumSfxInst].index = i;
                        g_soundInfo[NumSfxInst].filename = finfo->filename;
                        sfx_refcount[i]++;
                        break;
                    }
                }
                if (i == NumSfx) {
                    finfo = &SfxInfo[i];
                    finfo->filename = sfx_filename[NumSfxNames];
                    finfo->field4_0x4 = NULL;
                    finfo->index = i + 0x1000 - SFX_MUSIC_COUNT;
                    NuStrNCpy(sfx_filename[NumSfxNames++], fpar->word_buf, 0x40);
                    sfx_refcount[NumSfx] = 1;
                    g_soundInfo[NumSfxInst].filename = SfxInfo[NumSfx].filename;
                    g_soundInfo[NumSfxInst].index = NumSfx;
                    NumSfx++;
                }
            } else {
                g_soundInfo[NumSfxInst].index = -1;
                i32 i = 0;
                for (; i < NumSfx; i++) {
                    if (NuStrICmp(SfxInfo[i].filename, fpar->word_buf) == 0) {
                        sfx_refcount[i]++;
                        g_soundInfo[NumSfxInst].filename = SfxInfo[i].filename;
                        break;
                    }
                }
                if (i == NumSfx) {
                    u32 filename_index = NumSfxNames++;
                    NuStrNCpy(sfx_filename[filename_index], fpar->word_buf, 0x40);
                    g_soundInfo[NumSfxInst].filename = sfx_filename[NumSfxNames - 1];
                }
            }
        } else if (NuStrICmp(fpar->word_buf, "pitch") == 0) {
            g_soundInfo[NumSfxInst].pitch = NuFParGetInt(fpar);
        } else if (NuStrICmp(fpar->word_buf, "pan") == 0) {
            f32 pan = NuFParGetFloat(fpar);
            g_soundInfo[NumSfxInst].pan = pan < -1.0f ? -1.0f : pan > 1.0f ? 1.0f : pan;
        } else if (NuStrICmp(fpar->word_buf, "pri") == 0) {
            i32 priority = NuFParGetInt(fpar);
            g_soundInfo[NumSfxInst].priority = priority < -128 ? -128 : priority > 127 ? 127 : priority;
        } else if (NuStrICmp(fpar->word_buf, "loop") == 0) {
            g_soundInfo[NumSfxInst].loop = 1;
        } else if (NuStrICmp(fpar->word_buf, "pitch_rnd") == 0) {
            f32 pitch_rnd = NuFParGetFloat(fpar);
            g_soundInfo[NumSfxInst].pitch_rnd = pitch_rnd < 0.0f ? 0.0f : pitch_rnd > 1.0f ? 1.0f : pitch_rnd;
        } else if (NuStrICmp(fpar->word_buf, "volume") == 0) {
            i32 volume = NuFParGetInt(fpar);
            g_soundInfo[NumSfxInst].volume = volume < 0 ? 0 : volume > 0x3fff ? 0x3fff : volume;
        } else if (NuStrICmp(fpar->word_buf, "nofade") == 0) {
            g_soundInfo[NumSfxInst].nofade = 1;
        } else if (NuStrICmp(fpar->word_buf, "volume_rnd") == 0) {
            f32 volume_rnd = NuFParGetFloat(fpar);
            g_soundInfo[NumSfxInst].volume_rnd = !(volume_rnd >= -1.0f) ? -1.0f : volume_rnd > 0.0f ? 0.0f : volume_rnd;
        } else if (NuStrICmp(fpar->word_buf, "near") == 0) {
            f32 falloff_near = NuFParGetFloat(fpar);
            g_soundInfo[NumSfxInst].falloff_near = falloff_near < 0.0f     ? 0.0f
                                                   : falloff_near > 250.0f ? 250.0f
                                                                           : falloff_near;
        } else if (NuStrICmp(fpar->word_buf, "far") == 0) {
            f32 falloff_far = NuFParGetFloat(fpar);
            g_soundInfo[NumSfxInst].falloff_far = falloff_far < 0.0f     ? 0.0f
                                                  : falloff_far > 250.0f ? 250.0f
                                                                         : falloff_far;
        } else if (NuStrICmp(fpar->word_buf, "global") == 0) {
            g_soundInfo[NumSfxInst].global = 1;
        } else if (NuStrICmp(fpar->word_buf, "rumble") == 0) {
            f32 buzz_timer = NuFParGetFloat(fpar);
            i32 rumble_strength = NuFParGetInt(fpar);
            g_soundInfo[NumSfxInst].buzz_timer = buzz_timer < 0.0f ? 0.0f : buzz_timer > 5.0f ? 5.0f : buzz_timer;
            g_soundInfo[NumSfxInst].rumble_strength = rumble_strength < 0      ? 0
                                                      : rumble_strength > 0xff ? 0xff
                                                                               : rumble_strength;
            f32 rumble_sustain = NuFParGetFloat(fpar);
            g_soundInfo[NumSfxInst].rumble_sustain = rumble_sustain < 0.0f   ? 0.0f
                                                     : rumble_sustain > 5.0f ? 5.0f
                                                                             : rumble_sustain;
            f32 rumble_release = NuFParGetFloat(fpar);
            g_soundInfo[NumSfxInst].rumble_release = rumble_release < 0.0f   ? 0.0f
                                                     : rumble_release > 5.0f ? 5.0f
                                                                             : rumble_release;
        } else if (NuStrICmp(fpar->word_buf, "fcat") == 0) {
            i32 category = NuFParGetInt(fpar);
            g_soundInfo[NumSfxInst].category = category < 0 ? 0 : category > 0xffff ? 0xffff : category;
        }

        if (finfo != NULL) {
            finfo->field7_0x1c = g_soundInfo[NumSfxInst].field29_0x40;
        }
    }
}

void LoadSfx(const char *file, variptr_u *buffer_start, variptr_u buffer_end) {
    nufpar_s *fp = NuFParCreate(const_cast<char *>(file));
    if (fp != NULL) {
        NuFParPushCom(fp, audioCom);
        while (true) {
            if (NuFParGetLine(fp) == 0) {
                break;
            }
            NuFParGetWord(fp);
            if (*fp->word_buf != '\0') {
                NuFParInterpretWord(fp);
            }
        }
        NuFParDestroy(fp);
    }

    nusound_filename_info_s *last = &SfxInfo[NumSfx];
    last->filename = NULL;
    last->field4_0x4 = NULL;
    last->index = -1;

    NuSound3SetSampleTable(SfxInfo, buffer_start, buffer_end);

    memset(SfxBits, 0, sizeof(SfxBits));

    if (NOSOUND == 0) {
        NuSound3SetRequestTable(SfxBits, 100);
    }
}

void InitSfx(variptr_u *buffer_start, variptr_u buffer_end, const char *file) {
    // bVar15 = 0;
    // g_soundMap = (short *)((i32)buffer_start->voidptr + 3U & 0xfffffffc);
    usize allocation = ALIGN(buffer_start->addr, 4);
    g_soundMap = reinterpret_cast<i16 *>(allocation);

    // sfx_info = (nusound_filename_info_s *)(g_soundMap + 0x100);
    // SfxInfo = sfx_info;
    // buffer_start->voidptr = g_soundMap + 0x6500;
    // memset(sfx_info, 0, 0xc800);
    SfxInfo = reinterpret_cast<nusound_filename_info_s *>(allocation + 0x100 * sizeof(u16));
    buffer_start->addr = reinterpret_cast<usize>(SfxInfo + 1600);
    memset(SfxInfo, 0, 1600 * sizeof(nusound_filename_info_s));

    // sound_info = (SoundInfo *)((i32)buffer_start->voidptr + 3U & 0xfffffffc);
    // g_soundInfo = sound_info;
    // buffer_start->voidptr = sound_info + 0x640;
    // memset(sound_info, 0, 0x1a900);
    NUSOUNDINFO *sound_info = reinterpret_cast<NUSOUNDINFO *>(ALIGN(buffer_start->addr, 4));
    g_soundInfo = sound_info;
    buffer_start->addr = reinterpret_cast<usize>(sound_info + 1600);
    memset(sound_info, 0, 1600 * sizeof(NUSOUNDINFO));

    //__s = (void *)((i32)buffer_start->voidptr + 3U & 0xfffffffc);
    // g_revertSoundInfo = __s;
    // buffer_start->voidptr = (void *)((i32)__s + 0x1a900);
    // memset(__s, 0, 0x1a900);
    NUSOUNDINFO *revert_sound_info = reinterpret_cast<NUSOUNDINFO *>(ALIGN(buffer_start->addr, 4));
    g_revertSoundInfo = revert_sound_info;
    buffer_start->addr = reinterpret_cast<usize>(revert_sound_info + 1600);
    memset(revert_sound_info, 0, 1600 * sizeof(NUSOUNDINFO));

    CRC_Init(buffer_start);

    // psVar5 = g_soundMap;
    // uVar10 = -(((u32)g_soundMap & 0xf) >> 1) & 7;
    for (i32 i = 0; i < 0x100; i++) {
        g_soundMap[i] = -1;
    }

    NumSfx = 0;
    NumSfxInst = 0;

    i32 i = 0;
    for (; i < SFX_MUSIC_COUNT; i++) {
        SfxInfo[i] = g_music[i];
        SfxInfo[i].index = i;

        NuStrCpy(sfx_filename[i], SfxInfo[i].filename);
        SfxInfo[i].filename = sfx_filename[i];

        NumSfx = NumSfx + 1;
        NumSfxNames = NumSfxNames + 1;

        LOG_DEBUG("SfxInfo[%d]: name=%s", i, SfxInfo[i].filename);
    }

    SfxInfo[i].filename = NULL;
    SfxInfo[i].field4_0x4 = NULL;
    SfxInfo[i].index = -1;

    NuStrCpy(cfgfile_name, file);

    LoadSfx(file, buffer_start, buffer_end);

    memset(GlobalSfxBits, 0, sizeof(GlobalSfxBits));

    for (i32 i = 0; i < NumSfxInst; i++) {
        NUSOUNDINFO *sound_info = &g_soundInfo[i];
        if (sound_info->global != 0) {
            i32 index = sound_info->index;
            GlobalSfxBits[index >> 4] |= static_cast<u16>(1 << (index & 0xf));
        }
    }

    ResetSounds();
}

extern "C" {
    void PauseGameAudio(i32) {
        if (NOSOUND == 0) {
            NuSound3StopSFX();
            NuSound3SetSFXPitch(0);
        }
    }

    void ResumeGameAudio(void) {
        // Platform placeholder in the Android build.
    }

extern "C" i32 GetSfxCount(void) {
    return NumSfx;
}

extern "C" i32 GetLogicalSfxCount(void) {
    return NumSfxInst;
}

}

void RegisterMusic(NUSOUND_FILENAME_INFO *files) {
    LOG_DEBUG("files=%p", files);

    g_music = files;
    SFX_MUSIC_COUNT = 0;

    if (files != NULL) {
        for (; files->filename != NULL; files = files + 1) {
            NuStrLen(files->filename);
            LOG_DEBUG("Registered music file: %s", files->filename);
            SFX_MUSIC_COUNT++;
        }
    }
}

void PlayAMusic(i32 a, i32 b, i32 c, i32 d) {
    if (NOSOUND != 0 || NOMUSIC != 0) {
        return;
    }

    NuSound3StopStereoStream(a);
    NuSound3PlayStereoV(NUSOUNDPLAYTOK_STEREOSTREAM, a, NUSOUNDPLAYTOK_SAMPLE, b, NUSOUNDPLAYTOK_VOL, c,
                        d != 0 ? NUSOUNDPLAYTOK_ONESHOT : static_cast<NUSOUNDPLAYTOK>(0), NUSOUNDPLAYTOK_END);
    Music.secondary_stream = static_cast<i16>(a);
    Music.transition_frames = 0;
}

extern "C" {
    i32 GetCurrentMusicId(void) {
        return Music.current_track;
    }

    i32 GetOppMusicId(void) {
        return Music.queued_track;
    }

    void SetPreSeekStartPoint(f32 start_point) {
        Music.seek_offset = start_point;
    }

    void SetMusicVolume(f32 volume) {
        if (NOSOUND != 0 || NOMUSIC != 0) {
            return;
        }
        MusicVolume = volume;
        if (Music.state == MUSIC_PLAYBACK_ACTIVE) {
            NuSound3SetStereoStreamVolume(
                Music.primary_stream, static_cast<i32>(static_cast<f32>(g_music[Music.current_track].index) * volume));
        }
    }

    void SetCutVolume(f32 volume) {
        CutVolume = volume;
    }

    i32 GetCurPreSeek(void) {
        return Music.requested_track;
    }

    void ResetPreSeek(void) {
        if (Music.state == MUSIC_PLAYBACK_DUAL_STREAM) {
            Music.current_track = -1;
        } else {
            Music.queued_track = -1;
            Music.requested_track = -1;
            Music.pause_requested = false;
        }
        Music.seek_offset = 0.0f;
    }

    void MusicPreSeek(i32 track) {
        if (NOSOUND != 0 || NOMUSIC != 0 || track < 0 || track >= SFX_MUSIC_COUNT) {
            return;
        }

        const auto play_stream = [](i32 stream, i32 track, f32 seek_offset) {
            NuSound3StopStereoStream(stream);
            NuSound3PlayStereoV(NUSOUNDPLAYTOK_STEREOSTREAM, stream, NUSOUNDPLAYTOK_SAMPLE, track, NUSOUNDPLAYTOK_VOL,
                                0, NUSOUNDPLAYTOK_STARTOFFSET, static_cast<f64>(seek_offset), NUSOUNDPLAYTOK_ONESHOT,
                                NUSOUNDPLAYTOK_END);
        };
        const MusicPlaybackState state = Music.state;
        if ((state & ~MUSIC_PLAYBACK_ACTIVE) == MUSIC_PLAYBACK_STOPPED &&
            (track != Music.requested_track || Music.pause_requested)) {
            const i16 transition_frames = Music.transition_frames;
            const i32 primary_stream = Music.primary_stream;
            Music.resume_track = static_cast<i16>(track);
            Music.queued_track = static_cast<i16>(track);
            Music.requested_track = static_cast<i16>(track);
            reinterpret_cast<u8 *>(&Music)[primary_stream + 0x12] = 0;
            if (state == MUSIC_PLAYBACK_STOPPED || transition_frames >= 64) {
                Music.pause_requested = false;
                const f32 seek_offset = Music.seek_offset;
                const i32 stream = 1 - primary_stream;
                play_stream(stream, track, seek_offset);
                Music.secondary_stream = static_cast<i16>(stream);
                Music.transition_frames = 0;
                Music.seek_offset = 0.0f;
                if (track >= SFX_MUSIC_COUNT) {
                    return;
                }
            } else {
                Music.pause_requested = true;
            }
        }

        if (static_cast<u16>(Music.state - MUSIC_PLAYBACK_DUAL_STREAM) < 3 &&
            (track != Music.current_track || Music.pause_requested)) {
            const i32 primary_stream = Music.primary_stream;
            const i16 transition_frames = Music.transition_frames;
            Music.current_track = static_cast<i16>(track);
            Music.queued_track = static_cast<i16>(track);
            Music.requested_track = static_cast<i16>(track);
            Music.state = MUSIC_PLAYBACK_DUAL_STREAM;
            reinterpret_cast<u8 *>(&Music)[primary_stream + 0x12] = 0;
            if (__builtin_expect(transition_frames >= 64, 0)) {
                Music.pause_requested = false;
                const f32 seek_offset = Music.seek_offset;
                if (NOSOUND == 0 && NOMUSIC == 0) {
                    play_stream(primary_stream, track, seek_offset);
                }
                Music.secondary_stream = static_cast<i16>(primary_stream);
                Music.transition_frames = 0;
                Music.seek_offset = 0.0f;
            } else {
                Music.pause_requested = true;
            }
        }
    }

    void MusicPreSeekNow(i32 track) {
        if (track < 0 || track >= SFX_MUSIC_COUNT) {
            return;
        }

        const f32 seek_offset = Music.seek_offset;
        const i32 primary_stream = Music.primary_stream;
        Music.queued_track = static_cast<i16>(track);
        Music.requested_track = static_cast<i16>(track);
        Music.pause_requested = false;
        Music.stream_status_delay[primary_stream] = 0;
        if (NOSOUND == 0 && NOMUSIC == 0) {
            const i32 stream = 1 - primary_stream;
            NuSound3StopStereoStream(stream);
            NuSound3PlayStereoV(NUSOUNDPLAYTOK_STEREOSTREAM, stream, NUSOUNDPLAYTOK_SAMPLE, track, NUSOUNDPLAYTOK_VOL,
                                0, NUSOUNDPLAYTOK_STARTOFFSET, static_cast<f64>(seek_offset), NUSOUNDPLAYTOK_ONESHOT,
                                NUSOUNDPLAYTOK_END);
            Music.secondary_stream = static_cast<i16>(stream);
            Music.transition_frames = 0;
        }
        Music.seek_offset = 0.0f;
    }

extern "C" void MusicSeekOffset(i32 track, f32 seek_offset) {
    struct VolumeSnapshot {
        i32 index;
        f32 volume;
    };
    if (seek_offset < 0.0f) {
        seek_offset = Music.seek_offset;
    }
    if (track < 0 || track >= SFX_MUSIC_COUNT) {
        return;
    }

    if (static_cast<u16>(Music.state - MUSIC_PLAYBACK_DUAL_STREAM) < 3) {
        if (Music.current_track == track && !Music.pause_requested) {
            return;
        }
        const i16 primary_stream = Music.primary_stream;
        const i32 stream = primary_stream;
        Music.current_track = static_cast<i16>(track);
        Music.queued_track = static_cast<i16>(track);
        Music.requested_track = -1;
        Music.state = MUSIC_PLAYBACK_DUAL_STREAM;
        Music.stream_status_delay[stream] = 0;
        if (Music.transition_frames < 64) {
            Music.pause_requested = true;
        } else {
            Music.pause_requested = false;
            const VolumeSnapshot volume_snapshot = {g_music[track].index, MusicVolume};
            if (NOSOUND == 0 && NOMUSIC == 0) {
                NuSound3StopStereoStream(stream);
                NuSound3PlayStereoV(NUSOUNDPLAYTOK_STEREOSTREAM, stream, NUSOUNDPLAYTOK_SAMPLE, track,
                                    NUSOUNDPLAYTOK_VOL,
                                    static_cast<i32>(static_cast<f32>(volume_snapshot.index) * volume_snapshot.volume),
                                    NUSOUNDPLAYTOK_STARTOFFSET, static_cast<f64>(seek_offset), NUSOUNDPLAYTOK_ONESHOT,
                                    NUSOUNDPLAYTOK_END);
                Music.secondary_stream = primary_stream;
            }
            Music.transition_frames = 0;
            Music.seek_offset = 0.0f;
        }
        return;
    }

    const i16 primary_stream = Music.primary_stream;
    const i32 stream = primary_stream;
    Music.pause_requested = false;
    Music.stream_status_delay[stream] = 0;
    Music.current_track = static_cast<i16>(track);
    Music.queued_track = static_cast<i16>(track);
    Music.requested_track = static_cast<i16>(track);
    Music.state = MUSIC_PLAYBACK_ACTIVE;
    Music.transition_frames = 0;
    const VolumeSnapshot volume_snapshot = {g_music[track].index, MusicVolume};
    if (NOSOUND == 0 && NOMUSIC == 0) {
        NuSound3StopStereoStream(stream);
        NuSound3PlayStereoV(NUSOUNDPLAYTOK_STEREOSTREAM, stream, NUSOUNDPLAYTOK_SAMPLE, track, NUSOUNDPLAYTOK_VOL,
                            static_cast<i32>(static_cast<f32>(volume_snapshot.index) * volume_snapshot.volume),
                            NUSOUNDPLAYTOK_STARTOFFSET, static_cast<f64>(seek_offset), NUSOUNDPLAYTOK_ONESHOT,
                            NUSOUNDPLAYTOK_END);
        Music.transition_frames = 0;
        Music.secondary_stream = primary_stream;
    }
}

    void SoundStopMusic(void) {
        if (NOSOUND == 0 && NOMUSIC == 0) {
            NuSound3StopStereoStream(0);
            NuSound3StopStereoStream(1);

            Music.transition = 0.0f;
            Music.state = MUSIC_PLAYBACK_STOPPED;
            Music.requested_track = -1;
            Music.current_track = -1;
            Music.queued_track = -1;
            Music.primary_stream = 0;
            Music.transition_frames = 0;
            Music.pause_requested = false;
            Music.resume_frames = 0;
            Music.stream_status_delay[0] = 0;
            Music.stream_status_delay[1] = 0;
            Music.update_delay = 0;
            Music.restore_requested = false;
            Music.resume_track = -1;
        }
    }

    void SoundKillAll(void) {
        SoundStopMusic();
        NuSound3FlushLoops();
        NuSound3KillAllAudio();
    }

    i32 PlayingCutMusic(void) {
        const i32 stream = 1 - Music.primary_stream;
        u8 &delay = Music.stream_status_delay[stream];
        if (delay != 0) {
            --delay;
            return 0;
        }
        if (NOSOUND != 0 || NOMUSIC != 0) {
            return 0;
        }
        return NuSound3GetStereoStreamStatus(stream) != NUSOUND_STEREO_STREAM_FINISHED;
    }

    void ClearLinkedCutSceneMusic(void *context) {
        if (context == NULL || Music.track_data == context) {
            Music.track_data = NULL;
        }
    }

    void SetLinkedCutSceneMusic(void *context, i32 state) {
        Music.track_data = context;
        if (static_cast<u16>(Music.state - MUSIC_PLAYBACK_DUAL_STREAM) <= 2) {
            Music.state = state == MUSIC_PLAYBACK_DUAL_STREAM_PENDING ? MUSIC_PLAYBACK_DUAL_STREAM_PENDING
                                                                      : MUSIC_PLAYBACK_DUAL_STREAM;
        }
    }

    i32 PlayCutMusic(i32 track, i32 state, void *context) {
        if (NOSOUND != 0 || NOMUSIC != 0 || track < 0 || track >= SFX_MUSIC_COUNT) {
            return 0;
        }

        Music.queued_track = static_cast<i16>(track);
        Music.transition_frames = 0;

        Music.stream_status_delay[1 - Music.primary_stream] = 6;
        NuSound3CancelCheckStereo();
        NuSound3PauseStereoStream(Music.primary_stream);

        NuSound3SetStereoStreamVolume(Music.primary_stream,
                                      static_cast<i32>(static_cast<f32>(g_music[track].index) * CutVolume));

        i32 started = 0;
        if (Music.requested_track != track || Music.pause_requested ||
            NuSound3GetStereoStreamStatus(1 - Music.primary_stream) == NUSOUND_STEREO_STREAM_FINISHED) {
            PlayAMusic(1 - Music.primary_stream, track,
                       static_cast<i32>(static_cast<f32>(g_music[track].index) * CutVolume), 0);
            started = 1;
        } else {
            NuSound3ResumeStereoStream(1 - Music.primary_stream);
            NuSound3SetStereoStreamVolume(1 - Music.primary_stream,
                                          static_cast<i32>(static_cast<f32>(g_music[track].index) * CutVolume));
        }

        NuGCutSetCutAudioStream(1 - Music.primary_stream);
        Music.requested_track = -1;
        Music.pause_requested = false;
        Music.transition = 1.0f;
        switch (state) {
            case MUSIC_PLAYBACK_DUAL_STREAM_PENDING:
                Music.state = MUSIC_PLAYBACK_DUAL_STREAM_PENDING;
                break;
            case 12:
                Music.state = static_cast<MusicPlaybackState>(12);
                break;
            default:
                Music.state = static_cast<u16>(Music.state) < 1 ? static_cast<MusicPlaybackState>(12)
                                                                : MUSIC_PLAYBACK_DUAL_STREAM;
                break;
        }
        Music.track_data = context;
        return started;
    }

    void PauseGameMusic(void) {
        if (NOMUSIC == 0 && NOSOUND == 0 && NUSOUND_STREAM_3 != -1 && static_cast<u16>(Music.state - 11) > 2) {
            NuSound3CancelCheckStereo();
            NuSound3PauseStereoStream(Music.primary_stream);
            if (static_cast<u16>(Music.state - 5) < 6) {
                NuSound3PauseStereoStream(1 - Music.primary_stream);
            }
        }
        Music.restore_requested = false;
    }

    void RestoreGameMusic(void) {
        if ((NOMUSIC == 0 || NOSOUND == 0) && NUSOUND_STREAM_3 != -1) {
            if (Music.transition_frames < 25) {
                Music.restore_requested = true;
                return;
            }
            if (static_cast<u16>(Music.state - 11) > 2) {
                NuSound3ResumeStereoStream(Music.primary_stream);
                if (static_cast<u16>(Music.state - 5) < 6) {
                    NuSound3ResumeStereoStream(1 - Music.primary_stream);
                }
            }
        }
    }

    void PlayAltGameMusic(i32 track) {
        Music.update_delay = 1;
        if (Music.requested_track == track && !Music.pause_requested) {
            i32 stream = 1 - Music.primary_stream;
            NuSound3ResumeStereoStream(stream);
            NuSound3SetStereoStreamVolume(stream, static_cast<i32>(g_music[track].index * MusicVolume));
            Music.resume_track = -1;
        } else {
            PlayAMusic(1 - Music.primary_stream, track, static_cast<i32>(g_music[track].index * MusicVolume), 0);
        }
    }

    void StopAltGameMusic(void) {
        NuSound3CancelCheckStereo();
        NuSound3PauseStereoStream(1 - Music.primary_stream);
        Music.update_delay = 0;
        Music.queued_track = -1;
        Music.requested_track = -1;
        if (Music.resume_track >= 0) {
            MusicPreSeek(Music.resume_track);
        }
    }

    void PauseGameCut(void) {
        if (NOMUSIC != 0 || NOSOUND != 0 || NUSOUND_STREAM_3 == -1) {
            return;
        }

        MusicPlayback *music = &Music;
        if (music->state != MUSIC_PLAYBACK_DUAL_STREAM && music->state != MUSIC_PLAYBACK_DUAL_STREAM_PENDING) {
            return;
        }
        NuSound3CancelCheckStereo();
        NuSound3PauseStereoStream(1 - music->primary_stream);
    }

    void RestoreGameCut(void) {
        MusicPlayback *music = &Music;

        if (NOMUSIC != 0 && NOSOUND != 0) {
            return;
        }
        if (NUSOUND_STREAM_3 == -1) {
            return;
        }
        if (music->state != MUSIC_PLAYBACK_DUAL_STREAM && music->state != MUSIC_PLAYBACK_DUAL_STREAM_PENDING) {
            return;
        }
        NuSound3ResumeStereoStream(1 - music->primary_stream);
    }

    void PauseGameSfx(void) {
        NuSound3StopSFX();
        NuSound3FlushLoops();
        NuSound3SetSFXPitch(0);
    }

    void PlayMusic(i32 track, i32 mode) {
        if (NOSOUND != 0 || NOMUSIC != 0) {
            return;
        }

        if (track < 0 || track >= SFX_MUSIC_COUNT) {
            Music.primary_stream = 1 - Music.primary_stream;
            Music.restore_requested = false;
            Music.state = static_cast<MusicPlaybackState>((mode == 3) * 2 + 7);
            Music.queued_track = Music.current_track;
            Music.current_track = static_cast<i16>(track);
            Music.transition = 0.0f;
            return;
        }

        Music.transition_frames = 0;
        Music.queued_track = Music.current_track;
        Music.current_track = static_cast<i16>(track);

        i32 requested;
        i32 stream;
        i16 primary_stream;
        if (Music.state == MUSIC_PLAYBACK_STOPPED) {
            requested = Music.requested_track;
            primary_stream = Music.primary_stream;
            stream = primary_stream;
            Music.stream_status_delay[stream] = 0;
            if (requested == track)
                goto flip_primary_stream;
            goto start_primary_music;
        } else if (mode != 1 && NUSOUND_STREAM_3 != -1) {
            requested = Music.requested_track;
            Music.primary_stream = 1 - Music.primary_stream;
            stream = Music.primary_stream;
            Music.stream_status_delay[stream] = 0;
            if (requested == track && !Music.pause_requested) {
                Music.state = static_cast<MusicPlaybackState>((mode == 3) * 2 + 7);
                NuSound3ResumeStereoStream(stream);
                NuSound3SetStereoStreamVolume(Music.primary_stream, 0);
            } else {
                Music.state = static_cast<MusicPlaybackState>((mode == 3) * 2 + 8);
                PlayAMusic(stream, track, 0, 0);
            }
            Music.transition = 0.0f;
            goto clear_music_flags;
        } else {
            requested = Music.requested_track;
            primary_stream = Music.primary_stream;
            stream = primary_stream;
            Music.stream_status_delay[stream] = 0;
            if (requested != track || Music.state == MUSIC_PLAYBACK_DUAL_STREAM)
                goto start_primary_music;
        }

    flip_primary_stream:
        Music.primary_stream = 1 - primary_stream;
        stream = Music.primary_stream;
    start_primary_music:
        NuSound3StopStereoStream(1 - stream);
        if (Music.requested_track == track && !Music.pause_requested &&
            NuSound3GetStereoStreamStatus(Music.primary_stream) != NUSOUND_STEREO_STREAM_FINISHED) {
            NuSound3ResumeStereoStream(Music.primary_stream);
            NuSound3SetStereoStreamVolume(Music.primary_stream, static_cast<i32>(g_music[track].index * MusicVolume));
        } else {
            PlayAMusic(Music.primary_stream, track, static_cast<i32>(g_music[track].index * MusicVolume), 0);
        }
        Music.transition = 1.0f;
        Music.state = MUSIC_PLAYBACK_ACTIVE;
    clear_music_flags:
        Music.requested_track = -1;
        Music.pause_requested = false;
        Music.restore_requested = false;
    }

    void SwapMusic(i32 mode) {
        if (NOSOUND != 0 || NOMUSIC != 0) {
            return;
        }

        i16 previous_track = Music.current_track;
        i16 queued_track = Music.queued_track;
        Music.primary_stream = 1 - Music.primary_stream;
        Music.current_track = queued_track;
        Music.queued_track = previous_track;
        NuSound3ResumeStereoStream(Music.primary_stream);

        if (mode == 1) {
            NuSound3SetStereoStreamVolume(Music.primary_stream,
                                          static_cast<i32>(g_music[queued_track].index * MusicVolume));
            NuSound3PauseStereoStream(1 - Music.primary_stream);
            NuSound3SetStereoStreamVolume(1 - Music.primary_stream, 0);
            Music.state = MUSIC_PLAYBACK_ACTIVE;
            Music.transition = 1.0f;
        } else {
            f32 transition = 0.0f;
            if (static_cast<u16>(Music.state - 5) < 2) {
                transition = 1.0f - Music.transition;
            }
            Music.transition = transition;
            NuSound3SetStereoStreamVolume(Music.primary_stream,
                                          static_cast<i32>(g_music[queued_track].index * transition));
            Music.state = static_cast<MusicPlaybackState>((mode == 3) + 5);
        }
    }

extern "C" void SoundUpdate(float frame_time) {
    if (Music.update_delay != 0 || frame_time == 0.0f) {
        return;
    }

    // Playback states 4 through 13 form the active update range.
    switch (static_cast<u16>(Music.state - MUSIC_PLAYBACK_ACTIVE)) {
        case 4:
        case 6:
            if (NuSound3GetStereoStreamStatus(Music.primary_stream) != NUSOUND_STEREO_STREAM_FINISHED)
                Music.state = static_cast<MusicPlaybackState>(7);
            return;
        case 1:
        case 2:
        case 3:
        case 5: {
            if (Music.state == 9 || Music.state == 6) {
                Music.transition = (frame_time + frame_time) + Music.transition;
            } else {
                Music.transition = frame_time * 0.2f + Music.transition;
            }
            if (Music.transition >= 1.0f) {
                Music.transition = 1.0f;
                if (static_cast<u16>(Music.state - 5) <= 1) {
                    NuSound3PauseStereoStream(1 - Music.primary_stream);
                } else {
                    NuSound3StopStereoStream(1 - Music.primary_stream);
                }
                Music.state = MUSIC_PLAYBACK_ACTIVE;
                Music.transition_frames = 0;
            }

            if (Music.current_track != -1) {
                NuSound3SetStereoStreamVolume(Music.primary_stream,
                                              static_cast<i32>(static_cast<f32>(g_music[Music.current_track].index) *
                                                               Music.transition * MusicVolume));
            }
            if (Music.queued_track != -1) {
                NuSound3SetStereoStreamVolume(
                    1 - Music.primary_stream,
                    static_cast<i32>((1.0f - Music.transition) * static_cast<f32>(g_music[Music.queued_track].index) *
                                     MusicVolume));
            }
            return;
        }
        case 0: {
            if (!UpdateSecondaryMusicStream())
                return;
            if (Music.transition_frames <= 0x18) {
                return;
            }
            if (Music.restore_requested) {
                RestoreGameMusic();
                Music.restore_requested = false;
            }
            return;
        }
        case 7:
        case 8:
        case 9: {
            SoundTrackData *track_data = static_cast<SoundTrackData *>(Music.track_data);
            if (track_data != NULL && (track_data->flags_88 & 2) != 0) {
                Music.resume_frames = 0;
            } else {
                if (NuSound3GetStereoStreamStatus(1 - Music.primary_stream) == NUSOUND_STEREO_STREAM_FINISHED) {
                    Music.resume_frames = 0;
                } else {
                    if (Music.resume_frames <= 0x3f) {
                        ++Music.resume_frames;
                        if (Music.resume_frames <= 8) {
                            goto update_secondary_stream;
                        }
                    }
                    if (Music.current_track != -1 && Music.state != MUSIC_PLAYBACK_DUAL_STREAM_PENDING &&
                        NuSound3GetStereoStreamStatus(Music.primary_stream) != NUSOUND_STEREO_STREAM_FINISHED &&
                        !Music.pause_requested) {
                        if (Music.state == 12) {
                            Music.state = MUSIC_PLAYBACK_STOPPED;
                            NuSound3StopStereoStream(1 - Music.primary_stream);
                            NuSound3StopStereoStream(Music.primary_stream);
                        } else {
                            Music.state = MUSIC_PLAYBACK_ACTIVE;
                            NuSound3StopStereoStream(1 - Music.primary_stream);
                            NuSound3ResumeStereoStream(Music.primary_stream);
                        }
                        Music.transition = 1.0f;
                        NuSound3SetStereoStreamVolume(
                            Music.primary_stream,
                            static_cast<i32>(static_cast<f32>(g_music[Music.current_track].index) * MusicVolume));
                        Music.transition_frames = 0;
                        Music.requested_track = -1;
                    }
                }
            }

        update_secondary_stream:
            UpdateSecondaryMusicStream();
            return;
        }
        default:
            return;
    }
}

    i32 MusicState(void) {
        return Music.state;
    }

    i32 MusicSeeking(void) {
        if (fake_seeking != 0 || Music.pause_requested) {
            return 1;
        }
        if (NuSound3GetStereoStreamStatus(0) == NUSOUND_STEREO_STREAM_FINISHED) {
            return 1;
        }
        return NuSound3GetStereoStreamStatus(1) == NUSOUND_STEREO_STREAM_FINISHED;
    }

}

i32 SolveQuadratic(f32 a, f32 b, f32 c, f32 *first, f32 *second) {
    if (a == 0.0f) {
        if (b == 0.0f)
            return 0;
        *first = *second = -c / b;
        return 1;
    }
    const f32 four_ac = 4.0f * a * c;
    const f32 b_squared = b * b;
    if (four_ac > b_squared)
        return 0;
    if (four_ac == b_squared) {
        *first = *second = -b / (a + a);
        return 1;
    }
    const f32 root = NuFsqrt(b_squared - four_ac);
    *first = (-b - root) / (a + a);
    *second = (root - b) / (a + a);
    return 1;
}

void DebrisGetControlStackLock() {
    while (control_stack_lock != 0) {
        NuThreadSleep(1);
    }
    control_stack_lock = 1;
}

void DebrisReleaseControlStackLock() {
    control_stack_lock = 0;
}

NUMTL *CreateCopyMat(NUMTL *source, i32 enable_uv_mode, i32 alpha_mode, i32 depth_mode, i32 filter_mode) {
    if (source == NULL) {
        return NULL;
    }

    NUMTL *material = NuMtlCreate3D(1);
    material->diffuse_color.r = 1.0f;
    material->diffuse_color.g = 1.0f;
    material->diffuse_color.b = 1.0f;
    material->attribs.cull_mode = 2;
    material->attribs.z_mode = static_cast<u32>(depth_mode) & 3;
    material->attribs.filter_mode = static_cast<u32>(filter_mode) & 3;
    material->attribs.alpha_mode = static_cast<u32>(alpha_mode) & 0xf;
    material->opacity = 0.999f;
    if (enable_uv_mode != 0) {
        material->attribs.uv_mode = 1;
    }
    material->attribs.unknown_1_1_2 = 1;
    material->attribs.unknown_1_4_8 = 1;
    material->tex_id = source->tex_id;
    material->sort_pri = source->sort_pri;
    material->attribs.alpha_fail = 1;
    NuMtlUpdate(material);
    return material;
}

extern "C" {
    void DebrisReserveTrashableSpace(VARIPTR *buffer, VARIPTR, i32 chunk_count, i32 glass_chunk_count) {
        if (debris_trash_space == NULL) {
            buffer->addr = ALIGN(buffer->addr, 0x80);
            debris_trash_space = buffer->void_ptr;
            debrischunks = chunk_count;
            debrischunksglass = glass_chunk_count;
            buffer->addr += chunk_count * 0x430 + glass_chunk_count * 0x1b0 + EDPP_MAX_DMADEBTYPES * 0xa4c;
            debris_trash_size = buffer->addr - reinterpret_cast<usize>(debris_trash_space);
        }
    }

    void DebrisTrashableSetup(VARIPTR *buffer, VARIPTR *) {
        if (debris_setup_called == 0) {
            return;
        }

        u8 *cursor = static_cast<u8 *>(debris_trash_space);
        if (cursor == NULL) {
            if (buffer == NULL) {
                return;
            }
            buffer->addr = ALIGN(buffer->addr, 0x10);
            cursor = buffer->u8_ptr;
        }

        memset(debris_chunk_controls, 0,
               static_cast<usize>(debrischunks + debrischunksglass) * 2 * sizeof(debris_chunk_control_s));
        memset(freechunkcontrols, 0,
               static_cast<usize>(debrischunks + debrischunksglass) * 2 * sizeof(debris_chunk_control_s *));
        memset(freedebchunks, 0, static_cast<usize>(debrischunks) * sizeof(dma_particle_chunk_s *));
        memset(freedebchunksglass, 0, static_cast<usize>(debrischunksglass) * sizeof(dma_particle_chunk_s *));
        memset(ParticleChunkToRender, 0,
               static_cast<usize>(debrischunks + debrischunksglass) * sizeof(particlechunkrendertype_s));

        i32 size;
        for (i32 i = 0; i < debrischunks; ++i) {
            freedebchunks[i] = CreateDmaParticleSet(cursor, &size);
            cursor += size;
        }
        for (i32 i = 0; i < debrischunksglass; ++i) {
            freedebchunksglass[i] = CreateDmaParticleSetGlass(cursor, &size);
            cursor += size;
        }

        freedebchkptr = 0;
        freedebchkptrg = 0;
        for (i32 i = 0; i < EDPP_MAX_DMADEBTYPES; ++i) {
            DmaDebTypes[i] = CreateDmaPartEffectList(cursor, &size);
            cursor += size;
        }

        if (debris_trash_space == NULL) {
            debris_trash_space = buffer->void_ptr;
            debris_trash_size = static_cast<usize>(cursor - buffer->u8_ptr);
            buffer->u8_ptr = cursor;
        }

        const i32 chunk_count = debrischunks + debrischunksglass;
        debris_chunk_control_stack[0] = NULL;
        debris_chunk_control_stack[1] = NULL;
        for (i32 i = 0; i < chunk_count * 2; ++i) {
            freechunkcontrols[i] = &debris_chunk_controls[i];
        }
        freechunkcontrolsptr = 0;
        for (i32 i = 0; i < chunk_count; ++i) {
            ParticleChunkToRender[i].particle_chunk = NULL;
            ParticleChunkToRender[i].effect = NULL;
            ParticleChunkToRender[i].key = NULL;
            ParticleChunkToRender[i].previous = NULL;
            ParticleChunkToRender[i].next = NULL;
        }
        ParticleChunkRenderStack[0] = NULL;
        ParticleChunkRenderStack[1] = NULL;
        ParticleChunkRenderStack[2] = NULL;
        ParticleChunkRenderStack[3] = NULL;
        ParticleChunkRenderStack[4] = NULL;
    }

    void DebrisSetup2(VARIPTR *buffer, VARIPTR buffer_end, VARIPTR *trash_buffer, VARIPTR trash_end, char *texture_name,
                      i32 chunk_count, i32 glass_chunk_count, i32 key_count, i32 effect_count) {
        if (debris_trash_space == NULL) {
            debrischunks = chunk_count;
            debrischunksglass = glass_chunk_count;
        }
        debris_setup_called = 1;
        maxdebkeys = key_count;
        EDPP_MAX_TYPES = effect_count;
        Debris_Init = 1;
        NuRegisterEndFrameCallBackFn(DebrisProcessTimeSlip);

        buffer->addr = ALIGN(buffer->addr, 0x10);
        const i32 regular_chunks = debrischunks;
        const i32 glass_chunks = debrischunksglass;
        const i32 total_chunks = regular_chunks + glass_chunks;
        debris_chunk_controls = reinterpret_cast<debris_chunk_control_s *>(buffer->addr);
        buffer->addr += static_cast<usize>(total_chunks) * 2 * sizeof(debris_chunk_control_s);
        freechunkcontrols = reinterpret_cast<debris_chunk_control_s **>(buffer->addr);
        buffer->addr += static_cast<usize>(total_chunks) * 2 * sizeof(debris_chunk_control_s *);
        freedebchunks = reinterpret_cast<dma_particle_chunk_s **>(buffer->addr);
        buffer->addr += static_cast<usize>(regular_chunks) * sizeof(dma_particle_chunk_s *);
        freedebchunksglass = reinterpret_cast<dma_particle_chunk_s **>(buffer->addr);
        buffer->addr += static_cast<usize>(glass_chunks) * sizeof(dma_particle_chunk_s *);
        ParticleChunkToRender = reinterpret_cast<particlechunkrendertype_s *>(buffer->addr);
        buffer->addr += static_cast<usize>(total_chunks) * sizeof(particlechunkrendertype_s);

        buffer->addr = ALIGN(buffer->addr, 0x10);
        debkeydata = reinterpret_cast<debkeydatatype_s *>(buffer->addr);
        buffer->addr += static_cast<usize>(maxdebkeys) * sizeof(debkeydatatype_s);
        freedebkeys = reinterpret_cast<i16 *>(buffer->addr);
        buffer->addr += static_cast<usize>(maxdebkeys) * sizeof(i16);
        effecttypes = reinterpret_cast<debinftype *>(buffer->addr);
        buffer->addr += static_cast<usize>(EDPP_MAX_TYPES) * sizeof(debinftype);
        debtab = reinterpret_cast<debinftype **>(buffer->addr);
        buffer->addr += static_cast<usize>(EDPP_MAX_TYPES) * sizeof(debinftype *);
        DmaDebTypes = reinterpret_cast<PartHeader **>(buffer->addr);
        buffer->addr += static_cast<usize>(EDPP_MAX_DMADEBTYPES) * sizeof(PartHeader *);
        spherecolldata = reinterpret_cast<u32 *>(buffer->addr);
        buffer->addr += static_cast<usize>(maxdebkeys) * 2 * sizeof(u32);
        toruscolldata = reinterpret_cast<u32 *>(buffer->addr);
        buffer->addr += static_cast<usize>(maxdebkeys) * 2 * sizeof(u32);
        debscale = reinterpret_cast<debscale_s *>(buffer->addr);
        buffer->addr += static_cast<usize>(EDPP_SCALE_TYPES) * sizeof(debscale_s);

        memset(freedebkeys, 0, static_cast<usize>(maxdebkeys) * sizeof(i16));
        memset(debkeydata, 0, static_cast<usize>(maxdebkeys) * sizeof(debkeydatatype_s));
        memset(effecttypes, 0, static_cast<usize>(EDPP_MAX_TYPES) * sizeof(debinftype));
        memset(debtab, 0, static_cast<usize>(EDPP_MAX_TYPES) * sizeof(debinftype *));
        memset(debscale, 0, static_cast<usize>(EDPP_SCALE_TYPES) * sizeof(u32));

        for (i32 i = 0; i < maxdebkeys; ++i) {
            spherecolldata[i * 2] = static_cast<u32>(i);
            toruscolldata[i * 2] = static_cast<u32>(i);
            spherecolldata[i * 2 + 1] = 3;
            toruscolldata[i * 2 + 1] = 3;
        }

        effecttypes[0] = nulleffecttype;
        debtab[0] = &effecttypes[0];
        edpp_types_used = 1;
        numspherecolldata = maxdebkeys;
        numtoruscolldata = maxdebkeys;

        DebMat[0] = CreateAlphaBlendTexture(buffer, buffer_end, texture_name, 1, 2, 0x100, 0);
        const i16 texture_id = DebMat[0]->tex_id;
        DebMat[0]->attribs.z_mode = 1;
        DebMat[0]->attribs.alpha_test = 1;
        NuMtlUpdate(DebMat[0]);
        DebMat[1] = CreateCopyMat(DebMat[0], 0, 0, 3, 0);
        DebMat[2] = CreateCopyMat(DebMat[0], 1, 1, 1, 1);
        DebMat[3] = CreateCopyMat(DebMat[0], 1, 3, 1, 1);
        DebMat[4] = CreateCopyMat(DebMat[0], 0, 1, 1, 1);
        DebMat[5] = CreateCopyMat(DebMat[0], 0, 2, 1, 1);
        DebMat[6] = CreateCopyMat(DebMat[0], 0, 0, 0, 1);
        DebMat[0]->shader_desc.vtx_desc.unknown_2_16 = 1;
        DebMat[1]->shader_desc.vtx_desc.unknown_2_16 = 1;
        DebMat[2]->shader_desc.vtx_desc.unknown_2_16 = 1;
        DebMat[3]->shader_desc.vtx_desc.unknown_2_16 = 1;
        DebMat[4]->shader_desc.vtx_desc.unknown_2_16 = 1;
        DebMat[5]->shader_desc.vtx_desc.unknown_2_16 = 1;
        DebMat[6]->shader_desc.vtx_desc.unknown_2_16 = 1;
        DebMat[6]->tex_id = texture_id;
        DebMat[5]->tex_id = texture_id;
        DebMat[4]->tex_id = texture_id;
        DebMat[3]->tex_id = texture_id;
        DebMat[2]->tex_id = texture_id;
        DebMat[1]->tex_id = texture_id;
        DebMat[0]->tex_id = texture_id;

        DebMat[7] = NuMtlCreateEx3D(1, 2);
        NUMTL *glass = DebMat[7];
        glass->diffuse_color = {1.0f, 1.0f, 1.0f};
        glass->opacity = 0.999f;
        f32 glass_parameter = 0.25f;
        memcpy(glass->filler3, &glass_parameter, sizeof(glass_parameter));
        glass->tex_id = -1;
        glass->shader_desc.vtx_desc.unknown_2_16 = 1;
        glass->attribs.alpha_mode = 1;
        glass->attribs.filter_mode = 0;
        glass->attribs.unknown_1_1_2 = 1;
        glass->attribs.unknown_1_4_8 = 1;
        glass->attribs.cull_mode = 2;
        glass->attribs.z_mode = 1;
        glass->attribs.unknown_2_1_2 = 2;
        glass->attribs.alpha_fail = 1;
        glass->attribs.unknown_2_4 = 1;
        glass->sort_pri = 128;
        glass->particle_type_tag = -105;
        NuMtlUpdate(glass);
        DebMat[8] = CreateCopyMat(DebMat[0], 0, 6, 0, 1);

        for (debinftype **entry = debtab; *entry != NULL; ++entry) {
            debinftype *effect = *entry;
            if (effect->field_0ab == 0)
                effect->field_0ab = 1;
            f32 frame_rate = static_cast<f32>((effect->field_0a8 * 60) / static_cast<i8>(effect->field_0ab));
            u32 packed;
            memcpy(&packed, &frame_rate, sizeof(packed));
            packed = (packed & 0xfffff800) + ((effect->field_0a8 * (static_cast<i8>(effect->field_0aa) - 1)) & 0x3ff);
            memcpy(&effect->field_0ac, &packed, sizeof(packed));
            effect->alpha_keys[0].value /= effect->particle_lifetime;
            effect->texture_u0 += 524288.0f;
            effect->texture_u1 += 524288.0f;
            effect->texture_v0 += 524288.0f;
            effect->texture_v1 += 524288.0f;
        }
        for (i32 i = 0; i < EDPP_MAX_TYPES; ++i)
            effecttypes[i].native_data = NULL;
        freeDmaDebType = 0;
        if (debris_suspended == 0) {
            if (trash_buffer != NULL)
                DebrisTrashableSetup(trash_buffer, &trash_end);
            else
                DebrisTrashableSetup(buffer, &buffer_end);
        }
        for (i32 i = 0; i < maxdebkeys; ++i)
            freedebkeys[i] = static_cast<i16>(i);
        for (i32 i = 0; i < maxdebkeys; ++i) {
            debkeydatatype_s *key = &debkeydata[i];
            key->field_184 = 0;
            key->field_18a = 0;
            key->emitter_rotation_x = 0;
            key->emitter_rotation_y = 0;
            key->field_1d4 = 0;
            key->effect_index = 0;
            key->allocation_index = -1;
        }

        NuMtxSetIdentity(&xzfacingmtx);
        NuMtxRotateXInline(&xzfacingmtx, -0x4000);
    }

    // DebrisSetup @0x34c7d0 is only the argument-shuffling wrapper around the
    // real setup routine.  Keep the call shape visible; DebrisSetup2 owns the
    // arena and all of the ancillary debris tables.
    void DebrisSetup(VARIPTR *p1, VARIPTR p2, char *p3, i32 p4, i32 p5, i32 p6) {
        DebrisSetup2(p1, p2, p1, p2, p3, p4, 0x20, p5, p6);
    }

}

void AddChunkToRenderStack(particlechunkrendertype_s *chunk, particlechunkrendertype_s **stack) {
    chunk->next = NULL;
    chunk->previous = NULL;

    particlechunkrendertype_s *current = *stack;
    if (current != NULL) {
        const u16 priority = static_cast<u16>(chunk->render_priority);
        const u16 current_priority = static_cast<u16>(current->render_priority);
        if (priority <= current_priority &&
            (priority != current_priority || chunk->effect->particle_type > current->effect->particle_type)) {
            particlechunkrendertype_s *next = current->next;
            while (next != NULL) {
                const u16 next_priority = static_cast<u16>(next->render_priority);
                if (__builtin_expect(next_priority <= priority &&
                    (priority != next_priority || chunk->effect->particle_type <= next->effect->particle_type), 0)) {
                    break;
                }
                current = next;
                next = next->next;
            }
            current->next = chunk;
            chunk->previous = current;
            chunk->next = next;
            if (next != NULL) {
                next->previous = chunk;
            }
            return;
        }
        chunk->next = current;
        current->previous = chunk;
    }
    *stack = chunk;
}

void RemoveChunkFromRenderStack(particlechunkrendertype_s *chunk, particlechunkrendertype_s **stack) {
    if (*stack == chunk) {
        particlechunkrendertype_s *next = chunk->next;
        *stack = next;
        if (next != NULL) {
            next->previous = NULL;
        }
    } else if (chunk->previous != NULL) {
        chunk->previous->next = chunk->next;
        if (chunk->next != NULL) {
            chunk->next->previous = chunk->previous;
        }
    }
    chunk->previous = NULL;
    chunk->next = NULL;
}

extern "C" {
    void SortDebrisRenderStack(void) {
        if (--debris_sort_delay > 0) {
            return;
        }
        debris_sort_delay = 6;

        i32 stack_index = debris_sort_this_stack;
        while (ParticleChunkRenderStack[stack_index] == NULL) {
            if (++stack_index >= 5) {
                stack_index = 0;
            }
            if (stack_index == debris_sort_this_stack) {
                break;
            }
        }
        debris_sort_this_stack = stack_index;

        particlechunkrendertype_s *chunk = ParticleChunkRenderStack[stack_index];
        if (chunk == NULL) {
            return;
        }
        while (chunk->next != NULL) {
            particlechunkrendertype_s *next = chunk->next;
            const u16 next_priority = static_cast<u16>(next->render_priority);
            const u16 priority = static_cast<u16>(chunk->render_priority);
            if (priority < next_priority ||
                (priority == next_priority &&
                 static_cast<i8>(chunk->effect->particle_type) > static_cast<i8>(next->effect->particle_type))) {
                RemoveChunkFromRenderStack(next, &ParticleChunkRenderStack[stack_index]);
                AddChunkToRenderStack(next, &ParticleChunkRenderStack[debris_sort_this_stack]);
                return;
            }
            chunk = next;
        }
    }

    void UpdateDebrisRenderStackPriority(void) {
        if (--debris_update_delay > 0) {
            return;
        }
        debris_update_delay = 6;

        i32 stack_index = debris_update_this_stack;
        while (ParticleChunkRenderStack[stack_index] == NULL) {
            if (++stack_index >= 5) {
                stack_index = 0;
            }
            if (stack_index == debris_update_this_stack) {
                debris_update_this_stack = stack_index;
                if (ParticleChunkRenderStack[stack_index] == NULL) {
                    return;
                }
                break;
            }
        }
        debris_update_this_stack = stack_index;

        particlechunkrendertype_s *chunk = ParticleChunkRenderStack[debris_sort_this_stack];
        while (chunk != NULL) {
            debkeydatatype_s *key = chunk->key;
            if (key != NULL) {
                if (key->timed_flags != 0) {
                    const f32 priority = static_cast<u16>(key->render_priority) + key->cutoff_distance * 25.0f;
                    i32 updated_priority = -1;
                    if (!(priority > 65535.0f)) {
                        updated_priority = static_cast<i32>(priority);
                    }
                    chunk->render_priority = static_cast<i16>(updated_priority);
                } else {
                    chunk->render_priority = key->render_priority;
                }
            }
            chunk = chunk->next;
        }
    }

    i32 DebAlloc(void) {
        if (freedebkeyptr >= maxdebkeys) {
            return -1;
        }

        const i32 slot = freedebkeys[freedebkeyptr++];
        debkeydatatype_s *key = debkeydata + slot;
        for (i32 i = 0; i < 32; ++i) {
            key->particle_chunks[i] = NULL;
        }
        key->allocated_chunk_count = 0;
        key->field_18a = 0;
        key->particle_count = 0;
        key->previous_allocated_chunk_count = 0;
        key->previous_particle_count = 0;
        key->field_2f2 = -1;
        key->gscene = NULL;
        key->controlled_chunk_count = 0;
        key->field_2f4 = 1;
        key->field_2f6 = 1;
        key->user_data = NULL;
        key->field_2f7 = 1;
        key->allocation_index = slot;
        key->field_2fa = 0;
        return slot;
    }

}

void AddChunkControlToStack(debris_chunk_control_s *control, debris_chunk_control_s **stack) {
    debris_chunk_control_s *current = *stack;
    while (current != NULL && current->expiry_time < control->expiry_time) {
        stack = &current->next;
        current = current->next;
    }
    control->next = current;
    *stack = control;
}

extern "C" {
    void DebReAlloc2(debkeydatatype_s *key) {
        const i32 old_chunk_count = key->allocated_chunk_count;
        const i32 requested_chunk_count = key->previous_allocated_chunk_count;
        debinftype *effect = debtab[key->effect_index];
        const i32 additional_chunks = requested_chunk_count - old_chunk_count;
        if (additional_chunks == 0) {
            return;
        }

        const bool glass = effect->particle_type == 7;
        if (additional_chunks > 0) {
            if (glass) {
                i32 &free_chunk_count = freedebchkptrg;
                const i32 available_chunk_count = debrischunksglass;
                dma_particle_chunk_s **free_chunks = freedebchunksglass;
                if (available_chunk_count <= free_chunk_count + additional_chunks) {
                    return;
                }

                const i32 particles_per_chunk = 12;
                for (i32 i = 0; i < additional_chunks; ++i) {
                    dma_particle_chunk_s *chunk = free_chunks[free_chunk_count + i];
                    key->particle_chunks[old_chunk_count + i] = chunk;
                    key->particle_chunks[old_chunk_count + i]->particles[0].start_time = 0.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[0].inverse_lifetime = 32768.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[1].start_time = 0.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[1].inverse_lifetime = 32768.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[2].start_time = 0.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[2].inverse_lifetime = 32768.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[3].start_time = 0.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[3].inverse_lifetime = 32768.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[4].start_time = 0.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[4].inverse_lifetime = 32768.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[5].start_time = 0.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[5].inverse_lifetime = 32768.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[6].start_time = 0.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[6].inverse_lifetime = 32768.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[7].start_time = 0.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[7].inverse_lifetime = 32768.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[8].start_time = 0.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[8].inverse_lifetime = 32768.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[9].start_time = 0.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[9].inverse_lifetime = 32768.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[10].start_time = 0.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[10].inverse_lifetime = 32768.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[11].start_time = 0.0f;
                    key->particle_chunks[old_chunk_count + i]->particles[11].inverse_lifetime = 32768.0f;
                }

                if (old_chunk_count == 0) {
                    const i32 render_chunk_count = debrischunks + debrischunksglass;
                    particlechunkrendertype_s *render_chunk = NULL;
                    for (i32 i = 0; i < render_chunk_count; ++i) {
                        if (ParticleChunkToRender[i].particle_chunk == NULL) {
                            render_chunk = &ParticleChunkToRender[i];
                            break;
                        }
                    }
                    if (render_chunk != NULL) {
                        render_chunk->particle_chunk = key->particle_chunks[0];
                        render_chunk->key = key;
                        render_chunk->effect = effect;
                        render_chunk->render_priority = key->render_priority;
                        if (key->field_2f6 != 0) {
                            AddChunkToRenderStack(render_chunk, &ParticleChunkRenderStack[effect->time_group]);
                        }
                    }
                }

                key->allocated_chunk_count += additional_chunks;
                if (key->allocated_chunk_count == key->previous_allocated_chunk_count)
                    key->particle_count = key->previous_particle_count;
                else
                    key->particle_count += 12;
                free_chunk_count += additional_chunks;
                LinkDmaParticalSets(key->particle_chunks, key->allocated_chunk_count);
            } else {
                i32 &free_chunk_count = freedebchkptr;
                const i32 available_chunk_count = debrischunks;
                dma_particle_chunk_s **free_chunks = freedebchunks;
                if (available_chunk_count <= free_chunk_count + additional_chunks) {
                    return;
                }

                const i32 particles_per_chunk = 32;
                for (i32 i = 0; i < additional_chunks; ++i) {
                    dma_particle_chunk_s *chunk = free_chunks[free_chunk_count + i];
                    key->particle_chunks[old_chunk_count + i] = chunk;
                    for (i32 particle_index = 0; particle_index < particles_per_chunk; ++particle_index) {
                        chunk->particles[particle_index].start_time = 0.0f;
                        chunk->particles[particle_index].inverse_lifetime = 32768.0f;
                    }
                }

                if (old_chunk_count == 0) {
                    const i32 render_chunk_count = debrischunks + debrischunksglass;
                    particlechunkrendertype_s *render_chunk = NULL;
                    for (i32 i = 0; i < render_chunk_count; ++i) {
                        if (ParticleChunkToRender[i].particle_chunk == NULL) {
                            render_chunk = &ParticleChunkToRender[i];
                            break;
                        }
                    }
                    if (render_chunk != NULL) {
                        render_chunk->effect = effect;
                        render_chunk->particle_chunk = key->particle_chunks[0];
                        render_chunk->key = key;
                        render_chunk->render_priority = key->render_priority;
                        if (key->field_2f6 != 0) {
                            AddChunkToRenderStack(render_chunk, &ParticleChunkRenderStack[effect->time_group]);
                        }
                    }
                }

                key->allocated_chunk_count += additional_chunks;
                if (key->allocated_chunk_count == key->previous_allocated_chunk_count)
                    key->particle_count = key->previous_particle_count;
                else
                    key->particle_count += 32;
                free_chunk_count += additional_chunks;
                LinkDmaParticalSets(key->particle_chunks, key->allocated_chunk_count);
            }
            return;
        }

        const i32 removed_chunk_count = -additional_chunks;
        if ((debrischunks + debrischunksglass) * 2 < freechunkcontrolsptr + removed_chunk_count) {
            return;
        }

        DebrisGetControlStackLock();
        for (i32 i = 0; i < removed_chunk_count; ++i) {
            debris_chunk_control_s *control = freechunkcontrols[freechunkcontrolsptr];
            control->particle_chunk = key->particle_chunks[key->allocated_chunk_count + additional_chunks + i];
            control->active = effect->particle_type == 7 ? 7 : 0;
            const bool panel_time = effect->time_group == 4;
            debinftype *current_effect = debtab[key->effect_index];
            control->expiry_time = current_effect->particle_lifetime + (panel_time ? panelglobaltime : globaltime) +
                                   static_cast<i8>(current_effect->trail_count) * current_effect->trail_time;
            AddChunkControlToStack(control, &debris_chunk_control_stack[panel_time]);
            ++freechunkcontrolsptr;
        }
        DebrisReleaseControlStackLock();

        particlechunkrendertype_s *render_chunk = NULL;
        if (removed_chunk_count != key->allocated_chunk_count) {
            LinkDmaParticalSets(&key->particle_chunks[key->allocated_chunk_count + additional_chunks],
                                removed_chunk_count);
            for (i32 i = 0; i < debrischunks + debrischunksglass; ++i) {
                if (ParticleChunkToRender[i].particle_chunk == NULL) {
                    render_chunk = &ParticleChunkToRender[i];
                    break;
                }
            }
            if (render_chunk != NULL) {
                render_chunk->effect = debtab[key->effect_index];
                render_chunk->particle_chunk = key->particle_chunks[key->allocated_chunk_count + additional_chunks];
                render_chunk->key = NULL;
                render_chunk->effect_orientation = key->effect_orientation;
                render_chunk->render_priority = key->render_priority;
                render_chunk->position.x = key->position.x;
                render_chunk->position.y = key->position.y;
                render_chunk->position.z = key->position.z;
                if (key->field_2f6 != 0) {
                    AddChunkToRenderStack(render_chunk, &ParticleChunkRenderStack[render_chunk->effect->time_group]);
                }
            }
            render_chunk = NULL;
        } else {
            for (i32 i = 0; i < debrischunks + debrischunksglass; ++i) {
                if (ParticleChunkToRender[i].particle_chunk == key->particle_chunks[0]) {
                    render_chunk = &ParticleChunkToRender[i];
                    break;
                }
            }
        }

        if (render_chunk != NULL) {
            render_chunk->effect = debtab[key->effect_index];
            render_chunk->key = NULL;
            render_chunk->effect_orientation = key->effect_orientation;
            render_chunk->position.x = key->position.x;
            render_chunk->position.y = key->position.y;
            render_chunk->position.z = key->position.z;
            render_chunk->render_priority = key->render_priority;
        }

        for (i32 i = additional_chunks; i < 0; ++i) {
            key->particle_chunks[key->allocated_chunk_count + i] = NULL;
        }
        key->allocated_chunk_count = key->previous_allocated_chunk_count;
        key->particle_count = key->previous_particle_count;
        if (__builtin_expect(key->previous_particle_count != 0, 0)) {
            LinkDmaParticalSets(key->particle_chunks, key->previous_allocated_chunk_count);
        }
        return;
    }

    void DebReAlloc(debkeydatatype_s *key, i32 particle_count) {
        debinftype *effect = debtab[key->effect_index];
        key->previous_particle_count = static_cast<i16>(particle_count);
        if (effect->particle_type == 7)
            key->previous_allocated_chunk_count = static_cast<i16>((particle_count + 11) / 12);
        else
            key->previous_allocated_chunk_count = static_cast<i16>((particle_count + 31) / 32);
        if (key->previous_allocated_chunk_count > 32) {
            key->previous_allocated_chunk_count = 32;
            key->previous_particle_count = effect->particle_type == 7 ? 0x180 : 0x400;
        }
        if (key->allocated_chunk_count == key->previous_allocated_chunk_count) {
            key->particle_count = key->previous_particle_count;
        } else if (key->previous_allocated_chunk_count != 0 && key->allocated_chunk_count == 0) {
            DebReAlloc2(key);
        }
    }

}

static void UpdateTotalPtls(debinftype *effect) {
    f32 active_time = 0.0f;
    f32 elapsed_time = 0.0f;
    while (effect->particle_lifetime > elapsed_time) {
        f32 remaining_time = effect->particle_lifetime - elapsed_time;
        f32 emission_time = effect->emission_period_random + effect->emission_pause;
        if (remaining_time < emission_time) {
            active_time += remaining_time;
            elapsed_time += remaining_time;
        } else {
            active_time += emission_time;
            elapsed_time += emission_time;
        }

        remaining_time = effect->particle_lifetime - elapsed_time;
        if (remaining_time < effect->emission_pause_random) {
            elapsed_time += remaining_time;
        } else {
            elapsed_time += effect->emission_pause_random;
        }
    }

    i16 particle_count = static_cast<i16>(static_cast<i32>(static_cast<f32>(effect->frequency) *
                                                           (active_time / elapsed_time) * effect->particle_lifetime));
    if (particle_count < 1) {
        particle_count = 1;
    }
    effect->max_particles = static_cast<i16>(particle_count * (effect->trail_count + 1));

    for (i32 i = 0; i < 512; ++i) {
        i32 instance_id = edpp_ptls[i].instance_id;
        if (instance_id == 99999) {
            continue;
        }
        if (instance_id == -1) {
            continue;
        }

        debkeydatatype_s *key = &debkeydata[instance_id];
        if (debtab[key->effect_index] == effect) {
            DebReAlloc(key, effect->max_particles);
        }
    }
}

