static void cbPtlAddEffect(eduimenu_s *menu, eduiitem_s *, u32) {
    if (edpp_types_used >= EDPP_MAX_TYPES) {
        eduiCreateMessageMenu(menu, "Out of particle slots", 0);
        return;
    }

    for (i32 index = 1; index < EDPP_MAX_TYPES; ++index) {
        if (debtab[index] == NULL) {
            debtab[index] = &effecttypes[index];
            memcpy(debtab[index], debtab[0], sizeof(debinftype));
            debtab[index]->status = 1;
            sprintf(debtab[index]->name, "New%d", index);
            debtab[index]->category = edpp_effect_list;
            if (edpp_effect_list == 0) {
                debtab[index]->page = edbits_particle_general_page;
                edpp_page_used[edbits_particle_general_page] = 1;
            } else if (edpp_effect_list == 5) {
                debtab[index]->page = edbits_particle_char_page;
                edpp_page_used[edbits_particle_char_page] = 1;
            } else if (edpp_effect_list == 1) {
                debtab[index]->page = edbits_particle_level_page;
                edpp_page_used[edbits_particle_level_page] = 1;
            }
            edpp_create_type = index;
            ++edpp_types_used;
            UpdateTotalPtls(debtab[index]);
            break;
        }
    }
    eduimenu_s *parent = menu->parent;
    if (parent != NULL)
        eduiMenuDetach(menu);
    if (menu->callback != NULL)
        menu->callback(menu, parent);
}

uv1deb *GenDebIndexBounceXZ(debkeydatatype_s *key, debinftype *effect, float time) {
    NUVEC normal = {1.0f, 0.0f, 0.0f};
    if (key->field_18a >= key->particle_count)
        key->field_18a = 0;
    if (effect->particle_type == 7)
        return NULL;
    dma_particle_chunk_s *chunk = key->particle_chunks[key->field_18a / 32];
    dma_particle_s *particle = &chunk->particles[key->field_18a % 32];
    particle->start_time = time;
    key->emission_epoch = time;
    particle->inverse_lifetime = 64.0f / effect->particle_lifetime;

    NUVEC vector;
    f32 random = NuRandFloatSeeded(&debrisseed);
    vector.x = (random + random) * effect->field_058 - effect->field_058;
    random = NuRandFloatSeeded(&debrisseed);
    vector.y = (random + random) * effect->field_05c - effect->field_05c;
    random = NuRandFloatSeeded(&debrisseed);
    vector.z = (random + random) * effect->field_060 - effect->field_060;
    NuVecMtxTransformVU0(&vector, &vector, &key->emitter_orientation);
    particle->position.x = vector.x;
    particle->position.y = vector.y;
    particle->position.z = vector.z;
    random = NuRandFloatSeeded(&debrisseed);
    vector.x = (random + random) * effect->field_04c - effect->field_04c;
    random = NuRandFloatSeeded(&debrisseed);
    vector.y = (random + random) * effect->field_050 - effect->field_050 + effect->field_048;
    random = NuRandFloatSeeded(&debrisseed);
    vector.z = (random + random) * effect->field_054 - effect->field_054;
    NuVecMtxTransformVU0(&vector, &vector, &key->emitter_orientation);
    particle->momentum.x = vector.x;
    particle->momentum.y = vector.y;
    particle->momentum.z = vector.z;

    NuVecRotateY(&normal, &normal, key->reflection_y);
    NUVEC plane_position;
    NuVecScale(&plane_position, &normal, key->collision_plane);
    NUVEC end_position;
    end_position.x = particle->momentum.x * effect->particle_lifetime + particle->position.x;
    end_position.y = 0.0f;
    end_position.z = effect->particle_lifetime * particle->momentum.z + particle->position.z;
    NUVEC start_delta, end_delta;
    NuVecSub(&start_delta, &plane_position, &particle->position);
    NuVecSub(&end_delta, &plane_position, &end_position);
    f32 start_distance = start_delta.x * normal.x + start_delta.z * normal.z;
    f32 end_distance = normal.x * end_delta.x + normal.z * end_delta.z;
    if ((start_distance < 0.0f && end_distance > 0.0f) || (start_distance > 0.0f && end_distance < 0.0f)) {
        f32 lifetime = effect->particle_lifetime;
        DebrisGetControlStackLock();
        if (freechunkcontrolsptr < debrischunks + debrischunksglass) {
            f32 collision_time = (0.0f - start_distance) / (end_distance - start_distance) * lifetime;
            freechunkcontrols[freechunkcontrolsptr]->particle_chunk = chunk;
            freechunkcontrols[freechunkcontrolsptr]->expiry_time = time + collision_time;
            freechunkcontrols[freechunkcontrolsptr]->active = 6;
            freechunkcontrols[freechunkcontrolsptr]->owner = NULL;
            freechunkcontrols[freechunkcontrolsptr]->effect_index = key->effect_index;
            freechunkcontrols[freechunkcontrolsptr]->rotation_y = key->reflection_y;
            freechunkcontrols[freechunkcontrolsptr]->field_01e = 0;
            freechunkcontrols[freechunkcontrolsptr]->collision_plane = key->collision_plane;
            freechunkcontrols[freechunkcontrolsptr]->restitution = key->reflection_scale;
            freechunkcontrols[freechunkcontrolsptr]->collision_time = collision_time;
            freechunkcontrols[freechunkcontrolsptr]->particle_index = key->field_18a % 32;
            AddChunkControlToStack(freechunkcontrols[freechunkcontrolsptr], &debris_chunk_control_stack[0]);
            ++freechunkcontrolsptr;
        }
        DebrisReleaseControlStackLock();
    }
    if (key->momentum_adjuster != NULL)
        key->momentum_adjuster(key, effect, reinterpret_cast<uv1deb *>(particle));
    ++key->field_18a;
    particle->position.x += key->emission_position.x;
    particle->position.y += key->emission_position.y;
    particle->position.z += key->emission_position.z;
    particle->momentum.x += key->momentum.x;
    particle->momentum.y += key->momentum.y;
    particle->momentum.z += key->momentum.z;
    if (effect->native_data == NULL)
        GenericDebinfoDmaTypeUpdate(effect);
    return reinterpret_cast<uv1deb *>(particle);
}

uv1deb *GenDebIndexBounceY(debkeydatatype_s *key, debinftype *effect, float time) {
    if (key->field_18a >= key->particle_count)
        key->field_18a = 0;
    if (effect->particle_type == 7)
        return NULL;
    dma_particle_chunk_s *chunk = key->particle_chunks[key->field_18a / 32];
    dma_particle_s *particle = &chunk->particles[key->field_18a % 32];
    particle->start_time = time;
    key->emission_epoch = time;
    particle->inverse_lifetime = 64.0f / effect->particle_lifetime;

    NUVEC vector;
    f32 random = NuRandFloatSeeded(&debrisseed);
    vector.x = (random + random) * effect->field_058 - effect->field_058;
    random = NuRandFloatSeeded(&debrisseed);
    vector.y = (random + random) * effect->field_05c - effect->field_05c;
    random = NuRandFloatSeeded(&debrisseed);
    vector.z = (random + random) * effect->field_060 - effect->field_060;
    NuVecMtxTransformVU0(&vector, &vector, &key->emitter_orientation);
    particle->position.x = vector.x;
    particle->position.y = vector.y;
    particle->position.z = vector.z;
    random = NuRandFloatSeeded(&debrisseed);
    vector.x = (random + random) * effect->field_04c - effect->field_04c;
    random = NuRandFloatSeeded(&debrisseed);
    vector.y = (random + random) * effect->field_050 - effect->field_050 + effect->field_048;
    random = NuRandFloatSeeded(&debrisseed);
    vector.z = (random + random) * effect->field_054 - effect->field_054;
    NuVecMtxTransformVU0(&vector, &vector, &key->emitter_orientation);
    particle->momentum.x = vector.x;
    particle->momentum.y = vector.y;
    particle->momentum.z = vector.z;

    f32 first, second;
    if (__builtin_expect(SolveQuadratic(effect->field_0a0, particle->momentum.y, particle->position.y - key->collision_plane, &first,
                       &second) &&
        (first > second ? first : second) > 0.0f && effect->particle_lifetime > (first > second ? first : second), 1)) {
        DebrisGetControlStackLock();
        if (freechunkcontrolsptr < debrischunks + debrischunksglass) {
            const f32 collision_time = first > second ? first : second;
            freechunkcontrols[freechunkcontrolsptr]->particle_chunk = chunk;
            freechunkcontrols[freechunkcontrolsptr]->active = 5;
            freechunkcontrols[freechunkcontrolsptr]->owner = NULL;
            freechunkcontrols[freechunkcontrolsptr]->effect_index = key->effect_index;
            freechunkcontrols[freechunkcontrolsptr]->expiry_time = time + collision_time;
            freechunkcontrols[freechunkcontrolsptr]->collision_plane = key->collision_plane;
            freechunkcontrols[freechunkcontrolsptr]->rotation_y = 0;
            freechunkcontrols[freechunkcontrolsptr]->field_01e = 0;
            freechunkcontrols[freechunkcontrolsptr]->restitution = key->reflection_scale;
            freechunkcontrols[freechunkcontrolsptr]->collision_time = collision_time;
            freechunkcontrols[freechunkcontrolsptr]->particle_index = key->field_18a % 32;
            AddChunkControlToStack(freechunkcontrols[freechunkcontrolsptr], &debris_chunk_control_stack[0]);
            ++freechunkcontrolsptr;
        }
        DebrisReleaseControlStackLock();
    }
    if (key->momentum_adjuster != NULL)
        key->momentum_adjuster(key, effect, reinterpret_cast<uv1deb *>(particle));
    ++key->field_18a;
    particle->position.x += key->emission_position.x;
    particle->position.y += key->emission_position.y;
    particle->position.z += key->emission_position.z;
    particle->momentum.x += key->momentum.x;
    particle->momentum.y += key->momentum.y;
    particle->momentum.z += key->momentum.z;
    if (effect->native_data == NULL)
        GenericDebinfoDmaTypeUpdate(effect);
    return reinterpret_cast<uv1deb *>(particle);
}

void RemoveChunkControlFromStack(debris_chunk_control_s *control, debris_chunk_control_s **stack) {
    debris_chunk_control_s **link = stack;
    while (*link != NULL) {
        if (*link == control) {
            *link = control->next;
            break;
        }
        link = &(*link)->next;
    }
    control->next = NULL;
}

void RemoveAnyChunkControls(i32 *chunk) {
    for (i32 i = 0; i < 2; ++i) {
        for (debris_chunk_control_s *control = debris_chunk_control_stack[i]; control != NULL;) {
            debris_chunk_control_s *next = control->next;
            if (control->particle_chunk == reinterpret_cast<dma_particle_chunk_s *>(chunk)) {
                RemoveChunkControlFromStack(control, &debris_chunk_control_stack[i]);
                --freechunkcontrolsptr;
                freechunkcontrols[freechunkcontrolsptr] = control;
                control->particle_chunk = NULL;
            }
            control = next;
        }
    }
}

