void edgraInstanceDestroy(i32 index) {
    if (edgra_nearest != -1 && GrassClumps[edgra_nearest].element_count != 1) {
        if (index != GrassClumps[edgra_nearest].element_count - 1) {
            for (i32 i = index; i < GrassClumps[edgra_nearest].element_count - 1; ++i) {
                GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, i)->position =
                    GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, i + 1)->position;
                GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, i)->field_0c =
                    GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, i + 1)->field_0c;
                GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, i)->field_10 =
                    GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, i + 1)->field_10;
                GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, i)->field_12 =
                    GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, i + 1)->field_12;
            }
        }
        --GrassClumps[edgra_nearest].element_count;
        edgraInitAllClumps();
    }
}

void edgraClumpDestroy(i32 index) {
    edgra_clump_s *clump = &GrassClumps[index];
    clump->element_count = 0;
    edgra_free_vecbuffer = clump->vector_buffer;
    clump->vector_buffer = NULL;
    --edgra_clumps_used;
    if (clump->kind == 3) {
        IndGrassClumpsUsed[clump->individual_index] = 0;
        --edgra_ind_clumps_used;
    }
    edgraInitAllClumps();
}

void edgraClumpReseed(i32 index) {
    edgra_clump_s *clump = &GrassClumps[index];
    clump->seed = NuRand(NULL);
    edgraInitAllClumps();
}

void edgraInstancePlace(i32 index, NUVEC *position) {
    GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, index)->position.x =
        position->x - GrassClumps[edgra_nearest].position.x;
    GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, index)->position.y =
        position->y - GrassClumps[edgra_nearest].position.y;
    GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, index)->position.z =
        position->z - GrassClumps[edgra_nearest].position.z;
    GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, index)->field_0c = 1.0f;
    GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, index)->field_10 = edgra_rotz;
    GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, index)->field_12 = edgra_roty;
    edgraInitAllClumps();
}

void edgraInstanceCreate(NUVEC *position) {
    if (edgra_nearest != -1 && GrassClumps[edgra_nearest].element_count != EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP) {
        i32 index = GrassClumps[edgra_nearest].element_count++;
        edgraInstancePlace(index, position);
    }
}

void edgraClumpPlace(i32 index, NUVEC *position) {
    edgra_clump_s *clump = &GrassClumps[index];
    clump->position = *position;
    clump->size = edgra_size;
    clump->rotation_z = edgra_rotz;
    clump->rotation_y = edgra_roty;
    if (edgra_mode != 3) {
        if (edgra_units_used + edgra_clump_size - clump->element_count <= 0x3000)
            clump->element_count = edgra_clump_size;
    }
    edgra_free_vecbuffer = static_cast<NUVEC *>(clump->vector_buffer) + clump->element_count;
    edgraInitAllClumps();
}

i32 edgraClumpCreate(NUVEC *position) {
    if (edgra_clumps_used == EDGRA_MAX_CLUMPS)
        return -1;
    if (edgra_copy_source == -1 && edgra_mode == 3) {
        if (edgra_units_used == 0x3000 || edgra_ind_clumps_used == EDGRA_MAX_INDIVIDUAL_CLUMPS)
            return -1;
    } else if (edgra_units_used + edgra_clump_size > 0x3000)
        return -1;
    i32 index = 0;
    while (GrassClumps[index].element_count != 0)
        ++index;
    edgra_clump_s *clump = &GrassClumps[index];
    if (edgra_copy_source != -1) {
        clump->field_18 = GrassClumps[edgra_copy_source].field_18;
        clump->special_index = GrassClumps[edgra_copy_source].special_index;
        clump->field_20 = GrassClumps[edgra_copy_source].field_20;
        clump->element_count = edgra_clump_size;
        clump->flags = GrassClumps[edgra_copy_source].flags;
        clump->page = edgra_pageid;
        clump->seed = NuRand(NULL);
        GrassClumps[index].unknown_25 = GrassClumps[edgra_copy_source].unknown_25;
        GrassClumps[index].field_2c = GrassClumps[edgra_copy_source].field_2c;
        GrassClumps[index].unknown_26 = GrassClumps[edgra_copy_source].unknown_26;
        GrassClumps[index].field_30 = GrassClumps[edgra_copy_source].field_30;
        GrassClumps[index].kind = GrassClumps[edgra_copy_source].kind;
        GrassClumps[index].near_distance = GrassClumps[edgra_copy_source].near_distance;
        GrassClumps[index].field_42 = GrassClumps[edgra_copy_source].field_42;
        GrassClumps[index].far_distance = GrassClumps[edgra_copy_source].far_distance;
        GrassClumps[index].field_44 = GrassClumps[edgra_copy_source].field_44;
        GrassClumps[index].field_43 = GrassClumps[edgra_copy_source].field_43;
    } else {
        clump->special_index = edgra_instance_type;
        clump->element_count = edgra_mode == 3 ? 1 : edgra_clump_size;
        clump->field_18 = 0.2f;
        clump->field_20 = 1.0f;
        clump->flags = 1;
        clump->page = edgra_pageid;
        clump->seed = NuRand(NULL);
        GrassClumps[index].unknown_25 = 1;
        GrassClumps[index].unknown_26 = 1;
        GrassClumps[index].field_2c = 0.0f;
        GrassClumps[index].field_30 = 1.0f;
        GrassClumps[index].kind = edgra_mode;
        GrassClumps[index].near_distance = edgra_global_fadein;
        GrassClumps[index].far_distance = edgra_global_fadeout;
        GrassClumps[index].field_42 = 1;
        GrassClumps[index].field_44 = 0.0f;
        GrassClumps[index].field_43 = 1;
    }
    if (GrassClumps[index].kind == 3) {
        i32 individual = 0;
        while (IndGrassClumpsUsed[individual])
            ++individual;
        GrassClumps[index].individual_index = individual;
        IndGrassClumpsUsed[individual] = 1;
        GetIndGrassClump(individual, 0)->position.x = 0.0f;
        GetIndGrassClump(individual, 0)->position.y = 0.0f;
        GetIndGrassClump(individual, 0)->position.z = 0.0f;
        GetIndGrassClump(individual, 0)->field_0c = 1.0f;
        GetIndGrassClump(individual, 0)->field_10 = edgra_rotz;
        GetIndGrassClump(individual, 0)->field_12 = edgra_roty;
        ++edgra_ind_clumps_used;
    } else
        GrassClumps[index].individual_index = -1;
    ++edgra_clumps_used;
    if (!edgra_page_used[edgra_pageid]) {
        edgra_page_used[edgra_pageid] = 1;
        edgra_page_scene[edgra_pageid] = edbits_base_scene;
        edgra_page_terrain[edgra_pageid] = edbits_base_terrain;
        edgra_page_matrix_stack[edgra_pageid] = edgra_mtxbuffer;
    }
    GrassClumps[index].vector_buffer = edgra_free_vecbuffer;
    edgra_last_clump_in_buffer = index;
    edgraClumpPlace(index, position);
    return index;
}

void edgraSortVectorBuffer(i32 index) {
    NUVEC temporary[256];
    if (!(index != -1 && index != edgra_last_clump_in_buffer && GrassClumps[index].vector_buffer)) {
        return;
    }
    u8 *buffer = static_cast<u8 *>(GrassClumps[index].vector_buffer);
    usize bytes = GrassClumps[index].element_count * sizeof(NUVEC);
    memcpy(temporary, buffer, bytes);
    memmove(buffer, buffer + bytes, static_cast<u8 *>(edgra_free_vecbuffer) - (buffer + bytes));
    memcpy(reinterpret_cast<void *>(reinterpret_cast<uintptr_t>(edgra_free_vecbuffer) - bytes), temporary, bytes);
    edgra_last_clump_in_buffer = index;
    for (i32 i = 0; i < EDGRA_MAX_CLUMPS; ++i) {
        if (i != index && GrassClumps[i].element_count &&
            GrassClumps[i].vector_buffer > GrassClumps[index].vector_buffer) {
            GrassClumps[i].vector_buffer =
                reinterpret_cast<void *>(reinterpret_cast<uintptr_t>(GrassClumps[i].vector_buffer) - bytes);
        }
    }
    GrassClumps[index].vector_buffer =
        reinterpret_cast<void *>(reinterpret_cast<uintptr_t>(edgra_free_vecbuffer) - bytes);
    edgraInitAllClumps();
}

void edgraDetermineNearestClump(f32 distance) {
    NUVEC delta;
    if (edgra_nearest != -1) {
        NuVecSub(&delta, &edgra_cam_pos, &GrassClumps[edgra_nearest].position);
        if (delta.x * delta.x + delta.y * delta.y + delta.z * delta.z == 0.0f)
            return;
    }
    edgra_nearest = -1;
    for (i32 i = 0; i < EDGRA_MAX_CLUMPS; ++i) {
        if (GrassClumps[i].element_count) {
            NuVecSub(&delta, &edgra_cam_pos, &GrassClumps[i].position);
            f32 candidate = delta.x * delta.x + delta.y * delta.y + delta.z * delta.z;
            if (distance < 0.0f || candidate < distance) {
                distance = candidate;
                edgra_nearest = i;
            }
        }
    }
    if (edgra_nearest != -1)
        edgraSortVectorBuffer(edgra_nearest);
}

extern "C" {
    i32 edgraLoadPage(char *path, void *gscn, i32 terrain, void *buf, void *buf_end) {
        i32 page = -1;
        for (i32 index = 0; index < 8; ++index) {
            if (edgra_page_used[index] == 0) {
                page = index;
                break;
            }
        }
        if (page == -1) {
            return -1;
        }

        VARIPTR *buffer = static_cast<VARIPTR *>(buf);
        usize matrix_base;
        if (edbits_editmode == 1 && edgra_mtxbuffer != NULL) {
            matrix_base = reinterpret_cast<usize>(edgra_mtxbuffer);
        } else {
            matrix_base = ALIGN(buffer->addr, 16);
        }
        edgra_page_matrix_stack[page] = reinterpret_cast<NUMTX *>(matrix_base);

        EdFileSetMedia(1);
        if (EdFileOpen(path, NUFILE_READ) == 0) {
            return -1;
        }
        EdFileSetReadWrongEndianess(1);
        const i32 version = EdFileReadInt();
        if (version < 1 || version > 9) {
            EdFileSetReadWrongEndianess(0);
            EdFileClose();
            return -1;
        }

        if (version == 9) {
            edgra_global_fadein = EdFileReadFloat();
            edgra_global_fadeout = EdFileReadFloat();
        } else {
            edgra_global_fadein = 15.0f;
            edgra_global_fadeout = 25.0f;
        }

        i32 clump_count = EdFileReadInt();
        if (clump_count + edgra_clumps_used > EDGRA_MAX_CLUMPS) {
            clump_count = EDGRA_MAX_CLUMPS - edgra_clumps_used;
        }
        const i32 matrix_count = version >= 8 ? EdFileReadInt() : 0x3000;
        usize vector_cursor;
        if (__builtin_expect(edbits_editmode == 1 && edgra_vecbuffer != NULL, 1)) {
            vector_cursor = reinterpret_cast<usize>(edgra_vecbuffer);
        } else {
            vector_cursor = matrix_base + static_cast<usize>(matrix_count) * sizeof(NUMTX);
        }

        i32 slot = 0;
        for (i32 file_index = 0; file_index < clump_count; ++file_index) {
            while (GrassClumps[slot].element_count != 0 && slot < EDGRA_MAX_CLUMPS) {
                ++slot;
            }

            edgra_clump_s *clump = &GrassClumps[slot];
            char instance_name[20];
            EdFileRead(instance_name, sizeof(instance_name));
            clump->special_index = edbitsLookupInstance(instance_name, static_cast<NUGSCN *>(gscn));
            clump->element_count = EdFileReadInt();
            clump->position.x = EdFileReadFloat();
            clump->position.y = EdFileReadFloat();
            clump->position.z = EdFileReadFloat();
            clump->size = EdFileReadFloat();
            clump->field_18 = EdFileReadFloat();

            clump->flags = version == 1 ? 1 : EdFileReadInt();
            clump->field_20 = version <= 2 ? 1.0f : EdFileReadFloat();
            clump->page = static_cast<u8>(page);
            if (version < 5) {
                clump->unknown_25 = 1;
                clump->unknown_26 = 1;
                clump->kind = 1;
            } else {
                clump->unknown_25 = EdFileReadChar();
                clump->unknown_26 = EdFileReadChar();
                if (__builtin_expect(version == 5, 0)) {
                    clump->kind = 1;
                } else {
                    clump->kind = EdFileReadChar();
                }
            }

            if (version < 4) {
                clump->seed = 0;
                clump->field_2c = 0.2f;
                clump->field_30 = 1.7625f;
            } else {
                clump->seed = EdFileReadInt();
                clump->field_2c = EdFileReadFloat();
                clump->field_30 = EdFileReadFloat();
            }

            if (version < 5) {
                clump->rotation_z = 0;
                clump->rotation_y = 0;
            } else {
                clump->rotation_z = EdFileReadShort();
                clump->rotation_y = EdFileReadShort();
            }
            if (version < 6) {
                clump->near_distance = 15.0f;
                clump->far_distance = 25.0f;
            } else {
                clump->near_distance = EdFileReadFloat();
                clump->far_distance = EdFileReadFloat();
            }
            if (__builtin_expect(version < 7, 0)) {
                if (clump->kind == 1) {
                    clump->field_42 = 0;
                    clump->field_43 = 0;
                    clump->field_44 = 0.0f;
                    clump->near_distance = 20.0f;
                    clump->far_distance = 20.0f;
                } else if (clump->kind == 2) {
                    clump->field_42 = 1;
                    clump->field_43 = 1;
                    clump->field_44 = 0.05f;
                } else {
                    clump->field_42 = 0;
                    clump->field_43 = 0;
                    clump->field_44 = 0.0f;
                }
            } else {
                clump->field_42 = EdFileReadChar();
                clump->field_43 = EdFileReadChar();
                clump->field_44 = EdFileReadFloat();
            }

            i32 skipped_individuals = 0;
            if (clump->kind == 3) {
                if (edgra_ind_clumps_used == EDGRA_MAX_INDIVIDUAL_CLUMPS) {
                    skipped_individuals = clump->element_count;
                    clump->element_count = 0;
                } else {
                    i32 individual = 0;
                    while (IndGrassClumpsUsed[individual] != 0) {
                        ++individual;
                    }
                    clump->individual_index = static_cast<i16>(individual);
                    IndGrassClumpsUsed[individual] = 1;
                    if (clump->element_count > EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP) {
                        skipped_individuals = clump->element_count - EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP;
                        clump->element_count = EDGRA_MAX_UNITS_PER_INDIVIDUAL_CLUMP;
                    }
                    for (i32 element = 0; element < clump->element_count; ++element) {
                        GetIndGrassClump(individual, element)->position.x = EdFileReadFloat();
                        GetIndGrassClump(individual, element)->position.y = EdFileReadFloat();
                        GetIndGrassClump(individual, element)->position.z = EdFileReadFloat();
                        GetIndGrassClump(individual, element)->field_0c = EdFileReadFloat();
                        GetIndGrassClump(individual, element)->field_10 = EdFileReadShort();
                        GetIndGrassClump(individual, element)->field_12 = EdFileReadShort();
                    }
                }
                for (i32 element = 0; element < skipped_individuals; ++element) {
                    EdFileReadFloat();
                    EdFileReadFloat();
                    EdFileReadFloat();
                    EdFileReadFloat();
                    EdFileReadShort();
                    EdFileReadShort();
                }
            }

            clump->vector_buffer = reinterpret_cast<void *>(vector_cursor);
            if (version >= 8) {
                edgra_page_vectors_valid[page] = 1;
                for (i32 element = 0; element < clump->element_count; ++element) {
                    static_cast<NUVEC *>(clump->vector_buffer)[element].x = EdFileReadFloat();
                    static_cast<NUVEC *>(clump->vector_buffer)[element].y = EdFileReadFloat();
                    static_cast<NUVEC *>(clump->vector_buffer)[element].z = EdFileReadFloat();
                }
            } else {
                edgra_page_vectors_valid[page] = 0;
            }
            if (clump->element_count < 4) {
                clump->element_count = 4;
            }

            if (__builtin_expect(clump->special_index == -1, 1)) {
                clump->element_count = 0;
            }
            if (file_index % edgra_clumpthin != 0 && edbits_editmode == 0) {
                clump->element_count = 0;
            } else if (edgra_elementthin != 1 && edbits_editmode == 0) {
                clump->element_count = (clump->element_count + edgra_elementthin - 1) / edgra_elementthin;
            }

            if (clump->element_count > 0) {
                vector_cursor += static_cast<usize>(clump->element_count) * sizeof(NUVEC);
                ++edgra_clumps_used;
                edgra_free_vecbuffer = reinterpret_cast<void *>(vector_cursor);
                edgra_last_clump_in_buffer = slot;
            }
            ++slot;
        }

        EdFileSetReadWrongEndianess(0);
        EdFileClose();
        edgra_nearest = -1;
        edgraDetermineNearestClump(1.0f);
        edgra_page_used[page] = 1;
        edgra_page_scene[page] = static_cast<NUGSCN *>(gscn);
        edgra_page_terrain[page] = reinterpret_cast<void *>(static_cast<usize>(static_cast<u32>(terrain)));
        if (edbits_editmode != 1 || edgra_vecbuffer == NULL) {
            buffer->addr = vector_cursor;
        }
        (void)buf_end;
        return page;
    }

}

void edgraDoInput(nupad_s *pad) {
    if ((pad->digital_buttons & 0x100) == 0) {
        edcamMove(pad);
    }

    if ((pad->digital_buttons & 0x100) != 0) {
        const u32 pressed = pad->digital_buttons_pressed;
        if ((pressed & 0x20) && edgra_nearest != -1)
            edgraClumpReseed(edgra_nearest);

        if ((pad->digital_buttons_pressed & 0x40) && edgra_nearest != -1) {
            if (edgra_editormode == 1) {
                edgra_editormode = 0;
            } else if (edgra_mode == 3) {
                edgra_editormode = 1;
            }
        }

        if (edgra_editormode != 1) {
            if (edgra_nearest != -1) {
                if (pad->digital_buttons_pressed & 8) {
                    do {
                        ++edgra_nearest;
                        if (edgra_nearest == EDGRA_MAX_CLUMPS)
                            edgra_nearest = 0;
                    } while (!GrassClumps[edgra_nearest].element_count);
                    edgraSortVectorBuffer(edgra_nearest);
                }
                if (pad->digital_buttons_pressed & 2) {
                    do {
                        --edgra_nearest;
                        if (edgra_nearest == -1)
                            edgra_nearest = EDGRA_MAX_CLUMPS - 1;
                    } while (!GrassClumps[edgra_nearest].element_count);
                    edgraSortVectorBuffer(edgra_nearest);
                }
            } else {
                edgraDetermineNearestClump(-1.0f);
            }
        } else {
            if (edgra_nearest_instance == -1) {
                edgraDetermineNearestInstance(-1.0f);
            } else if (__builtin_expect(edgra_nearest != -1, 1)) {
                const i32 count = GrassClumps[edgra_nearest].element_count;
                if (pad->digital_buttons_pressed & 8) {
                    ++edgra_nearest_instance;
                    if (__builtin_expect(edgra_nearest_instance == count, 1))
                        edgra_nearest_instance = 0;
                }
                if (pad->digital_buttons_pressed & 2) {
                    --edgra_nearest_instance;
                    if (edgra_nearest_instance == -1)
                        edgra_nearest_instance = count - 1;
                }
            }
        }

        if (edgra_editormode == 1) {
            if (edgra_nearest != -1 && edgra_nearest_instance != -1) {
                const i32 individual_index = GrassClumps[edgra_nearest].individual_index;
                NUVEC *instance_position = &GetIndGrassClump(individual_index, edgra_nearest_instance)->position;
                NUVEC position;
                NuVecAdd(&position, &GrassClumps[edgra_nearest].position, instance_position);
                edcamSetPos(&position);
                edgra_rotz = GetIndGrassClump(individual_index, edgra_nearest_instance)->field_10;
                edgra_roty = GetIndGrassClump(individual_index, edgra_nearest_instance)->field_12;
            }
        } else {
            if (edgra_nearest != -1) {
                edcamSetPos(&GrassClumps[edgra_nearest].position);
                const i32 kind = static_cast<i8>(GrassClumps[edgra_nearest].kind);
                edgra_mode = kind;
                edgra_instance_type = GrassClumps[edgra_nearest].special_index;
                if (kind != 3) {
                    edgra_size = GrassClumps[edgra_nearest].size;
                    edgra_clump_size = GrassClumps[edgra_nearest].element_count;
                    edgra_rotz = GrassClumps[edgra_nearest].rotation_z;
                    edgra_roty = GrassClumps[edgra_nearest].rotation_y;
                }
            }
        }
    }

    edcamGetPosAng(&edgra_cam_pos, &edgra_cam_ax, &edgra_cam_ay);
    if ((pad->digital_buttons & 0x100) == 0) {
        const u32 pressed = pad->digital_buttons_pressed;
        if (pressed & 0x80) {
            edgra_options_menu = eduiMenuCreate(70, 70, 220, 300, ed_fnt, edgracbCancelOptMenu, "Options");
            if (edgra_options_menu) {
                eduiMenuAddItem(edgra_options_menu,
                                eduiItemSelCreate(1, edblack, 0, 0, edgracbInstanceMenu, "Base Instance Select..."));
                eduiMenuAddItem(edgra_options_menu,
                                eduiItemSelCreate(1, edgra_nearest == -1 ? edgrey : edblack, 0, 0,
                                                  edgra_nearest == -1 ? NULL : edgracbChangeInstanceMenu,
                                                  "Change Instance..."));
                eduiMenuAddItem(edgra_options_menu,
                                eduiItemSelCreate(1, edblack, 0, 0, edgracbClumpModeMenu, "Clump Mode..."));
                eduiMenuAddItem(edgra_options_menu,
                                eduiItemSelCreate(1, edgra_nearest == -1 ? edgrey : edblack, 0, 0,
                                                  edgra_nearest == -1 ? NULL : edgracbClumpPropertiesMenu,
                                                  "Clump Properties..."));
                eduiMenuAddItem(edgra_options_menu,
                                eduiItemSelCreate(1, edblack, 0, 0, edgracbDpadModeMenu, "Dpad Mode..."));
                eduiMenuAddItem(edgra_options_menu,
                                eduiItemSelCreate(1, edgra_nearest == -1 ? edgrey : edblack, 0, 0,
                                                  edgra_nearest == -1 ? NULL : edgracbCopyClump, "Copy Clump"));
                eduiMenuAddItem(edgra_options_menu,
                                eduiItemSelCreate(1, edgra_copy_source == -1 ? edgrey : edblack, 0, 0,
                                                  edgra_copy_source == -1 ? NULL : edgracbDiscardCopy, "Discard Copy"));
                eduiMenuAddItem(edgra_options_menu, eduiItemSelCreate(1, edblack, 0, 0, edgracbFileSave, "Save Grass"));
                eduiMenuAddItem(edgra_options_menu, eduiItemSelCreate(1, edblack, 0, 0, edgracbFileLoad, "Load Grass"));
                eduiMenuAddItem(edgra_options_menu,
                                eduiItemSelCreate(1, edblack, 0, 0, edgracbSScaleMenu, "Super Scale..."));
                eduiMenuAddItem(edgra_options_menu, eduiItemToggleCreate(1, edblack, edgra_filter, 1, edgraToggleFilter,
                                                                         "Instance Filter"));
                eduiMenuAddItem(edgra_options_menu,
                                eduiItemTextPickCreate(0, edblack, edgraChangeFilterName, "Filter String: "));
                strcpy(static_cast<edui_textpicker_s *>(edui_last_item)->value, edgra_filter_string);
                static_cast<edui_textpicker_s *>(edui_last_item)->max_length = 15;
                eduiMenuAddItem(edgra_options_menu,
                                eduiItemSelCreate(1, edblack, 0, 0, edgracbGlobalsMenu, "Global Options..."));
            }
            edgra_active_menu = edgra_options_menu;
        }
        if (pad->digital_buttons_pressed & 0x40) {
            if (edgra_editormode == 1)
                edgraInstanceCreate(&edgra_cam_pos);
            else if (edgra_instance_type != -1)
                edgraClumpCreate(&edgra_cam_pos);
        }
        if (pad->digital_buttons & 0x20) {
            if (edgra_editormode == 1) {
                if (edgra_nearest_instance != -1)
                    edgraInstancePlace(edgra_nearest_instance, &edgra_cam_pos);
            } else if (edgra_nearest != -1) {
                edgraClumpPlace(edgra_nearest, &edgra_cam_pos);
            }
        }
        if (pad->digital_buttons_pressed & 0x10) {
            if (edgra_editormode != 1) {
                if (edgra_nearest != -1)
                    edgraClumpDestroy(edgra_nearest);
                edgra_nearest = -1;
            } else {
                if (edgra_nearest_instance != -1)
                    edgraInstanceDestroy(edgra_nearest_instance);
                edgra_nearest_instance = -1;
            }
        }
    }

    if (edgra_dpadmode == 0) {
        if (edgra_mode != 3) {
            edgra_size += static_cast<f32>(pad->analog_left_pad_up) / 5000.0f;
            edgra_size -= static_cast<f32>(pad->analog_left_pad_down) / 5000.0f;
            if (edgra_size < 0.1f)
                edgra_size = 0.1f;
            if (edgra_size > 10.0f)
                edgra_size = 10.0f;
            if (pad->analog_left_pad_left == 255 || (pad->digital_buttons_pressed & 0x8000))
                --edgra_clump_size;
            if (pad->analog_left_pad_right == 255 || (pad->digital_buttons_pressed & 0x2000))
                ++edgra_clump_size;
            if (edgra_clump_size < 4)
                edgra_clump_size = 4;
            if (edgra_clump_size > 256)
                edgra_clump_size = 256;
        } else {
            if (edgra_nearest != -1 && edgra_nearest_instance != -1) {
                GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, edgra_nearest_instance)->field_0c +=
                    static_cast<f32>(pad->analog_left_pad_up) / 5000.0f;
                GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, edgra_nearest_instance)->field_0c -=
                    static_cast<f32>(pad->analog_left_pad_down) / 5000.0f;
                if (GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, edgra_nearest_instance)->field_0c >
                    1.0f)
                    GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, edgra_nearest_instance)->field_0c =
                        1.0f;
                if (GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, edgra_nearest_instance)->field_0c <
                    0.1f)
                    GetIndGrassClump(GrassClumps[edgra_nearest].individual_index, edgra_nearest_instance)->field_0c =
                        0.1f;
            }
            if (__builtin_expect(pad->analog_left_pad_up || pad->analog_left_pad_down, 1))
                edgraInitAllClumps();
        }
    } else if (edgra_dpadmode == 1) {
        edgra_roty += pad->analog_left_pad_right - pad->analog_left_pad_left;
        edgra_rotz += pad->analog_left_pad_up;
        if (edgra_rotz > 32768)
            edgra_rotz = 32768;
        edgra_rotz -= pad->analog_left_pad_down;
        if (edgra_rotz < -32768)
            edgra_rotz = -32768;
    }
}

static i32 edgraProc(f32 delta_time, nupad_s *pad) {
    if (edgra_active_menu) {
        eduiMenuProcess(edgra_active_menu, delta_time, pad);
        return 0;
    }
    edgraDoInput(pad);
    if (edgra_editormode == 1)
        edgraDetermineNearestInstance(1.0f);
    else
        edgraDetermineNearestClump(1.0f);
    return (pad->digital_buttons_pressed >> 11) & 1;
}

static void edgracbFileLoad(eduimenu_s *menu, eduiitem_s *, u32) {
    char path[256];
    char directory[256];
    char name[256];
    char extension[256];
    if (edbits_level_save_directory[0] == 0)
        strcpy(directory, ".");
    else
        strcpy(directory, edbits_level_save_directory);
    if (edbits_level_save_name[0] == 0)
        strcpy(name, "grass");
    else
        strcpy(name, edbits_level_save_name);
    if (edbits_level_save_extension[0] == 0)
        strcpy(extension, "gra");
    else
        strcpy(extension, edbits_level_save_extension);
    sprintf(path, "%s\\%s.%s", directory, name, extension);
    edgraClumpsReset();
    if (NuFileExists(path))
        edgraLoadPage(path, edbits_base_scene, reinterpret_cast<usize>(edbits_base_terrain), NULL, NULL);
    edgraInitAllClumps();
    eduiCreateMessageMenu(menu, "Loaded OK", 1);
}

extern "C" {
    void edgraStopPage(i8 page) {
        if (edgra_page_on[page]) {
            edgra_page_on[page] = 0;
            edgra_units_used = 0;
            NuWindInit();
            NuFadeObjInit();
            for (i32 i = 0; i < 8; ++i) {
                if (edgra_page_on[i]) {
                    edgra_page_on[i] = 0;
                    edgraStartPage(i);
                }
            }
        }
    }

    void edgraClearPage(i8 page) {
        edgraStopPage(page);
        for (i32 i = 0; i < EDGRA_MAX_CLUMPS; ++i) {
            edgra_clump_s *clump = &GrassClumps[i];
            if (clump->element_count && clump->page == static_cast<u8>(page)) {
                if (clump->kind == 3) {
                    IndGrassClumpsUsed[clump->individual_index] = 0;
                    --edgra_ind_clumps_used;
                }
                clump->element_count = 0;
                --edgra_clumps_used;
            }
        }
        edgra_page_used[page] = 0;
        edgra_page_scene[page] = NULL;
        edgra_page_matrix_stack[page] = NULL;
        edgra_page_vectors_valid[page] = 0;
        edgra_page_calculate_done[page] = 0;
    }

    void PlatformUpdateCallback(void (*function)(void *), void *argument) {
        if (PlatCodeCallback < 8) {
            PlatCallback[PlatCodeCallback].function = function;
            PlatCallback[PlatCodeCallback].argument = argument;
            ++PlatCodeCallback;
        }
    }

    void PlatformRemoveCallback(void (*function)(void *)) {
        for (i32 i = 0; i < PlatCodeCallback; ++i) {
            if (PlatCallback[i].function == function) {
                --PlatCodeCallback;
                PlatCallback[i].function = PlatCallback[PlatCodeCallback].function;
                PlatCallback[i].argument = PlatCallback[PlatCodeCallback].argument;
                --i;
            }
        }
    }

extern "C" void TerrSetPlatScanDist(f32 dist) {
    TerrPlatScanDist = dist;
}

extern "C" void TerrainPlatformNewUpdate(void) {
    if (CurTerr != NULL) {
        TERRAIN_TRACK_SLOT *slot = CurTerr->track_slots;
        i32 remaining = TERRAIN_TRACK_SLOT_COUNT;
        do {
            if (slot->id != NULL) {
                if (slot->platform_contact_state > 0)
                    --slot->platform_contact_state;
                if (slot->wall_contact_state > 0)
                    --slot->wall_contact_state;
            }
            ++slot;
            --remaining;
        } while (remaining != 0);
        for (i32 i = 0; i < 16; ++i) {
            if (static_cast<i16>(CurTerr->index_levels[i].entry_count) > 0)
                --CurTerr->index_levels[i].entry_count;
        }
    }
    for (i32 i = 0; i < PlatCodeCallback; ++i)
        PlatCallback[i].function(PlatCallback[i].argument);
    PlatCodeCallback = 0;
    cntrots = 0;
    if (CurTerr == NULL)
        return;

    const NUMTX &camera = global_camera.mtx;
    const f32 negative_distance = -TerrPlatScanDist;
    const f32 back_x = negative_distance * camera.m20 * 0.25f;
    f32 min_x = camera.m00 * negative_distance * 0.25f + back_x;
    const f32 back_z = negative_distance * camera.m22 * 0.25f;
    f32 max_x = camera.m00 * negative_distance * 0.35f + camera.m20 * TerrPlatScanDist;
    f32 max_z = camera.m02 * negative_distance * 0.35f + camera.m22 * TerrPlatScanDist;
    f32 min_z = camera.m02 * negative_distance * 0.25f + back_z;
    f32 x = min_x;
    f32 z = min_z;
    min_x = MIN(min_x, max_x);
    min_z = MIN(min_z, max_z);
    max_x = MAX(x, max_x);
    max_z = MAX(z, max_z);
    x = camera.m00 * TerrPlatScanDist * 0.35f + camera.m20 * TerrPlatScanDist;
    z = TerrPlatScanDist * camera.m02 * 0.35f + camera.m22 * TerrPlatScanDist;
    min_x = MIN(min_x, x);
    max_x = MAX(max_x, x);
    min_z = MIN(min_z, z);
    max_z = MAX(max_z, z);
    x = camera.m00 * TerrPlatScanDist * 0.25f + back_x;
    z = TerrPlatScanDist * camera.m02 * 0.25f + back_z;
    min_x = (MIN(min_x, x)) + (camera.m30 - 1.0f);
    max_x = (MAX(max_x, x)) + (camera.m30 + 1.0f);
    min_z = (MIN(min_z, z)) + (camera.m32 - 1.0f);
    max_z = (MAX(max_z, z)) + (camera.m32 + 1.0f);
    CurTerr->platform_scan_min.x = min_x;
    CurTerr->platform_scan_min.z = min_z;
    CurTerr->platform_scan_max.x = max_x;
    CurTerr->platform_scan_max.z = max_z;
    CurTerr->active_platform_count = 0;
    TERRAIN_CELL &cell = CurTerr->cells[TERRAIN_PLATFORM_CELL];
    i16 *group_index = CurTerr->group_indices + cell.first_group;
    const i32 group_count = static_cast<i16>(cell.group_count);
    if (group_count <= 0)
        return;
    i16 *end = group_index + group_count;
    for (; group_index != end; ++group_index) {
        TERRAIN_GROUP &group = CurTerr->groups[*group_index];
        TERRAIN_PLATFORM &platform = CurTerr->platforms[group.scene_index];
        if (platform.scene_transform != NULL) {
            const u8 visibility = *static_cast<u8 *>(platform.scene_transform);
            if ((platform.flags & TERRAIN_PLATFORM_FLAG_DISPLAY_LIST_BACKED) != 0) {
                if ((visibility & 2) == 0)
                    continue;
            } else if ((visibility & 1) == 0)
                continue;
        }
        if (group.chunk_type == 0)
            continue;
        NUMTX *matrix = static_cast<NUMTX *>(platform.scene_object);
        if (matrix != NULL) {
            if (platform.bounce_frames != 0) {
                f32 velocity;
                if (platform.bounce_frames < 125)
                    velocity = platform.bounce_velocity - platform.bounce_damping * platform.bounce_velocity;
                else
                    velocity = (platform.bounce_impulse - platform.bounce_damping * platform.bounce_velocity) +
                               platform.bounce_velocity;
                const f32 offset = platform.bounce_offset;
                --platform.bounce_frames;
                velocity = (-offset * fabsf(offset) * platform.bounce_spring * 0.5f - platform.bounce_spring * offset) +
                           velocity;
                platform.bounce_velocity = velocity;
                platform.bounce_offset = velocity + offset;
                matrix->m31 = platform.bounce_offset + matrix->m31;
            }
            group.origin = *NUMTX_GET_ROW_VEC(matrix, 3);
        }
        const u8 flags = platform.flags;
        if ((flags & TERRAIN_PLATFORM_FLAG_COLLIDED) != 0)
            platform.bounce_frames = 128;
        platform.field_0x44 = 0;
        platform.flags &= ~TERRAIN_PLATFORM_FLAG_COLLIDED;
        if ((flags & TERRAIN_PLATFORM_FLAG_ROTATING) != 0) {
            if (group.origin.x - group.radius > max_x || group.origin.x + group.radius < min_x ||
                group.origin.z - group.radius > max_z || group.origin.z + group.radius < min_z)
                continue;
        } else {
            if (__builtin_expect(
                    group.bounds_min.x + group.origin.x > max_x || group.origin.x + group.bounds_max.x < min_x ||
                        group.bounds_min.z + group.origin.z > max_z || group.origin.z + group.bounds_max.z < min_z,
                    0))
                continue;
        }
        if (__builtin_expect(CurTerr->active_platform_count < 96, 0))
            CurTerr->active_platform_groups[CurTerr->active_platform_count++] = *group_index;
    }
}

}

NUVEC TerCrossProduct(NUVEC *a, NUVEC *b) {
    NUVEC result;
    result.x = a->y * b->z - a->z * b->y;
    result.y = a->z * b->x - b->z * a->x;
    result.z = a->x * b->y - b->x * a->y;
    return result;
}

void TerrDraw(tertype *terrain, i16 index) {
    TERRAIN_DEBUG_RECORD *record = reinterpret_cast<TERRAIN_DEBUG_RECORD *>(terrain);
    i32 colour = (index & 0x80) + (static_cast<u8>(index * 64) << 8);
    if (!(record->normals[1].y > 65535.0f)) {
        for (i32 i = 0; i < 2; ++i) {
            f32 t = static_cast<f32>(i);
            NUVEC *origin = &CurTerr->groups[index].origin;
            NuRndrLine3dDbg(origin->x + record->vertices[0].x + (record->vertices[1].x - record->vertices[0].x) * t,
                            origin->y + record->vertices[0].y + (record->vertices[1].y - record->vertices[0].y) * t,
                            origin->z + record->vertices[0].z + (record->vertices[1].z - record->vertices[0].z) * t,
                            origin->x + record->vertices[2].x + (record->vertices[3].x - record->vertices[2].x) * t,
                            origin->y + record->vertices[2].y + (record->vertices[3].y - record->vertices[2].y) * t,
                            origin->z + record->vertices[2].z + (record->vertices[3].z - record->vertices[2].z) * t,
                            colour);
        }
        for (i32 i = 0; i < 2; ++i) {
            f32 t = static_cast<f32>(i);
            NUVEC *origin = &CurTerr->groups[index].origin;
            NuRndrLine3dDbg(origin->x + record->vertices[0].x + (record->vertices[2].x - record->vertices[0].x) * t,
                            origin->y + record->vertices[0].y + (record->vertices[2].y - record->vertices[0].y) * t,
                            origin->z + record->vertices[0].z + (record->vertices[2].z - record->vertices[0].z) * t,
                            origin->x + record->vertices[1].x + (record->vertices[3].x - record->vertices[1].x) * t,
                            origin->y + record->vertices[1].y + (record->vertices[3].y - record->vertices[1].y) * t,
                            origin->z + record->vertices[1].z + (record->vertices[3].z - record->vertices[1].z) * t,
                            colour);
        }
    }
    NUVEC *origin = &CurTerr->groups[index].origin;
    f32 z = origin->z + record->vertices[0].z;
    f32 y = origin->y + record->vertices[0].y;
    f32 x = origin->x + record->vertices[0].x;
    NuRndrLine3dDbg(x, y, z, x + record->normals[0].x * 0.4f, y + record->normals[0].y * 0.4f,
                    z + record->normals[0].z * 0.4f, colour);
    if (record->normals[1].y < 65536.0f) {
        origin = &CurTerr->groups[index].origin;
        z = origin->z + record->vertices[3].z;
        y = origin->y + record->vertices[3].y;
        x = origin->x + record->vertices[3].x;
        NuRndrLine3dDbg(x, y, z, x + record->normals[1].x * 0.4f, y + record->normals[1].y * 0.4f,
                        z + record->normals[1].z * 0.4f, colour);
    }
}

void TerrDrawSitu(tertype *terrain, terrsitu_s *situation) {
    TERRAIN_DEBUG_RECORD *record = reinterpret_cast<TERRAIN_DEBUG_RECORD *>(terrain);
    NUVEC *origin = reinterpret_cast<NUVEC *>(situation);
    if (record->normals[1].y > 65535.0f) {
        for (i32 i = 0; i < 2; ++i) {
            f32 t = static_cast<f32>(i);
            NuRndrLine3dDbg(
                origin->x + record->vertices[0].x, origin->y + record->vertices[0].y, origin->z + record->vertices[0].z,
                origin->x + record->vertices[1].x + (record->vertices[2].x - record->vertices[1].x) * t,
                origin->y + record->vertices[1].y + (record->vertices[2].y - record->vertices[1].y) * t,
                origin->z + record->vertices[1].z + (record->vertices[2].z - record->vertices[1].z) * t, 0x003f7f80);
        }
        for (i32 i = 0; i < 2; ++i) {
            f32 t = static_cast<f32>(i);
            NuRndrLine3dDbg(
                origin->x + record->vertices[1].x, origin->y + record->vertices[1].y, origin->z + record->vertices[1].z,
                origin->x + record->vertices[0].x + (record->vertices[2].x - record->vertices[0].x) * t,
                origin->y + record->vertices[0].y + (record->vertices[2].y - record->vertices[0].y) * t,
                origin->z + record->vertices[0].z + (record->vertices[2].z - record->vertices[0].z) * t, 0x003f7f80);
        }
    } else {
        for (i32 i = 0; i < 2; ++i) {
            f32 t = static_cast<f32>(i);
            NuRndrLine3dDbg(origin->x + record->vertices[0].x + (record->vertices[1].x - record->vertices[0].x) * t,
                            origin->y + record->vertices[0].y + (record->vertices[1].y - record->vertices[0].y) * t,
                            origin->z + record->vertices[0].z + (record->vertices[1].z - record->vertices[0].z) * t,
                            origin->x + record->vertices[2].x + (record->vertices[3].x - record->vertices[2].x) * t,
                            origin->y + record->vertices[2].y + (record->vertices[3].y - record->vertices[2].y) * t,
                            origin->z + record->vertices[2].z + (record->vertices[3].z - record->vertices[2].z) * t,
                            0xffff7f80);
        }
        for (i32 i = 0; i < 2; ++i) {
            f32 t = static_cast<f32>(i);
            NuRndrLine3dDbg(origin->x + record->vertices[0].x + (record->vertices[2].x - record->vertices[0].x) * t,
                            origin->y + record->vertices[0].y + (record->vertices[2].y - record->vertices[0].y) * t,
                            origin->z + record->vertices[0].z + (record->vertices[2].z - record->vertices[0].z) * t,
                            origin->x + record->vertices[1].x + (record->vertices[3].x - record->vertices[1].x) * t,
                            origin->y + record->vertices[1].y + (record->vertices[3].y - record->vertices[1].y) * t,
                            origin->z + record->vertices[1].z + (record->vertices[3].z - record->vertices[1].z) * t,
                            0xffff7f80);
        }
    }
}

void TerrDrawPlat(tertype *terrain, i16 index) {
    TERRAIN_DEBUG_RECORD *record = reinterpret_cast<TERRAIN_DEBUG_RECORD *>(terrain);
    TERRAIN_PLATFORM *platform = &CurTerr->platforms[CurTerr->groups[index].scene_index];
    if (__builtin_expect(platform->scene_transform != NULL, 1)) {
        if (platform->flags & TERRAIN_PLATFORM_FLAG_DISPLAY_LIST_BACKED) {
            if (!(*static_cast<u8 *>(platform->scene_transform) & 2))
                return;
        } else if (!(*static_cast<u8 *>(platform->scene_transform) & 1))
            return;
    }
    NUVEC4 points[5];
    points[3].x = record->vertices[3].x;
    points[3].y = record->vertices[3].y;
    points[3].z = record->vertices[3].z;
    points[3].w = 0.0f;
    for (i32 i = 0; i < 3; ++i) {
        points[i].x = record->vertices[i].x;
        points[i].y = record->vertices[i].y;
        points[i].z = record->vertices[i].z;
        points[i].w = 0.0f;
    }
    NUVEC4 &normal = points[4];
    normal.x = record->normals[0].x * 0.4f;
    normal.y = record->normals[0].y * 0.4f;
    normal.z = record->normals[0].z * 0.4f;
    i32 colour = static_cast<i8>(record->unknown_60[2]) < 0 ? 0x0000ffff : 0x00ff0000;
    normal.w = 0.0f;
    if (platform->flags & TERRAIN_PLATFORM_FLAG_ROTATING) {
        NuVec4MtxTransformVU0(&points[0], &points[0], static_cast<NUMTX *>(platform->scene_object));
        NuVec4MtxTransformVU0(
            &points[1], &points[1],
            static_cast<NUMTX *>(CurTerr->platforms[CurTerr->groups[index].scene_index].scene_object));
        NuVec4MtxTransformVU0(
            &points[2], &points[2],
            static_cast<NUMTX *>(CurTerr->platforms[CurTerr->groups[index].scene_index].scene_object));
        NuVec4MtxTransformVU0(
            &points[3], &points[3],
            static_cast<NUMTX *>(CurTerr->platforms[CurTerr->groups[index].scene_index].scene_object));
        NuVec4MtxTransformVU0(
            &normal, &normal,
            static_cast<NUMTX *>(CurTerr->platforms[CurTerr->groups[index].scene_index].scene_object));
    }
    NUVEC *origin;
    if (record->normals[1].y > 65535.0f) {
        for (i32 i = 0; i < 2; ++i) {
            f32 t = static_cast<f32>(i);
            origin = &CurTerr->groups[index].origin;
            NuRndrLine3dDbg(origin->x + points[0].x, origin->y + points[0].y, origin->z + points[0].z,
                            origin->x + points[1].x + (points[2].x - points[1].x) * t,
                            origin->y + points[1].y + (points[2].y - points[1].y) * t,
                            origin->z + points[1].z + (points[2].z - points[1].z) * t, colour);
        }
        for (i32 i = 0; i < 2; ++i) {
            f32 t = static_cast<f32>(i);
            origin = &CurTerr->groups[index].origin;
            NuRndrLine3dDbg(origin->x + points[1].x, origin->y + points[1].y, origin->z + points[1].z,
                            origin->x + points[0].x + (points[2].x - points[0].x) * t,
                            origin->y + points[0].y + (points[2].y - points[0].y) * t,
                            origin->z + points[0].z + (points[2].z - points[0].z) * t, colour);
        }
    } else {
        for (i32 i = 0; i < 2; ++i) {
            f32 t = static_cast<f32>(i);
            origin = &CurTerr->groups[index].origin;
            NuRndrLine3dDbg(origin->x + points[0].x + (points[1].x - points[0].x) * t,
                            origin->y + points[0].y + (points[1].y - points[0].y) * t,
                            origin->z + points[0].z + (points[1].z - points[0].z) * t,
                            origin->x + points[2].x + (points[3].x - points[2].x) * t,
                            origin->y + points[2].y + (points[3].y - points[2].y) * t,
                            origin->z + points[2].z + (points[3].z - points[2].z) * t, colour);
        }
        for (i32 i = 0; i < 2; ++i) {
            f32 t = static_cast<f32>(i);
            origin = &CurTerr->groups[index].origin;
            NuRndrLine3dDbg(origin->x + points[0].x + (points[2].x - points[0].x) * t,
                            origin->y + points[0].y + (points[2].y - points[0].y) * t,
                            origin->z + points[0].z + (points[2].z - points[0].z) * t,
                            origin->x + points[1].x + (points[3].x - points[1].x) * t,
                            origin->y + points[1].y + (points[3].y - points[1].y) * t,
                            origin->z + points[1].z + (points[3].z - points[1].z) * t, colour);
        }
    }
    origin = &CurTerr->groups[index].origin;
    f32 z = origin->z + points[0].z;
    f32 y = origin->y + points[0].y;
    f32 x = origin->x + points[0].x;
    colour = static_cast<i8>(index & 0xf0) + static_cast<i8>(index * 16) * 256;
    NuRndrLine3dDbg(x, y, z, x + normal.x, y + normal.y, z + normal.z, colour);
}

void TerrDrawPlatCol(tertype *terrain, i16 index, i32 colour) {
    TERRAIN_DEBUG_RECORD *record = reinterpret_cast<TERRAIN_DEBUG_RECORD *>(terrain);
    TERRAIN_GROUP &group = CurTerr->groups[index];
    TERRAIN_PLATFORM &platform = CurTerr->platforms[group.scene_index];
    if (platform.scene_transform == NULL ||
        ((platform.flags & TERRAIN_PLATFORM_FLAG_DISPLAY_LIST_BACKED) != 0
             ? (*static_cast<u8 *>(platform.scene_transform) & 2) != 0
             : (*static_cast<u8 *>(platform.scene_transform) & 1) != 0)) {

        NUVEC4 points[4];
        for (i32 i = 0; i < 3; ++i) {
            points[i].x = record->vertices[i].x;
            points[i].y = record->vertices[i].y;
            points[i].z = record->vertices[i].z;
            points[i].w = 0.0f;
        }
        NUVEC4 normals[2];
        normals[0].x = record->normals[0].x * 0.4f;
        normals[0].y = record->normals[0].y * 0.4f;
        normals[0].z = record->normals[0].z * 0.4f;
        normals[0].w = 0.0f;
        if (__builtin_expect((platform.flags & TERRAIN_PLATFORM_FLAG_ROTATING) != 0, 0)) {
            NuVec4MtxTransformVU0(&points[0], &points[0], static_cast<NUMTX *>(platform.scene_object));
            NuVec4MtxTransformVU0(
                &points[1], &points[1],
                static_cast<NUMTX *>(CurTerr->platforms[CurTerr->groups[index].scene_index].scene_object));
            NuVec4MtxTransformVU0(
                &points[2], &points[2],
                static_cast<NUMTX *>(CurTerr->platforms[CurTerr->groups[index].scene_index].scene_object));
            NuVec4MtxTransformVU0(
                &normals[0], &normals[0],
                static_cast<NUMTX *>(CurTerr->platforms[CurTerr->groups[index].scene_index].scene_object));
        }
        const bool quad = record->normals[1].y <= 65535.0f;
        if (quad) {
            points[3].x = record->vertices[3].x;
            points[3].y = record->vertices[3].y;
            points[3].z = record->vertices[3].z;
            points[3].w = 0.0f;
            NuVec4MtxTransformVU0(
                &points[3], &points[3],
                static_cast<NUMTX *>(CurTerr->platforms[CurTerr->groups[index].scene_index].scene_object));
            normals[1].x = record->normals[1].x * 0.4f;
            normals[1].y = record->normals[1].y * 0.4f;
            normals[1].z = record->normals[1].z * 0.4f;
            normals[1].w = 0.0f;
            // Retail transforms the first normal again here, leaving the second in local space.
            NuVec4MtxTransformVU0(
                &normals[0], &normals[0],
                static_cast<NUMTX *>(CurTerr->platforms[CurTerr->groups[index].scene_index].scene_object));
        }

        if (!quad) {
            for (i32 i = 0; i < 2; ++i) {
                const f32 t = static_cast<f32>(i);
                const NUVEC &origin = CurTerr->groups[index].origin;
                NuRndrLine3dDbg(origin.x + points[0].x, origin.y + points[0].y, origin.z + points[0].z,
                                origin.x + points[1].x + (points[2].x - points[1].x) * t,
                                origin.y + points[1].y + (points[2].y - points[1].y) * t,
                                origin.z + points[1].z + (points[2].z - points[1].z) * t, colour);
            }
            for (i32 i = 0; i < 2; ++i) {
                const f32 t = static_cast<f32>(i);
                const NUVEC &origin = CurTerr->groups[index].origin;
                NuRndrLine3dDbg(origin.x + points[1].x, origin.y + points[1].y, origin.z + points[1].z,
                                origin.x + points[0].x + (points[2].x - points[0].x) * t,
                                origin.y + points[0].y + (points[2].y - points[0].y) * t,
                                origin.z + points[0].z + (points[2].z - points[0].z) * t, colour);
            }
        } else {
            for (i32 i = 0; i < 2; ++i) {
                const f32 t = static_cast<f32>(i);
                const NUVEC &origin = CurTerr->groups[index].origin;
                NuRndrLine3dDbg(origin.x + points[0].x + (points[1].x - points[0].x) * t,
                                origin.y + points[0].y + (points[1].y - points[0].y) * t,
                                origin.z + points[0].z + (points[1].z - points[0].z) * t,
                                origin.x + points[2].x + (points[3].x - points[2].x) * t,
                                origin.y + points[2].y + (points[3].y - points[2].y) * t,
                                origin.z + points[2].z + (points[3].z - points[2].z) * t, colour);
            }
            for (i32 i = 0; i < 2; ++i) {
                const f32 t = static_cast<f32>(i);
                const NUVEC &origin = CurTerr->groups[index].origin;
                NuRndrLine3dDbg(origin.x + points[0].x + (points[2].x - points[0].x) * t,
                                origin.y + points[0].y + (points[2].y - points[0].y) * t,
                                origin.z + points[0].z + (points[2].z - points[0].z) * t,
                                origin.x + points[1].x + (points[3].x - points[1].x) * t,
                                origin.y + points[1].y + (points[3].y - points[1].y) * t,
                                origin.z + points[1].z + (points[3].z - points[1].z) * t, colour);
            }
            const NUVEC &origin = CurTerr->groups[index].origin;
            NuRndrLine3dDbg(origin.x + points[3].x, origin.y + points[3].y, origin.z + points[3].z,
                            origin.x + points[3].x + normals[1].x, origin.y + points[3].y + normals[1].y,
                            origin.z + points[3].z + normals[1].z, 0xff);
        }
        const NUVEC &origin = CurTerr->groups[index].origin;
        NuRndrLine3dDbg(origin.x + points[0].x, origin.y + points[0].y, origin.z + points[0].z,
                        origin.x + points[0].x + normals[0].x, origin.y + points[0].y + normals[0].y,
                        origin.z + points[0].z + normals[0].z, 0xff);
    }
}

extern "C" {
extern "C" void TerrDrawImpactPol(void) {
    if (TerI == NULL || TerI->surface == NULL)
        return;
    TERRAIN_SHAPE *surface = TerI->surface;
    if (surface >= ScaleTerrain && surface < ScaleTerrain + 0x200) {
        surface = *reinterpret_cast<TERRAIN_SHAPE **>(surface);
    }
    TerrDraw(surface, TerI->terrain_group_index);
}

    void DrawPlatform(i32 platform_index) {
        if (CurTerr == NULL || platform_index < 0)
            return;

        TERRAIN_GROUP &group = CurTerr->groups[CurTerr->platforms[platform_index].terrain_group_index];
        if (static_cast<u32>(group.chunk_type) > TERRAIN_CHUNK_GROUP_SECONDARY)
            return;

        TERRAIN_SHAPE_BATCH *batch = static_cast<TERRAIN_SHAPE_BATCH *>(group.data);
        while (batch->marker >= 0) {
            TERRAIN_SHAPE *shape = reinterpret_cast<TERRAIN_SHAPE *>(batch + 1);
            const i32 shape_count = batch->shape_count;
            for (i32 i = shape_count; i > 0; --i, ++shape)
                TerrDrawPlat(shape, CurTerr->platforms[platform_index].terrain_group_index);
            batch = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(shape);
        }
    }

}

void DrawMSitu(i32 index) {
    TERRAIN_GROUP *group = &CurTerr->groups[index];
    if ((u32)group->chunk_type <= TERRAIN_CHUNK_GROUP_SECONDARY && group->data != NULL) {
        TERRAIN_SHAPE_BATCH *batch = static_cast<TERRAIN_SHAPE_BATCH *>(group->data);
        while (batch->marker >= 0) {
            u8 *entry = reinterpret_cast<u8 *>(batch + 1);
            i16 count = batch->shape_count;
            for (i32 remaining = count; remaining > 0; --remaining) {
                TerrDraw(reinterpret_cast<tertype *>(entry), static_cast<i16>(index));
                // This debug walker uses the original 100-byte record stride.
                entry += 100;
            }
            batch = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(entry);
        }
    }
}

extern "C" {
extern "C" void SphereDrawEx(NUVEC *centre, f32 radius, f32 vertical_scale, i32 colour) {
    f32 radius_squared = radius * radius;
    for (i32 band = 0; band < 8; ++band) {
        f32 lower_radius;
        f32 upper_radius;
        if (band < 4) {
            lower_radius = radius * NU_SIN_LUT(band * 4096);
        } else {
            lower_radius = radius * NU_SIN_LUT((8 - band) * 4096);
        }
        if (band < 3) {
            upper_radius = radius * NU_SIN_LUT((band + 1) * 4096);
        } else {
            upper_radius = radius * NU_SIN_LUT((7 - band) * 4096);
        }
        f32 lower_y = NuFsqrt(radius_squared - lower_radius * lower_radius) * vertical_scale;
        f32 upper_y = NuFsqrt(radius_squared - upper_radius * upper_radius) * vertical_scale;
        if (band > 4)
            lower_y = -lower_y;
        if (band > 3)
            upper_y = -upper_y;
        lower_y += radius * vertical_scale + centre->y;
        upper_y += radius * vertical_scale + centre->y;
        for (i32 angle = 0; angle < 65536; angle += 2048) {
            NuRndrLine3dDbg(centre->x + lower_radius * NU_COS_LUT(angle), lower_y,
                            centre->z + lower_radius * NU_SIN_LUT(angle), centre->x + upper_radius * NU_COS_LUT(angle),
                            upper_y, centre->z + upper_radius * NU_SIN_LUT(angle), colour);
            NuRndrLine3dDbg(centre->x + lower_radius * NU_COS_LUT(angle), lower_y,
                            centre->z + lower_radius * NU_SIN_LUT(angle),
                            centre->x + lower_radius * NU_COS_LUT(angle + 2048), lower_y,
                            centre->z + lower_radius * NU_SIN_LUT(angle + 2048), colour);
        }
    }
}

extern "C" void SphereDraw(NUVEC *centre, f32 radius, f32 vertical_scale) {
    SphereDrawEx(centre, radius, vertical_scale, 0x00400000);
}

}

void DrawWallSpline(float height) {
    for (i32 i = 0; i < WallSplCount; i += 2) {
        const NUVEC &start = WallSplList[i].position;
        const NUVEC &end = WallSplList[i + 1].position;
        NuRndrLine3dDbg(start.x, height, start.z, end.x, height, end.z, 0x80808080);
    }
}

NUVEC TerrainSkin(PLATSKININFO *info, nuvec_s *position, float weight, i32 mode) {
    NUVEC4_ALIGNED16 point;
    NUMTX_ALIGNED16 matrix;
    if (mode != 1) {
        if (weight < 0.0f)
            weight = position->z / info->scale;
        if (weight < 0.0f)
            weight = 0.0f;
        else
            weight = MIN(1.0f, weight);
        point.x = position->x;
        point.y = position->y;
        point.w = 1.0f;
        if (info->matrix_data != NULL) {
            weight = (f32)(i32)(weight * 8.0f + 0.5f) * 0.125f;
            point.z = position->z - info->scale * weight;
            i32 index = (i32)(weight * 8.0f);
            NUVEC4 *rows = static_cast<NUVEC4 *>(info->matrix_data);
            NUVEC4 *out = reinterpret_cast<NUVEC4 *>(&matrix);
            for (i32 row = 0; row < 4; ++row) {
                out[row].x = rows[index + row * 11].x;
                out[row].y = rows[index + row * 11].y;
                out[row].z = rows[index + row * 11].z;
                out[row].w = rows[index + row * 11].w;
            }
        } else {
            struct SKIN_BLEND_DATA {
                NUMTX end_matrix;
                NUVEC scale_amplitude;
                f32 reserved_4c;
                NUVEC translation_amplitude;
            };
            SKIN_BLEND_DATA *blend = static_cast<SKIN_BLEND_DATA *>(info->skin_data);
            weight = (f32)(i32)(weight * 10.0f + 0.5f) / 10.0f;
            f32 inverse_weight = 1.0f - weight;
            point.z = position->z - info->scale * weight;
            f32 wave = NU_SIN_LUT((i32)(weight * 32768.0f));
            f32 *out = reinterpret_cast<f32 *>(&matrix);
            f32 *start = reinterpret_cast<f32 *>(info->matrix);
            f32 *end = reinterpret_cast<f32 *>(&blend->end_matrix);
            f32 *amplitude = reinterpret_cast<f32 *>(&blend->scale_amplitude);
            for (i32 row = 0; row < 3; ++row) {
                f32 scale = amplitude[row] * wave + 1.0f;
                for (i32 column = 0; column < 4; ++column) {
                    i32 index = row * 4 + column;
                    out[index] = (start[index] * inverse_weight + end[index] * weight) * scale;
                }
            }
            matrix.m30 = start[12] * inverse_weight + end[12] * weight + blend->translation_amplitude.x * wave;
            matrix.m31 = start[13] * inverse_weight + end[13] * weight + blend->translation_amplitude.y * wave;
            matrix.m32 = start[14] * inverse_weight + end[14] * weight + blend->translation_amplitude.z * wave;
            matrix.m33 = start[15] * inverse_weight + end[15] * weight;
        }
        NuVec4MtxTransformVU0(&point, &point, &matrix);
    } else {
        point.x = position->x;
        point.y = position->y;
        point.z = position->z;
        point.w = 1.0f;
        NuVec4MtxTransformVU0(&point, &point, info->matrix);
    }
    NUVEC result;
    result.x = point.x;
    result.y = point.y;
    result.z = point.z;
    return result;
}

void SkinPlatform(terrsitu_s *terrain_group, unsigned char *buffer, PLATSKININFO *info) {
    TERRAIN_GROUP *group = reinterpret_cast<TERRAIN_GROUP *>(terrain_group);
    if (CurTerr == NULL || static_cast<u32>(group->chunk_type) > 1)
        return;
    TERRAIN_SHAPE_BATCH *input = static_cast<TERRAIN_SHAPE_BATCH *>(group->data);
    TERRAIN_SHAPE_BATCH *output = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(buffer);
    while (__builtin_expect(input->marker >= 0, 1)) {
        output->shape_count = input->shape_count;
        output->marker = input->marker;
        TERRAIN_SHAPE *destination = reinterpret_cast<TERRAIN_SHAPE *>(output + 1);
        TERRAIN_SHAPE *source = reinterpret_cast<TERRAIN_SHAPE *>(input + 1);
        f32 min_x = 123456792.0f, min_z = 123456792.0f;
        f32 max_x = -123456792.0f, max_z = -123456792.0f;
        TERRAIN_SHAPE *const first_shape = source;
        const i32 shape_count = input->shape_count;
        TERRAIN_SHAPE *const end_shape = shape_count > 0 ? source + shape_count : source;
        for (; source != end_shape; ++source, ++destination) {
            i32 last_vertex = source->normals[1].y > 65535.0f ? 2 : 3;
            *destination = *source;
            f32 shape_min_x = 123456792.0f, shape_min_y = 123456792.0f, shape_min_z = 123456792.0f;
            f32 shape_max_x = -123456792.0f, shape_max_y = -123456792.0f, shape_max_z = -123456792.0f;
            for (i32 vertex = last_vertex; vertex >= 0; --vertex) {
                i32 source_vertex = SkinFlipTab[vertex + info->mirrored * 4];
                NUVEC &v = destination->vectors[vertex];
                v = TerrainSkin(info, &source->vectors[source_vertex], -1.0f, info->flags);
                v.x -= info->matrix->m30;
                v.y -= info->matrix->m31;
                v.z -= info->matrix->m32;
                min_x = MIN(v.x, min_x);
                max_x = MAX(v.x, max_x);
                min_z = MIN(v.z, min_z);
                max_z = MAX(v.z, max_z);
                shape_min_x = MIN(v.x, shape_min_x);
                shape_min_y = MIN(v.y, shape_min_y);
                shape_min_z = MIN(v.z, shape_min_z);
                shape_max_x = MAX(v.x, shape_max_x);
                shape_max_y = MAX(v.y, shape_max_y);
                shape_max_z = MAX(v.z, shape_max_z);
            }
            destination->min_x = shape_min_x - 0.05f;
            destination->min_y = shape_min_y - 0.05f;
            destination->min_z = shape_min_z - 0.05f;
            destination->max_x = shape_max_x + 0.05f;
            destination->max_y = shape_max_y + 0.05f;
            destination->max_z = shape_max_z + 0.05f;
            if (__builtin_expect(source->normals[1].y < 65535.0f, 0)) {
                NUVEC a, b;
                a.x = destination->vectors[1].x - destination->vectors[3].x;
                a.y = destination->vectors[1].y - destination->vectors[3].y;
                a.z = destination->vectors[1].z - destination->vectors[3].z;
                b.x = destination->vectors[2].x - destination->vectors[3].x;
                b.y = destination->vectors[2].y - destination->vectors[3].y;
                b.z = destination->vectors[2].z - destination->vectors[3].z;
                NUVEC &n = destination->normals[1];
                n = TerCrossProduct(&a, &b);
                f32 length = NuFsqrt((n.x * n.x + n.y * n.y) + n.z * n.z);
                f32 inverse = length == 0.0f ? 0.0f : 1.0f / length;
                n.x *= inverse;
                n.y *= inverse;
                n.z = inverse * n.z;
            }
            {
                NUVEC a, b;
                a.x = destination->vectors[2].x - destination->vectors[0].x;
                a.y = destination->vectors[2].y - destination->vectors[0].y;
                b.x = destination->vectors[1].x - destination->vectors[0].x;
                a.z = destination->vectors[2].z - destination->vectors[0].z;
                b.y = destination->vectors[1].y - destination->vectors[0].y;
                b.z = destination->vectors[1].z - destination->vectors[0].z;
                NUVEC &n = destination->normals[0];
                n = TerCrossProduct(&a, &b);
                f32 length = NuFsqrt((n.x * n.x + n.y * n.y) + n.z * n.z);
                f32 inverse = length == 0.0f ? 0.0f : 1.0f / length;
                n.x *= inverse;
                n.y *= inverse;
                n.z = inverse * n.z;
            }
        }
        if (source != first_shape) {
            min_z -= 0.05f;
            min_x -= 0.05f;
            max_x += 0.05f;
            max_z += 0.05f;
        }
        output->min_x = min_x;
        output->max_x = max_x;
        output->min_z = min_z;
        output->max_z = max_z;
        input = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(source);
        output = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(destination);
    }
    output->marker = -1;
    output->shape_count = -1;
    group->data = buffer;
}

NUVEC TerrainStaticMtx(PLATSKININFO *info, nuvec_s *position, i32) {
    NUVEC4_ALIGNED16 point;
    point.x = position->x;
    point.y = position->y;
    point.z = position->z;
    point.w = 1.0f;
    NuVec4MtxTransformVU0(&point, &point, static_cast<NUMTX *>(info->matrix_data));
    NUVEC result;
    result.x = point.x;
    result.y = point.y;
    result.z = point.z;
    return result;
}

void TerrainSkinAllocate(terrsitu_s *terrain_group) {
    TERRAIN_GROUP *group = reinterpret_cast<TERRAIN_GROUP *>(terrain_group);
    i32 skin_index = ~static_cast<i32>(group->scene_index);
    if (skin_index >= PlatSkinCnt)
        return;
    ++TerrainUpadteCnt;
    if (group->data != NULL) {
        PLATSKININFO *info = &PlatSkinInfo[skin_index];
        SkinMemInfo[info->cache_slot].last_used = TerrainUpadteCnt;
        return;
    }
    i32 slot = 0;
    if (SkinMemInfo[0].skin_index != -1) {
        i32 oldest = SkinMemInfo[0].last_used;
        for (i32 i = 1; i < PlatSkinMaxStore; ++i) {
            if (SkinMemInfo[i].skin_index == -1) {
                slot = i;
                break;
            }
            if (SkinMemInfo[i].last_used < oldest) {
                oldest = SkinMemInfo[i].last_used;
                slot = i;
            }
        }
    }
    PLATSKINMEMINFO *cache = &SkinMemInfo[slot];
    if (cache->skin_index >= 0) {
        CurTerr->groups[PlatSkinInfo[cache->skin_index].terrain_group].data = NULL;
        for (i32 i = 0; i < 16; ++i)
            CurTerr->index_levels[i].entry_count = 0;
    }
    PLATSKININFO *info = &PlatSkinInfo[skin_index];
    info->cache_slot = slot;
    cache->skin_index = skin_index;
    group->data = info->terrain_data;
    SkinPlatform(terrain_group, PlatSkinMem + slot * PlatSkinMaxSize, info);
    SkinMemInfo[slot].last_used = TerrainUpadteCnt;
}

void DerotateMovementVector() {
    TerI->movement_yaw = static_cast<f32>(NuAtan2DA(TerI->movement.x, TerI->movement.z));
    const f32 horizontal_length = NuFsqrt(TerI->movement.x * TerI->movement.x + TerI->movement.z * TerI->movement.z);
    TerI->movement_pitch = static_cast<f32>(NuAtan2DA(-TerI->movement.y, horizontal_length));
    TerI->movement_length = NuFsqrt(TerI->movement.x * TerI->movement.x + TerI->movement.y * TerI->movement.y +
                                    TerI->movement.z * TerI->movement.z);
}

void RotateVec(NUVEC *source, NUVEC *destination) {
    TerrainQuery_s *query = TerI;
    const f32 pitch = query->movement_pitch;
    const f32 sin_pitch = NuTrigTable[(static_cast<i32>(pitch) >> 1) & (NUTRIGTABLE_COUNT - 1)];
    const f32 cos_pitch = NuTrigTable[(static_cast<i32>(pitch + 16384.0f) >> 1) & (NUTRIGTABLE_COUNT - 1)];

    const f32 z = source->z;
    const f32 y = source->y;
    const f32 rotated_z = y * sin_pitch + z * cos_pitch;
    destination->y = y * cos_pitch - z * sin_pitch;

    // The yaw table entries are read again after each destination store.
    const f32 yaw = query->movement_yaw;
    const i32 cos_yaw = (static_cast<i32>(yaw + 16384.0f) >> 1) & (NUTRIGTABLE_COUNT - 1);
    const f32 x = source->x;
    const i32 sin_yaw = (static_cast<i32>(yaw) >> 1) & (NUTRIGTABLE_COUNT - 1);
    destination->z = rotated_z * NuTrigTable[cos_yaw] - x * NuTrigTable[sin_yaw];
    destination->x = rotated_z * NuTrigTable[sin_yaw] + x * NuTrigTable[cos_yaw];
}

void RotateTerrain(tertype *surface) {
    TerrainQuery_s *query = TerI;
    const f32 pitch = query->movement_pitch;
    const f32 sin_pitch = NuTrigTable[(static_cast<i32>(pitch) >> 1) & (NUTRIGTABLE_COUNT - 1)];
    const f32 cos_pitch = NuTrigTable[(static_cast<i32>(pitch + 16384.0f) >> 1) & (NUTRIGTABLE_COUNT - 1)];
    const f32 yaw = query->movement_yaw;
    const f32 sin_yaw = NuTrigTable[(static_cast<i32>(yaw) >> 1) & (NUTRIGTABLE_COUNT - 1)];
    const f32 cos_yaw = NuTrigTable[(static_cast<i32>(yaw + 16384.0f) >> 1) & (NUTRIGTABLE_COUNT - 1)];

    for (i32 vertex_index = 0; vertex_index < 3; ++vertex_index) {
        const NUVEC &source = surface->vectors[vertex_index];
        NUVEC &destination = query->transformed_vertices[vertex_index];
        const f32 z = source.z;
        destination.y = source.y * cos_pitch - z * sin_pitch;
        const f32 x = source.x;
        const f32 rotated_z = source.y * sin_pitch + z * cos_pitch;
        destination.z = rotated_z * cos_yaw - x * sin_yaw;
        destination.x = rotated_z * sin_yaw + x * cos_yaw;
    }
    if (65536.0f > surface->normals[1].y) {
        const NUVEC &source = surface->vectors[3];
        NUVEC &destination = query->transformed_vertices[3];
        const f32 z = source.z;
        destination.y = source.y * cos_pitch - z * sin_pitch;
        const f32 x = source.x;
        const f32 rotated_z = source.y * sin_pitch + z * cos_pitch;
        destination.z = rotated_z * cos_yaw - x * sin_yaw;
        destination.x = rotated_z * sin_yaw + x * cos_yaw;
    }
}

void DeRotateTerrain(tertype *surface) {
    TerrainQuery_s *query = TerI;

    const f32 sin_pitch = NuTrigTable[(static_cast<i32>(-query->movement_pitch) >> 1) & 0x7fff];
    const f32 cos_pitch = NuTrigTable[(static_cast<i32>(16384.0f - query->movement_pitch) >> 1) & 0x7fff];
    const f32 sin_yaw = NuTrigTable[(static_cast<i32>(-query->movement_yaw) >> 1) & 0x7fff];
    const f32 start_z = query->local_start.z;
    const f32 cos_yaw = NuTrigTable[(static_cast<i32>(16384.0f - query->movement_yaw) >> 1) & 0x7fff];
    const f32 start_y = query->local_start.y;

    for (i32 vertex_index = 0; vertex_index < 3; ++vertex_index) {
        const NUVEC &vertex = surface->vectors[vertex_index];
        NUVEC &transformed = query->transformed_vertices[vertex_index];
        const f32 relative_z = vertex.z - start_z;
        const f32 relative_x = vertex.x - query->local_start.x;
        const f32 rotated_x = relative_z * sin_yaw + relative_x * cos_yaw;
        const f32 rotated_z = relative_z * cos_yaw - relative_x * sin_yaw;

        transformed.x = rotated_x;
        transformed.y = (vertex.y - start_y) * cos_pitch - rotated_z * sin_pitch;
        transformed.z = (vertex.y - start_y) * sin_pitch + rotated_z * cos_pitch;
    }

    if (__builtin_expect(65536.0f > surface->normals[1].y, 1)) {
        const NUVEC &vertex = surface->vectors[3];
        NUVEC &transformed = query->transformed_vertices[3];
        const f32 relative_z = vertex.z - start_z;
        const f32 relative_x = vertex.x - query->local_start.x;
        const f32 rotated_x = relative_z * sin_yaw + relative_x * cos_yaw;
        const f32 rotated_z = relative_z * cos_yaw - relative_x * sin_yaw;

        transformed.x = rotated_x;
        transformed.y = (vertex.y - start_y) * cos_pitch - rotated_z * sin_pitch;
        transformed.z = (vertex.y - start_y) * sin_pitch + rotated_z * cos_pitch;
    }
}

void DeRotatePoint(nuvec_s *point) {
    TerrainQuery_s *query = TerI;

    const f32 sin_pitch = NuTrigTable[(static_cast<i32>(-query->movement_pitch) >> 1) & 0x7fff];
    const f32 cos_pitch = NuTrigTable[(static_cast<i32>(16384.0f - query->movement_pitch) >> 1) & 0x7fff];
    const f32 sin_yaw = NuTrigTable[(static_cast<i32>(-query->movement_yaw) >> 1) & 0x7fff];
    const f32 cos_yaw = NuTrigTable[(static_cast<i32>(16384.0f - query->movement_yaw) >> 1) & 0x7fff];

    const f32 relative_z = point->z - query->position.z;
    const f32 relative_x = point->x - query->position.x;

    const f32 rotated_x = relative_z * sin_yaw + relative_x * cos_yaw;
    const f32 rotated_z = relative_z * cos_yaw - relative_x * sin_yaw;

    point->x = rotated_x;
    const f32 relative_y = point->y + query->collision_radius - query->position.y;
    point->z = relative_y * sin_pitch + rotated_z * cos_pitch;
    point->y = relative_y * cos_pitch - rotated_z * sin_pitch;
}

i16 InsideLineF(f32 point_u, f32 point_v, f32 line_start_u, f32 line_start_v, f32 line_end_u, f32 line_end_v) {
    const f32 side =
        (point_u - line_start_u) * (line_end_v - line_start_v) + (point_v - line_start_v) * (line_start_u - line_end_u);
    if (side < 0.0f) {
        return 0;
    }
    return 1;
}

i16 InsidePolLines(f32 point_x, f32 point_y, f32 point_z, f32 edge_a_x, f32 edge_a_y, f32 edge_a_z, f32 edge_b_x,
                   f32 edge_b_y, f32 edge_b_z, NUVEC *normal) {
    // Project onto the plane perpendicular to the dominant normal component.
    // The call order preserves the polygon winding in that projection.
    if (NuFabs(normal->y) >= NuFabs(normal->x) && NuFabs(normal->y) >= NuFabs(normal->z)) {
        if (0.0f > normal->y) {
            if (InsideLineF(point_x, point_z, 0.0f, 0.0f, edge_a_x, edge_a_z) == 0 ||
                InsideLineF(point_x, point_z, edge_b_x, edge_b_z, 0.0f, 0.0f) == 0) {
                return 0;
            }
            return InsideLineF(point_x, point_z, edge_a_x, edge_a_z, edge_b_x, edge_b_z) != 0;
        }

        if (InsideLineF(point_x, point_z, edge_a_x, edge_a_z, 0.0f, 0.0f) == 0 ||
            InsideLineF(point_x, point_z, 0.0f, 0.0f, edge_b_x, edge_b_z) == 0) {
            return 0;
        }
        return InsideLineF(point_x, point_z, edge_b_x, edge_b_z, edge_a_x, edge_a_z) != 0;
    }

    if (!(NuFabs(normal->y) <= NuFabs(normal->x)) || !(NuFabs(normal->z) <= NuFabs(normal->x))) {
        if (0.0f > normal->z) {
            if (InsideLineF(point_y, point_x, 0.0f, 0.0f, edge_a_y, edge_a_x) == 0 ||
                InsideLineF(point_y, point_x, edge_b_y, edge_b_x, 0.0f, 0.0f) == 0) {
                return 0;
            }
            return InsideLineF(point_y, point_x, edge_a_y, edge_a_x, edge_b_y, edge_b_x) != 0;
        }

        if (InsideLineF(point_y, point_x, edge_a_y, edge_a_x, 0.0f, 0.0f) == 0 ||
            InsideLineF(point_y, point_x, 0.0f, 0.0f, edge_b_y, edge_b_x) == 0) {
            return 0;
        }
        return InsideLineF(point_y, point_x, edge_b_y, edge_b_x, edge_a_y, edge_a_x) != 0;
    }

    if (0.0f > normal->x) {
        if (InsideLineF(point_y, point_z, edge_a_y, edge_a_z, 0.0f, 0.0f) == 0 ||
            InsideLineF(point_y, point_z, 0.0f, 0.0f, edge_b_y, edge_b_z) == 0) {
            return 0;
        }
        return InsideLineF(point_y, point_z, edge_b_y, edge_b_z, edge_a_y, edge_a_z) != 0;
    }

    if (InsideLineF(point_y, point_z, 0.0f, 0.0f, edge_a_y, edge_a_z) == 0 ||
        InsideLineF(point_y, point_z, edge_b_y, edge_b_z, 0.0f, 0.0f) == 0) {
        return 0;
    }
    return InsideLineF(point_y, point_z, edge_a_y, edge_a_z, edge_b_y, edge_b_z) != 0;
}

TERRAIN_TRACK_SLOT *ScanTerrId(void *id) {
    TERRSET *terrain = CurTerr;
    if (terrain == NULL) {
        return NULL;
    }

    for (i32 slot_index = 0; slot_index < TERRAIN_TRACK_SLOT_COUNT; ++slot_index) {
        if (terrain->track_slots[slot_index].id == id) {
            return &terrain->track_slots[slot_index];
        }
    }

    return NULL;
}

void ScanTerrIDRemovePlat(i32 platform_index) {
    for (i32 i = 0; i < TERRAIN_TRACK_SLOT_COUNT; ++i) {
        if (CurTerr->track_slots[i].platform_index == platform_index) {
            CurTerr->track_slots[i].id = NULL;
        }
    }
}

extern "C" {
extern "C" {
    extern "C++" TERRAIN_TRACK_SLOT *AllocTerrId() {
        TERRSET *terrain = CurTerr;
        if (terrain == NULL) {
            return NULL;
        }

        for (i32 slot_index = 0; slot_index < TERRAIN_TRACK_SLOT_COUNT; ++slot_index) {
            if (terrain->track_slots[slot_index].id == NULL) {
                return &terrain->track_slots[slot_index];
            }
        }

        return NULL;
    }

}
}

extern "C" {
    i32 TerrainFreeId(void *id) {
        if (CurTerr != NULL) {
            for (i32 i = 0; i < 64; ++i) {
                if (CurTerr->track_slots[i].id == id) {
                    CurTerr->track_slots[i].id = NULL;
                    return 1;
                }
            }
        }
        return 0;
    }

extern "C" void TerrainTrackFlush(void) {
    if (CurTerr == NULL) {
        return;
    }

    for (i32 slot_index = 0; slot_index < TERRAIN_TRACK_SLOT_COUNT; ++slot_index) {
        CurTerr->track_slots[slot_index].id = NULL;
    }
}

}

void NewScan(nuvec_s *position, i32 terrain_mask, i32 scan_platforms) {
    const f32 position_x = position->x;
    const f32 position_z = position->z;
    i32 cache_index = 0;
    i32 oldest_age = CurTerr->index_levels[0].cache_age;
    bool cache_hit = false;
    for (i32 i = 0; i < 16; ++i) {
        TERRAIN_INDEX_LEVEL &candidate = CurTerr->index_levels[i];
        if (candidate.cache_age > 0) {
            const f32 dx = (position_x + 1.0f) - candidate.center_x;
            const f32 dz = (position_z + 1.0f) - candidate.center_z;
            if (dx < 2.0f && dz < 2.0f && dx > 0.0f && dz > 0.0f) {
                cache_index = i;
                cache_hit = true;
                break;
            }
        }
        if (candidate.cache_age < oldest_age) {
            oldest_age = candidate.cache_age;
            cache_index = i;
        }
    }

    TERRAIN_INDEX_LEVEL &cache = CurTerr->index_levels[cache_index];
    const bool fill_cache = !cache_hit;
    ShadowScanWriter writer;
    writer.group_header = fill_cache ? cache.scan_list : TerI->scan_list_storage;
    writer.cursor = reinterpret_cast<TERRAIN_SHAPE **>(writer.group_header + sizeof(TERRAIN_SHAPE *));
    writer.limit = writer.group_header + 0x7f4;
    writer.shape_count = 0;

    const f32 extent = fill_cache ? 1.0f : SHADOW_SCAN_HALF_EXTENT;
    f32 min_x = position_x - extent;
    f32 max_x = position_x + extent;
    f32 min_z = position_z - extent;
    f32 max_z = position_z + extent;

    if (!cache_hit) {
        for (i32 cell_index = 0; cell_index < CurTerr->used_cell_count; ++cell_index) {
            const TERRAIN_CELL &cell = CurTerr->cells[cell_index];
            if (!(max_x >= cell.min_x && max_z >= cell.min_z && cell.max_x >= min_x && !(cell.max_z < min_z))) {
                continue;
            }
            const i16 *group_indices = CurTerr->group_indices + cell.first_group;
            for (i32 cell_group = 0; cell_group < static_cast<i16>(cell.group_count); ++cell_group) {
                // Cache geometry independently of the requesting material mask.
                const i32 group_index = group_indices[cell_group];
                TERRAIN_GROUP &group = CurTerr->groups[group_index];
                if (__builtin_expect(!(max_x >= group.bounds_min.x && max_z >= group.bounds_min.z && group.bounds_max.x >= min_x &&
                      group.bounds_max.z > min_z) ||
                    group.chunk_type == -1, 0))
                    continue;
                const f32 local_max_z = max_z - group.origin.z;
                const f32 local_max_x = max_x - group.origin.x;
                const f32 local_min_x = min_x - group.origin.x;
                const f32 local_min_z = min_z - group.origin.z;
                if (group.scene_index < 0)
                    TerrainSkinAllocate(reinterpret_cast<terrsitu_s *>(&group));
                TERRAIN_SHAPE_BATCH *batch = static_cast<TERRAIN_SHAPE_BATCH *>(group.data);
                while (batch->marker >= 0) {
                    const i16 count = batch->shape_count;
                    TERRAIN_SHAPE *shape = reinterpret_cast<TERRAIN_SHAPE *>(batch + 1);
                    if (!(local_max_x < batch->min_x) && batch->max_x > local_min_x && local_max_z >= batch->min_z &&
                        batch->max_z > local_min_z) {
                        i32 remaining = count;
                        while (remaining > 0) {
                            if (local_max_x >= shape->min_x && shape->max_x > local_min_x &&
                                local_max_z >= shape->min_z && shape->max_z > local_min_z &&
                                reinterpret_cast<u8 *>(writer.cursor) < writer.limit) {
                                *writer.cursor++ = shape;
                                ++writer.shape_count;
                            }
                            ++shape;
                            --remaining;
                        }
                    } else
                        shape += count;
                    batch = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(shape);
                }
                ShadowFinishGroup(&writer, group_index);
            }
        }
    }

    if (fill_cache) {
        i16 *terminator = reinterpret_cast<i16 *>(writer.group_header);
        terminator[0] = 0;
        cache.center_x = position->x;
        cache.center_z = position->z;
        terminator[1] = 0;
    }

    if (fill_cache || cache_hit) {
        cache.cache_age = 8;
        writer.group_header = TerI->scan_list_storage;
        writer.cursor = reinterpret_cast<TERRAIN_SHAPE **>(writer.group_header + sizeof(TERRAIN_SHAPE *));
        writer.limit = writer.group_header + 0x7f4;
        writer.shape_count = 0;
        min_x = position_x - SHADOW_SCAN_HALF_EXTENT;
        min_z = position_z - SHADOW_SCAN_HALF_EXTENT;
        max_z = position_z + SHADOW_SCAN_HALF_EXTENT;
        max_x = position_x + SHADOW_SCAN_HALF_EXTENT;

        u8 *entry = cache.scan_list;
        for (;;) {
            const i16 count = reinterpret_cast<i16 *>(entry)[0];
            if (count <= 0) {
                break;
            }
            const i16 group_index = reinterpret_cast<i16 *>(entry)[1];
            TERRAIN_SHAPE **shapes = reinterpret_cast<TERRAIN_SHAPE **>(entry + sizeof(TERRAIN_SHAPE *));
            entry = reinterpret_cast<u8 *>(shapes + count);
            TERRAIN_GROUP &group = CurTerr->groups[group_index];
            if (__builtin_expect(!(max_x >= group.bounds_min.x && max_z >= group.bounds_min.z && group.bounds_max.x >= min_x &&
                  group.bounds_max.z > min_z) ||
                group.chunk_type == -1, 1)) {
                continue;
            }

            const f32 local_max_x = max_x - group.origin.x;
            const f32 local_min_x = min_x - group.origin.x;
            const f32 local_max_z = max_z - group.origin.z;
            const f32 local_min_z = min_z - group.origin.z;
            TERRAIN_SHAPE **shape_entry = shapes;
            for (i32 remaining = count; remaining > 0; --remaining, ++shape_entry) {
                TERRAIN_SHAPE *shape = *shape_entry;
                if (__builtin_expect(!(local_max_x >= shape->min_x && shape->max_x > local_min_x && local_max_z >= shape->min_z &&
                      shape->max_z > local_min_z), 0)) {
                    continue;
                }
                if (shape->material[1] != 0 && (shape->material[1] & terrain_mask) == 0) {
                    continue;
                }
                if (reinterpret_cast<u8 *>(writer.cursor) >= writer.limit) {
                    continue;
                }
                *writer.cursor++ = shape;
                ++writer.shape_count;
            }
            ShadowFinishGroup(&writer, group_index);
        }
    }

    if (scan_platforms != 0) {
        min_x -= 0.05f;
        min_z -= 0.05f;
        max_x += 0.05f;
        max_z += 0.05f;
        // This scan uses the complete platform cell, not NewScanRot's active cache.
        const TERRAIN_CELL &cell = CurTerr->cells[TERRAIN_PLATFORM_CELL];
        const i16 *platform_groups = CurTerr->group_indices + cell.first_group;
        const i32 platform_count = static_cast<i16>(cell.group_count);

        for (i32 platform_index = 0; platform_index < platform_count; ++platform_index) {
            const i32 group_index = platform_groups[platform_index];
            TERRAIN_GROUP &group = CurTerr->groups[group_index];
            TERRAIN_PLATFORM &platform = CurTerr->platforms[group.scene_index];
            if (__builtin_expect(platform.scene_transform != NULL, 1)) {
                const u8 visible_mask = (platform.flags & TERRAIN_PLATFORM_FLAG_DISPLAY_LIST_BACKED) != 0 ? 2 : 1;
                if (__builtin_expect((*static_cast<u8 *>(platform.scene_transform) & visible_mask) == 0, 0)) {
                    continue;
                }
            }

            f32 local_max_x = max_x - group.origin.x;
            f32 local_min_x = min_x - group.origin.x;
            f32 local_min_z = min_z - group.origin.z;
            f32 local_max_z = max_z - group.origin.z;
            NUMTX *matrix = static_cast<NUMTX *>(platform.scene_object);
            if (__builtin_expect(matrix != NULL, 1)) {
                if (matrix->m30 > platform.previous_matrix.m30)
                    local_max_x = (matrix->m30 - platform.previous_matrix.m30) * 1.5f + max_x - group.origin.x;
                else
                    local_min_x = (matrix->m30 - platform.previous_matrix.m30) * 1.5f + min_x - group.origin.x;
                if (__builtin_expect(matrix->m32 > platform.previous_matrix.m32, 1))
                    local_max_z = (matrix->m32 - platform.previous_matrix.m32) * 1.5f + max_z - group.origin.z;
                else
                    local_min_z = (matrix->m32 - platform.previous_matrix.m32) * 1.5f + min_z - group.origin.z;
            }
            if (__builtin_expect(!ShadowBoundsOverlap(local_min_x, local_min_z, local_max_x, local_max_z, group.bounds_min,
                                     group.bounds_max) ||
                group.chunk_type == -1, 0)) {
                continue;
            }

            TERRAIN_SHAPE_BATCH *batch = static_cast<TERRAIN_SHAPE_BATCH *>(group.data);
            while (batch->marker >= 0) {
                TERRAIN_SHAPE *shapes = reinterpret_cast<TERRAIN_SHAPE *>(batch + 1);
                if (local_max_x >= batch->min_x && batch->max_x > local_min_x && local_max_z >= batch->min_z &&
                    batch->max_z > local_min_z) {
                    TERRAIN_SHAPE *shape = shapes;
                    for (i32 remaining = batch->shape_count; remaining > 0; --remaining, ++shape) {
                        if (!(local_max_x >= shape->min_x && shape->max_x > local_min_x &&
                              local_max_z >= shape->min_z && shape->max_z > local_min_z)) {
                            continue;
                        }
                        if (reinterpret_cast<u8 *>(writer.cursor) >= writer.limit) {
                            continue;
                        }
                        if (shape->material[1] != 0 && (shape->material[1] & terrain_mask) == 0) {
                            continue;
                        }
                        *writer.cursor++ = shape;
                        ++writer.shape_count;
                    }
                }
                batch = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(shapes + batch->shape_count);
            }
            ShadowFinishGroup(&writer, group_index);
        }
    }

    i16 *terminator = reinterpret_cast<i16 *>(writer.group_header);
    terminator[0] = 0;
    terminator[1] = 0;
}

void NewScanRot(nuvec_s *position, i32 terrain_mask) {
    void *scratch = NuScratchAlloc32(0xd0);
    const f32 position_z = position->z;
    i32 cache_index = 0;
    bool cache_hit = false;
    i16 oldest_age = CurTerr->index_levels[0].cache_age;
    for (i32 i = 0; i < 16; ++i) {
        TERRAIN_INDEX_LEVEL &cache = CurTerr->index_levels[i];
        i16 age = cache.cache_age;
        if (age > 0) {
            f32 dx = (position->x + 1.0f) - cache.center_x;
            if (dx > 0.0f && dx < 2.0f) {
                f32 dz = (position_z + 1.0f) - cache.center_z;
                if (dz > 0.0f && !(dz >= 2.0f)) {
                    cache_index = i;
                    cache_hit = true;
                    break;
                }
            }
        }
        if (age < oldest_age) {
            oldest_age = age;
            cache_index = i;
        }
    }
    TERRAIN_INDEX_LEVEL &cache = CurTerr->index_levels[cache_index];
    bool fill_cache = !cache_hit && cache.cache_age <= 1;
    ShadowScanWriter writer;
    if (fill_cache) {
        writer.group_header = cache.scan_list;
    } else {
        writer.group_header = TerI->scan_list_storage;
    }
    writer.cursor = reinterpret_cast<TERRAIN_SHAPE **>(writer.group_header + sizeof(TERRAIN_SHAPE *));
    // Target stops at TerI + 0x93c, leaving the final header slot available.
    writer.limit = writer.group_header + 0x7f4;
    writer.shape_count = 0;

    const f32 extent = fill_cache ? 1.0f : SHADOW_SCAN_HALF_EXTENT;
    f32 min_x = position->x - extent;
    f32 max_x = position->x + extent;
    f32 min_z = position_z - extent;
    f32 max_z = position_z + extent;

    if (!cache_hit) {
        for (i32 cell_index = 0; cell_index < CurTerr->used_cell_count; ++cell_index) {
            const TERRAIN_CELL &cell = CurTerr->cells[cell_index];
            if (!(max_x >= cell.min_x && cell.max_x >= min_x && max_z >= cell.min_z && cell.max_z >= min_z)) {
                continue;
            }
            const i16 *group_indices = CurTerr->group_indices + cell.first_group;
            for (i32 cell_group = 0; cell_group < static_cast<i16>(cell.group_count); ++cell_group) {
                const i32 group_index = group_indices[cell_group];
                TERRAIN_GROUP &group = CurTerr->groups[group_index];
                if (!(max_x >= group.bounds_min.x && max_z >= group.bounds_min.z && group.bounds_max.x >= min_x &&
                      group.bounds_max.z > min_z) ||
                    group.chunk_type == -1) {
                    continue;
                }
                const f32 local_max_x = max_x - group.origin.x;
                const f32 local_max_z = max_z - group.origin.z;
                const f32 local_min_x = min_x - group.origin.x;
                const f32 local_min_z = min_z - group.origin.z;
                if (group.scene_index < 0) {
                    TerrainSkinAllocate(reinterpret_cast<terrsitu_s *>(&group));
                }
                TERRAIN_SHAPE_BATCH *batch = static_cast<TERRAIN_SHAPE_BATCH *>(group.data);
                while (batch->marker >= 0) {
                    TERRAIN_SHAPE *shapes = reinterpret_cast<TERRAIN_SHAPE *>(batch + 1);
                    const i32 count = batch->shape_count;
                    if (local_max_x >= batch->min_x && batch->max_x > local_min_x && !(local_max_z < batch->min_z) &&
                        !(batch->max_z <= local_min_z)) {
                        TERRAIN_SHAPE *shape = shapes;
                        for (i32 remaining = count; remaining > 0; --remaining, ++shape) {
                            if (__builtin_expect(
                                    !(shape->min_x > local_max_x) && !(local_min_x >= shape->max_x) &&
                                        shape->min_z <= local_max_z && local_min_z < shape->max_z &&
                                        reinterpret_cast<u8 *>(writer.cursor) < writer.limit &&
                                        (shape->material[1] == 0 || (shape->material[1] & terrain_mask) != 0),
                                    1)) {
                                *writer.cursor++ = shape;
                                ++writer.shape_count;
                            }
                        }
                    }
                    batch = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(shapes + count);
                }
                ShadowFinishGroup(&writer, group_index);
            }
        }
        // Skin allocation can invalidate the cache while scanning groups.
        fill_cache = cache.cache_age <= 1;
    }
    if (__builtin_expect(fill_cache, 0)) {
        reinterpret_cast<i16 *>(writer.group_header)[0] = 0;
        reinterpret_cast<i16 *>(writer.group_header)[1] = 0;
        cache.center_z = position->z;
        cache.center_x = position->x;
    }
    if (fill_cache || cache_hit) {
        cache.cache_age = 8;
        writer.group_header = TerI->scan_list_storage;
        writer.cursor = reinterpret_cast<TERRAIN_SHAPE **>(writer.group_header + sizeof(TERRAIN_SHAPE *));
        writer.limit = writer.group_header + 0x7f4;
        max_x = position->x + SHADOW_SCAN_HALF_EXTENT;
        min_x = position->x - SHADOW_SCAN_HALF_EXTENT;
        min_z = position_z - SHADOW_SCAN_HALF_EXTENT;
        max_z = position_z + SHADOW_SCAN_HALF_EXTENT;
        u8 *entry = cache.scan_list;
        for (;;) {
            i32 count = reinterpret_cast<i16 *>(entry)[0];
            if (count <= 0)
                break;
            i16 group_index = reinterpret_cast<i16 *>(entry)[1];
            TERRAIN_SHAPE **shapes = reinterpret_cast<TERRAIN_SHAPE **>(entry + sizeof(TERRAIN_SHAPE *));
            entry = reinterpret_cast<u8 *>(shapes + count);
            TERRAIN_GROUP &group = CurTerr->groups[group_index];
            if (!ShadowBoundsOverlap(min_x, min_z, max_x, max_z, group.bounds_min, group.bounds_max) ||
                group.chunk_type == -1)
                continue;
            f32 local_min_x = min_x - group.origin.x, local_max_x = max_x - group.origin.x;
            f32 local_min_z = min_z - group.origin.z, local_max_z = max_z - group.origin.z;
            for (i32 i = 0; i < count; ++i) {
                TERRAIN_SHAPE *shape = shapes[i];
                if (!(local_max_x >= shape->min_x && shape->max_x > local_min_x && local_max_z >= shape->min_z &&
                      shape->max_z > local_min_z))
                    continue;
                if (__builtin_expect(shape->material[1] != 0 && (shape->material[1] & terrain_mask) == 0, 0))
                    continue;
                if (reinterpret_cast<u8 *>(writer.cursor) >= writer.limit)
                    continue;
                *writer.cursor++ = shape;
                ++writer.shape_count;
            }
            ShadowFinishGroup(&writer, group_index);
        }
    }

    if (NuTerrPlatsOff == 0) {
        min_x -= 0.05f;
        min_z -= 0.05f;
        max_x += 0.05f;
        max_z += 0.05f;
        i16 *platform_groups = CurTerr->active_platform_groups;
        i32 platform_count = CurTerr->active_platform_count;
        if (!(min_x > CurTerr->platform_scan_min.x && max_x < CurTerr->platform_scan_max.x &&
              min_z > CurTerr->platform_scan_min.z && max_z < CurTerr->platform_scan_max.z)) {
            TERRAIN_CELL &cell = CurTerr->cells[TERRAIN_PLATFORM_CELL];
            platform_groups = CurTerr->group_indices + cell.first_group;
            platform_count = static_cast<i16>(cell.group_count);
        }
        NUVEC4 *vertices = reinterpret_cast<NUVEC4 *>((reinterpret_cast<uintptr_t>(scratch) + 31) & ~uintptr_t(15));
        i32 transformed_count = 0;
        for (i32 p = 0; p < platform_count; ++p) {
            i32 group_index = platform_groups[p];
            TERRAIN_GROUP &group = CurTerr->groups[group_index];
            if (group.origin.x - group.radius > max_x || min_x > group.origin.x + group.radius ||
                group.origin.z - group.radius > max_z || min_z > group.origin.z + group.radius)
                continue;
            TERRAIN_PLATFORM &platform = CurTerr->platforms[group.scene_index];
            f32 local_min_z = min_z - group.origin.z, local_max_z = max_z - group.origin.z;
            f32 local_min_x = min_x - group.origin.x, local_max_x = max_x - group.origin.x;
            NUMTX *matrix = static_cast<NUMTX *>(platform.scene_object);
            if (matrix != NULL) {
                if (matrix->m30 > platform.previous_matrix.m30)
                    local_max_x = (matrix->m30 - platform.previous_matrix.m30) * 1.5f + max_x - group.origin.x;
                else
                    local_min_x = (matrix->m30 - platform.previous_matrix.m30) * 1.5f + min_x - group.origin.x;
                if (__builtin_expect(!(matrix->m32 <= platform.previous_matrix.m32), 1))
                    local_max_z = (matrix->m32 - platform.previous_matrix.m32) * 1.5f + max_z - group.origin.z;
                else
                    local_min_z = (matrix->m32 - platform.previous_matrix.m32) * 1.5f + min_z - group.origin.z;
            }
            bool rotating = (platform.flags & 1) != 0;
            if (!rotating) {
                if (!ShadowBoundsOverlap(local_min_x, local_min_z, local_max_x, local_max_z, group.bounds_min,
                                         group.bounds_max) ||
                    group.chunk_type == -1) {
                    continue;
                }
            } else {
                if (group.chunk_type == -1)
                    continue;
                f32 dz = (min_z + max_z) * 0.5f - group.origin.z;
                f32 dx = (max_x + min_x) * 0.5f - group.origin.x;
                f32 radius = group.radius + 0.00001f;
                if (!(radius * radius > dx * dx + dz * dz))
                    continue;
            }
            if (platform.scene_transform != NULL &&
                (*static_cast<u8 *>(platform.scene_transform) & ((platform.flags & 4) != 0 ? 2 : 1)) == 0)
                continue;
            TERRAIN_SHAPE_BATCH *batch = static_cast<TERRAIN_SHAPE_BATCH *>(group.data);
            while (batch->marker >= 0) {
                TERRAIN_SHAPE *shapes = reinterpret_cast<TERRAIN_SHAPE *>(batch + 1);
                bool batch_overlaps = rotating || (local_max_x >= batch->min_x && batch->max_x > local_min_x &&
                                                   local_max_z >= batch->min_z && batch->max_z > local_min_z);
                for (i32 i = 0; batch_overlaps && i < batch->shape_count; ++i) {
                    TERRAIN_SHAPE *shape = &shapes[i];
                    if (shape->material[1] != 0 && (shape->material[1] & terrain_mask) == 0)
                        continue;
                    if (reinterpret_cast<u8 *>(writer.cursor) >= writer.limit)
                        continue;
                    if (!rotating) {
                        if (!(local_max_x >= shape->min_x && shape->max_x > local_min_x &&
                              local_max_z >= shape->min_z && shape->max_z > local_min_z))
                            continue;
                    } else {
                        for (i32 v = 0; v < 3; ++v) {
                            vertices[v].x = shape->vectors[v].x;
                            vertices[v].y = shape->vectors[v].y;
                            vertices[v].z = shape->vectors[v].z;
                            vertices[v].w = 0.0f;
                        }
                        NuVec4MtxTransformVU0x3(vertices, vertices, matrix);
                        bool quad = shape->normals[1].y < 65535.0f;
                        if (quad) {
                            vertices[3].w = 0.0f;
                            vertices[3].y = shape->vectors[3].y;
                            vertices[3].x = shape->vectors[3].x;
                            vertices[3].z = shape->vectors[3].z;
                            NuVec4MtxTransformVU0(&vertices[3], &vertices[3], matrix);
                        } else
                            vertices[3] = vertices[2];
                        if (!(!(vertices[0].x <= local_min_x) || vertices[1].x > local_min_x ||
                              vertices[2].x > local_min_x || vertices[3].x > local_min_x))
                            continue;
                        if (!(!(local_max_x <= vertices[0].x) || local_max_x > vertices[1].x ||
                              local_max_x > vertices[2].x || local_max_x > vertices[3].x))
                            continue;
                        if (__builtin_expect(!(vertices[0].z > local_min_z || vertices[1].z > local_min_z ||
                                               vertices[2].z > local_min_z || vertices[3].z > local_min_z),
                                             0))
                            continue;
                        if (!(local_max_z > vertices[0].z || local_max_z > vertices[1].z ||
                              local_max_z > vertices[2].z || local_max_z > vertices[3].z))
                            continue;
                        TERRAIN_SHAPE *transformed = &ScaleTerrain[transformed_count];
                        memcpy(transformed->material, shape->material, 4);
                        for (i32 v = 0; v < 3; ++v) {
                            transformed->vectors[v].x = vertices[v].x;
                            transformed->vectors[v].y = vertices[v].y;
                            transformed->vectors[v].z = vertices[v].z;
                        }
                        if (shape->normals[1].y < 65535.0f) {
                            transformed->vectors[3].x = vertices[3].x;
                            transformed->vectors[3].y = vertices[3].y;
                            transformed->vectors[3].z = vertices[3].z;
                            vertices[0].x = transformed->vectors[1].x - transformed->vectors[3].x;
                            vertices[0].z = transformed->vectors[1].z - transformed->vectors[3].z;
                            vertices[1].x = transformed->vectors[2].x - transformed->vectors[3].x;
                            vertices[0].y = transformed->vectors[1].y - transformed->vectors[3].y;
                            vertices[1].y = transformed->vectors[2].y - transformed->vectors[3].y;
                            vertices[1].z = transformed->vectors[2].z - transformed->vectors[3].z;
                            transformed->normals[1] = TerCrossProduct(reinterpret_cast<NUVEC *>(&vertices[0]),
                                                                      reinterpret_cast<NUVEC *>(&vertices[1]));
                            f32 length = NuFsqrt((transformed->normals[1].x * transformed->normals[1].x +
                                                  transformed->normals[1].y * transformed->normals[1].y) +
                                                 transformed->normals[1].z * transformed->normals[1].z);
                            f32 inverse = length == 0.0f ? 0.0f : 1.0f / length;
                            transformed->normals[1].x *= inverse;
                            transformed->normals[1].y *= inverse;
                            transformed->normals[1].z *= inverse;
                        } else {
                            transformed->normals[1].y = 65536.0f;
                        }
                        vertices[0].x = transformed->vectors[2].x - transformed->vectors[0].x;
                        vertices[0].y = transformed->vectors[2].y - transformed->vectors[0].y;
                        vertices[0].z = transformed->vectors[2].z - transformed->vectors[0].z;
                        vertices[1].x = transformed->vectors[1].x - transformed->vectors[0].x;
                        vertices[1].y = transformed->vectors[1].y - transformed->vectors[0].y;
                        vertices[1].z = transformed->vectors[1].z - transformed->vectors[0].z;
                        transformed->normals[0] = TerCrossProduct(reinterpret_cast<NUVEC *>(&vertices[0]),
                                                                  reinterpret_cast<NUVEC *>(&vertices[1]));
                        f32 length = NuFsqrt((transformed->normals[0].x * transformed->normals[0].x +
                                              transformed->normals[0].y * transformed->normals[0].y) +
                                             transformed->normals[0].z * transformed->normals[0].z);
                        f32 inverse = length == 0.0f ? 0.0f : 1.0f / length;
                        transformed->normals[0].x *= inverse;
                        transformed->normals[0].y *= inverse;
                        transformed->normals[0].z *= inverse;
                        shape = transformed;
                        ++transformed_count;
                    }
                    *writer.cursor++ = shape;
                    ++writer.shape_count;
                }
                batch = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(shapes + batch->shape_count);
            }
            ShadowFinishGroup(&writer, group_index);
        }
    }
    NuScratchRelease();
    i16 *terminator = reinterpret_cast<i16 *>(writer.group_header);
    terminator[0] = 0;
    terminator[1] = 0;
}

f32 NewCast(nuvec_s *position, f32 height_above, f32 roof_range) {
    u8 *scan = TerI->scan_list_storage;
    TERRAIN_SHAPE *floor_poly = NULL;
    TERRAIN_SHAPE *roof_poly = NULL;
    TERRAIN_SHAPE *efloor_poly = NULL;
    TERRAIN_SHAPE *eroof_poly = NULL;
    f32 floor_y = -2000000.0f;
    f32 efloor_y = -2000000.0f;
    f32 roof_y = 2000000.0f;
    f32 eroof_y = 2000000.0f;
    i16 roof_group = -1;
    i16 eroof_group = -1;
    f32 floor_nx, floor_ny, floor_nz;
    f32 efloor_nx, efloor_ny, efloor_nz;
    f32 roof_nx, roof_ny, roof_nz;
    f32 eroof_nx, eroof_ny, eroof_nz;
    i16 shape_count;

    castnum = -1;
    ecastnum = -1;
    shape_count = *reinterpret_cast<i16 *>(scan);
    while (shape_count > 0) {
        i32 group_index = reinterpret_cast<i16 *>(scan)[1];
        TERRAIN_SHAPE **surfaces = reinterpret_cast<TERRAIN_SHAPE **>(scan + 4);
        f32 x = position->x - CurTerr->groups[group_index].origin.x;
        f32 z = position->z - CurTerr->groups[group_index].origin.z;
        TERRAIN_SHAPE **next_surface = surfaces;
        for (i32 i = shape_count; i != 0; i--) {
            TERRAIN_SHAPE *surface = *next_surface++;
            auto record_hit = [&](const NUVEC *normal, const NUVEC *corner, i32 facing) {
                f32 nx = normal->x;
                f32 ny = normal->y;
                f32 nz = normal->z;
                f32 y = corner->y + CurTerr->groups[group_index].origin.y +
                        ((x - corner->x) * nx + (z - corner->z) * nz) / -ny;
                if (__builtin_expect(surface->material[1] != 0, 0)) {
                    if (position->y >= y && y > efloor_y && facing == 1) {
                        efloor_nx = nx;
                        efloor_ny = ny;
                        efloor_nz = nz;
                        efloor_poly = surface;
                        efloor_y = y;
                        ecastnum = group_index;
                    } else if (y > position->y && eroof_y >= y && (y != eroof_y || eroof_ny > ny)) {
                        eroof_nx = nx;
                        eroof_ny = ny;
                        eroof_nz = nz;
                        eroof_poly = surface;
                        eroof_y = y;
                        eroof_group = group_index;
                    }
                } else {
                    if (position->y >= y && y > floor_y && facing == 1) {
                        floor_nx = nx;
                        floor_ny = ny;
                        floor_nz = nz;
                        floor_poly = surface;
                        floor_y = y;
                        castnum = group_index;
                    } else if (!(y <= position->y) && roof_y >= y && (y != roof_y || roof_ny > ny)) {
                        roof_nx = nx;
                        roof_ny = ny;
                        roof_nz = nz;
                        roof_poly = surface;
                        roof_y = y;
                        roof_group = group_index;
                    }
                }
            };
#define CAST_LINE(a, b)                                                                                                \
    InsideLineF(x, z, surface->vectors[a].x, surface->vectors[a].z, surface->vectors[b].x, surface->vectors[b].z)
            if (__builtin_expect(surface->normals[1].y > 65535.0f, 1)) {
                // Triangle: a single plane.
                i32 facing = 0;
                if (__builtin_expect(surface->normals[0].y > 0.0f, 1)) {
                    if (__builtin_expect(CAST_LINE(1, 0) != 0, 0) && CAST_LINE(0, 2) && CAST_LINE(2, 1)) {
                        facing = 1;
                    }
                } else if (surface->normals[0].y < 0.0f) {
                    if (__builtin_expect(CAST_LINE(0, 1) != 0, 0) && CAST_LINE(2, 0) && CAST_LINE(1, 2)) {
                        facing = 2;
                    }
                }
                if (facing != 0) {
                    record_hit(&surface->normals[0], &surface->vectors[0], facing);
                }
            } else {
                // Quad: two planes sharing the 1-2 edge.
                i32 facing = 0;
                i32 plane = 0;
                if (surface->normals[0].y > 0.0f) {
                    if (CAST_LINE(2, 1)) {
                        if (CAST_LINE(1, 0) && CAST_LINE(0, 2)) {
                            facing = 1;
                        }
                    } else if (CAST_LINE(3, 1) && CAST_LINE(2, 3)) {
                        facing = 1;
                        plane = 1;
                    }
                } else if (__builtin_expect(surface->normals[0].y < 0.0f, 1)) {
                    if (CAST_LINE(1, 2)) {
                        if (CAST_LINE(0, 1) && CAST_LINE(2, 0)) {
                            facing = 2;
                        }
                    } else if (CAST_LINE(1, 3) && CAST_LINE(3, 2)) {
                        facing = 2;
                        plane = 1;
                    }
                }
                if (__builtin_expect(facing != 0, 1)) {
                    if (plane != 0 && surface->normals[1].y == 0.0f) {
                        plane = 0;
                    }
                    record_hit(&surface->normals[plane], &surface->vectors[plane * 3], facing);
                }
            }
#undef CAST_LINE
        }
        scan = reinterpret_cast<u8 *>(surfaces + shape_count);
        shape_count = *reinterpret_cast<i16 *>(scan);
    }

    if (__builtin_expect(!(eroof_y >= 2000000.0f) && eroof_ny < 0.0f && roof_range + position->y > eroof_y, 0)) {
        if (roof_y < 2000000.0f && roof_ny < 0.0f && roof_range + position->y > roof_y && eroof_y > roof_y) {
            EShadRoofPoly = NULL;
            EShadRoofY = 2000000.0f;
        } else {
            EShadRoofPoly = eroof_poly;
            EShadRoofY = eroof_y;
            EShadRoofNorm.x = eroof_nx;
            EShadRoofNorm.y = eroof_ny;
            EShadRoofNorm.z = eroof_nz;
            ecastroofnum = eroof_group;
            eshadroofhit = 1;
        }
    } else {
        EShadRoofPoly = NULL;
        EShadRoofY = 2000000.0f;
    }

    if (eroof_y < 2000000.0f && eroof_ny > 0.0f && roof_range + position->y > eroof_y) {
        if (!(roof_y < 2000000.0f && roof_ny < 0.0f && roof_range + position->y > roof_y && eroof_y > roof_y)) {
            EShadY = eroof_y;
            EShadPoly = eroof_poly;
            EShadNorm.y = eroof_ny;
            EShadNorm.x = eroof_nx;
            EShadNorm.z = eroof_nz;
            eshadhit = 1;
            ecastnum = eroof_group;
        } else {
            eshadhit = 3;
            EShadNorm.y = 1.0f;
            EShadY = 2000000.0f;
            EShadPoly = NULL;
        }
    } else if (efloor_y > -2000000.0f && !(floor_y > -2000000.0f && floor_y > efloor_y)) {
        eshadhit = 2;
        EShadPoly = efloor_poly;
        EShadY = efloor_y;
        EShadNorm.x = efloor_nx;
        EShadNorm.y = efloor_ny;
        EShadNorm.z = efloor_nz;
    } else {
        eshadhit = 3;
        EShadY = 2000000.0f;
        EShadPoly = NULL;
        EShadNorm.y = 1.0f;
    }

    if (roof_y < 2000000.0f && roof_ny < 0.0f && roof_range + position->y > roof_y) {
        shadroofhit = 1;
        ShadRoofNorm.x = roof_nx;
        ShadRoofNorm.y = roof_ny;
        castroofnum = roof_group;
        ShadRoofNorm.z = roof_nz;
        ShadRoofY = roof_y;
        ShadRoofPoly = roof_poly;
    } else {
        ShadRoofPoly = NULL;
        ShadRoofY = 2000000.0f;
    }

    if (roof_y < 2000000.0f && roof_ny > 0.0f && height_above + position->y > roof_y) {
        position->y = roof_y;
        ShadNorm.y = roof_ny;
        ShadNorm.x = roof_nx;
        ShadNorm.z = roof_nz;
        shadhit = 1;
        castnum = roof_group;
        ShadPoly = roof_poly;
    } else if (__builtin_expect(floor_y > -2000000.0f, 0)) {
        ShadNorm.x = floor_nx;
        ShadNorm.y = floor_ny;
        ShadNorm.z = floor_nz;
        shadhit = 2;
        ShadPoly = floor_poly;
        position->y = floor_y;
    } else {
        shadhit = 3;
        position->y = 2000000.0f;
        ShadNorm.y = 1.0f;
        ShadPoly = NULL;
    }
    return 0.0f;
}

extern "C" {
extern "C" f32 NewShadowEx(NUVEC *position, i32, f32 height_above, f32 height_below, i32 terrain_mask) {
    TerrPolyObj = -1;
    castnum = -1;
    ecastnum = -1;
    EShadRoofPoly = NULL;
    EShadRoofY = 2000000.0f;
    eshadhit = 0;
    EShadPoly = NULL;
    ShadRoofPoly = NULL;
    shadhit = 0;
    ShadPoly = 0;
    EShadY = 2000000.0f;
    EShadNorm.y = 1.0f;
    ShadRoofY = 2000000.0f;
    ShadNorm.y = 1.0f;

    f32 shadow_height = 2000000.0f;
    if (CurTerr != NULL) {
        TerI = static_cast<TerrainQuery_s *>(NuScratchAlloc32(sizeof(TerrainQuery_s)));
        ScaleTerrain = static_cast<TERRAIN_SHAPE *>(ScaleTerrainT1);
        NUVEC scan_position = *position;
        NewScanRot(&scan_position, terrain_mask);
        NewCast(&scan_position, height_above, height_below);
        NuScratchRelease();
        shadow_height = scan_position.y;
        NuTerrPlatsOff = 0;
    }
    return shadow_height;
}

    f32 NewShadow(NUVEC *position, f32 height_above, f32 height_below, i32 terrain_mask) {
        return NewShadowEx(position, 0, height_above, height_below, terrain_mask);
    }

}

i32 CheckCylinder(i32 first_vertex, i32 second_vertex, i32 *vertex_mask, i32 remaining_vertex_mask) {
    TerrainQuery_s *query = TerI;

    // Reject an edge when both endpoints lie outside the swept sphere's
    // expanded bounds. Once an edge is rejected this way, its endpoint bits
    // can be removed from the later vertex tests as well.
    if ((query->transformed_vertices[first_vertex].x > query->collision_radius &&
         query->transformed_vertices[second_vertex].x > query->collision_radius) ||
        (query->transformed_vertices[first_vertex].x < -query->collision_radius &&
         query->transformed_vertices[second_vertex].x < -query->collision_radius) ||
        (query->transformed_vertices[first_vertex].y > query->collision_radius &&
         query->transformed_vertices[second_vertex].y > query->collision_radius) ||
        (query->transformed_vertices[first_vertex].y < -query->collision_radius &&
         query->transformed_vertices[second_vertex].y < -query->collision_radius) ||
        (query->transformed_vertices[first_vertex].z < -query->collision_radius &&
         query->transformed_vertices[second_vertex].z < -query->collision_radius) ||
        (query->transformed_vertices[first_vertex].z > query->movement_length + query->collision_radius &&
         query->transformed_vertices[second_vertex].z > query->movement_length + query->collision_radius)) {
        *vertex_mask &= remaining_vertex_mask;
        return 0;
    }

    NUVEC edge_direction = {
        query->transformed_vertices[second_vertex].x - query->transformed_vertices[first_vertex].x,
        query->transformed_vertices[second_vertex].y - query->transformed_vertices[first_vertex].y,
        query->transformed_vertices[second_vertex].z - query->transformed_vertices[first_vertex].z,
    };
    const f32 horizontal_length_sq = edge_direction.x * edge_direction.x + edge_direction.y * edge_direction.y;

    // An almost vertical edge has no stable radial cylinder in the XY plane.
    // It can only overlap the sphere at the start of the sweep when it crosses
    // z = 0.
    if (horizontal_length_sq < 1.0e-12f) {
        if (!((query->transformed_vertices[first_vertex].z <= 0.0f &&
               query->transformed_vertices[second_vertex].z >= 0.0f) ||
              (query->transformed_vertices[first_vertex].z >= 0.0f &&
               query->transformed_vertices[second_vertex].z <= 0.0f))) {
            return 0;
        }

        const f32 distance_sq =
            query->transformed_vertices[second_vertex].x * query->transformed_vertices[second_vertex].x +
            query->transformed_vertices[second_vertex].y * query->transformed_vertices[second_vertex].y;
        if (distance_sq > query->collision_radius_sq) {
            return 0;
        }

        const f32 distance = NuFsqrt(distance_sq);
        const f32 overlap_time = distance - query->collision_radius;
        if (!(query->hit_time > overlap_time)) {
            return 0;
        }

        NUVEC local_normal;
        local_normal.x = -query->transformed_vertices[second_vertex].x;
        local_normal.y = -query->transformed_vertices[second_vertex].y;
        local_normal.z = 0.0f;
        RotateVec(&local_normal, &local_normal);
        const NUVEC &surface_normal = query->working_surface->normals[0];
        if (!(local_normal.x * surface_normal.x + local_normal.y * surface_normal.y +
                  local_normal.z * surface_normal.z >
              0.0f)) {
            return 0;
        }

        query = TerI;
        query->hit_time = overlap_time;
        f32 inverse_distance = 0.0f;
        if (__builtin_expect(distance != 0.0f, 1)) {
            inverse_distance = 1.0f / distance;
        }
        query->hit_type = TERRAIN_HIT_TYPE_CYLINDER | TERRAIN_HIT_TYPE_SECOND_NORMAL;
        query->movement_normal.x = -query->transformed_vertices[second_vertex].x * inverse_distance;
        query->movement_normal.y = -query->transformed_vertices[second_vertex].y * inverse_distance;
        query->movement_normal.z = 0.0f;
        return 1;
    }

    // Squared radial distance from the movement axis to the infinite line
    // containing the edge. This avoids a square root for the common miss.
    const f32 line_cross = query->transformed_vertices[first_vertex].x * edge_direction.y -
                           query->transformed_vertices[first_vertex].y * edge_direction.x;
    if (line_cross * line_cross > query->collision_radius_sq * horizontal_length_sq) {
        *vertex_mask &= remaining_vertex_mask;
        return 0;
    }

    f32 line_distance_sq = 0.0f;
    if (horizontal_length_sq != 0.0f && line_cross != 0.0f) {
        line_distance_sq = line_cross * (line_cross / horizontal_length_sq);
    }

    const f32 edge_length = NuFsqrt(horizontal_length_sq + edge_direction.z * edge_direction.z);
    f32 inverse_edge_length = 0.0f;
    if (__builtin_expect(edge_length != 0.0f, 1)) {
        inverse_edge_length = 1.0f / edge_length;
    }
    edge_direction.x *= inverse_edge_length;
    edge_direction.y *= inverse_edge_length;
    edge_direction.z *= inverse_edge_length;

    NUVEC line_cross_vector = {
        -query->transformed_vertices[first_vertex].x,
        -query->transformed_vertices[first_vertex].y,
        -query->transformed_vertices[first_vertex].z,
    };
    NuVecCross(&line_cross_vector, &line_cross_vector, &edge_direction);

    NUVEC horizontal_perpendicular = {-edge_direction.y, edge_direction.x, 0.0f};
    const f32 height_numerator =
        line_cross_vector.x * horizontal_perpendicular.x + line_cross_vector.y * horizontal_perpendicular.y;
    const f32 horizontal_direction_sq = horizontal_perpendicular.x * horizontal_perpendicular.x +
                                        horizontal_perpendicular.y * horizontal_perpendicular.y;
    f32 negative_closest_height = 0.0f;
    if (horizontal_direction_sq != 0.0f && height_numerator != 0.0f) {
        negative_closest_height = height_numerator / horizontal_direction_sq;
    }
    const f32 closest_height = -negative_closest_height;

    // This normal lies in the plane formed by the edge and the movement axis.
    // Its z component tells how far along the sweep the cylinder surface is
    // reached.
    f32 cylinder_side_z = horizontal_perpendicular.x * edge_direction.y - horizontal_perpendicular.y * edge_direction.x;
    const f32 cylinder_side_x = horizontal_perpendicular.y * edge_direction.z;
    const f32 cylinder_side_y = edge_direction.z * horizontal_perpendicular.x;
    // Preserve the cross product's subtraction before squaring its components.
    const f32 cylinder_side_length = NuFsqrt(cylinder_side_x * cylinder_side_x + cylinder_side_y * cylinder_side_y +
                                             cylinder_side_z * cylinder_side_z);
    if (cylinder_side_length != 0.0f && cylinder_side_z != 0.0f) {
        cylinder_side_z /= cylinder_side_length;
    } else {
        cylinder_side_z = 0.0f;
    }

    const f32 radial_extent = NuFsqrt(query->collision_radius_sq - line_distance_sq);
    f32 height_offset = 0.0f;
    if (radial_extent != 0.0f && cylinder_side_z != 0.0f) {
        height_offset = radial_extent / cylinder_side_z;
    }

    f32 hit_distance;
    if (height_offset >= 0.0f) {
        hit_distance = closest_height - height_offset;
    } else {
        hit_distance = height_offset - negative_closest_height;
    }
    if (!(hit_distance < 0.0f) && hit_distance <= query->movement_length) {
        const f32 edge_parameter = (-query->transformed_vertices[first_vertex].y * edge_direction.y -
                                    query->transformed_vertices[first_vertex].x * edge_direction.x) +
                                   (hit_distance - query->transformed_vertices[first_vertex].z) * edge_direction.z;
        if (edge_parameter > 0.0f && edge_parameter <= edge_length) {
            f32 hit_time = 0.0f;
            if (hit_distance != 0.0f && query->movement_length != 0.0f) {
                hit_time = hit_distance / query->movement_length;
            }
            if (__builtin_expect(query->hit_time <= hit_time, 0)) {
                *vertex_mask &= remaining_vertex_mask;
                return 0;
            }

            query->hit_type = TERRAIN_HIT_TYPE_CYLINDER;
            query->hit_time = hit_time;
            query->movement_normal.y =
                -(query->transformed_vertices[first_vertex].y + edge_direction.y * edge_parameter);
            query->movement_normal.z =
                hit_distance - (edge_parameter * edge_direction.z + query->transformed_vertices[first_vertex].z);
            query->movement_normal.x =
                -(query->transformed_vertices[first_vertex].x + edge_direction.x * edge_parameter);
            *vertex_mask &= remaining_vertex_mask;
            return 1;
        }
    }

    // No forward-time hit was found. Test whether the sphere already overlaps
    // the finite edge at the start of the sweep.
    if ((!(query->transformed_vertices[first_vertex].z >= -query->collision_radius) &&
         !(query->transformed_vertices[second_vertex].z >= -query->collision_radius)) ||
        (!(query->transformed_vertices[first_vertex].z <= query->collision_radius) &&
         query->transformed_vertices[second_vertex].z > query->collision_radius)) {
        return 0;
    }

    const f32 closest_parameter = -query->transformed_vertices[first_vertex].x * edge_direction.x -
                                  query->transformed_vertices[first_vertex].y * edge_direction.y -
                                  query->transformed_vertices[first_vertex].z * edge_direction.z;
    const f32 edge_projection =
        (query->transformed_vertices[second_vertex].x - query->transformed_vertices[first_vertex].x) *
            edge_direction.x +
        (query->transformed_vertices[second_vertex].y - query->transformed_vertices[first_vertex].y) *
            edge_direction.y +
        (query->transformed_vertices[second_vertex].z - query->transformed_vertices[first_vertex].z) * edge_direction.z;
    if (closest_parameter < 0.0f || closest_parameter > edge_projection) {
        return 0;
    }

    // The normalized direction is no longer needed after the closest
    // parameter has been bounded, so reuse it for the closest point itself.
    edge_direction = {
        query->transformed_vertices[first_vertex].x + edge_direction.x * closest_parameter,
        query->transformed_vertices[first_vertex].y + edge_direction.y * closest_parameter,
        query->transformed_vertices[first_vertex].z + edge_direction.z * closest_parameter,
    };
    const f32 distance_sq =
        edge_direction.x * edge_direction.x + edge_direction.y * edge_direction.y + edge_direction.z * edge_direction.z;
    if (__builtin_expect(!(distance_sq < query->collision_radius_sq), 1)) {
        return 0;
    }

    const f32 distance = NuFsqrt(distance_sq);
    const f32 overlap_time = distance - query->collision_radius;
    if (!(query->hit_time > overlap_time)) {
        return 0;
    }

    RotateVec(&edge_direction, &horizontal_perpendicular);
    const NUVEC &surface_normal = query->working_surface->normals[0];
    if (horizontal_perpendicular.x * surface_normal.x + horizontal_perpendicular.y * surface_normal.y +
            horizontal_perpendicular.z * surface_normal.z <
        0.0f) {
        query = TerI;
        query->hit_time = overlap_time;
        f32 inverse_distance = 0.0f;
        if (__builtin_expect(distance != 0.0f, 0)) {
            inverse_distance = 1.0f / distance;
        }
        query->hit_type = TERRAIN_HIT_TYPE_CYLINDER | TERRAIN_HIT_TYPE_SECOND_NORMAL;
        query->movement_normal.x = -edge_direction.x * inverse_distance;
        query->movement_normal.y = -edge_direction.y * inverse_distance;
        query->movement_normal.z = -edge_direction.z * inverse_distance;
        return 1;
    }
    return 0;
}

i32 CheckSphere(i32 vertex_index) {
    f32 radius = TerI->collision_radius;
    if (TerI->transformed_vertices[vertex_index].z < -radius ||
        TerI->transformed_vertices[vertex_index].z > TerI->movement_length + radius) {
        return 0;
    }

    f32 radial_distance_sq = TerI->transformed_vertices[vertex_index].x * TerI->transformed_vertices[vertex_index].x +
                             TerI->transformed_vertices[vertex_index].y * TerI->transformed_vertices[vertex_index].y;
    if (radial_distance_sq > TerI->collision_radius_sq) {
        return 0;
    }

    f32 radial_extent = NuFsqrt(TerI->collision_radius_sq - radial_distance_sq);
    f32 hit_distance = TerI->transformed_vertices[vertex_index].z - radial_extent;
    // The original rejection tests are ordered comparisons, so NaN distances fall through.
    if (!(hit_distance < 0.0f) && !(hit_distance > TerI->movement_length)) {
        f32 hit_time = hit_distance / TerI->movement_length;
        if (!(TerI->hit_time > hit_time)) {
            return 0;
        }

        TerI->hit_time = hit_time;
        TerI->hit_type = TERRAIN_HIT_TYPE_VERTEX;
        TerI->movement_normal.x = -TerI->transformed_vertices[vertex_index].x;
        TerI->movement_normal.y = -TerI->transformed_vertices[vertex_index].y;
        TerI->movement_normal.z = -radial_extent;
        return 1;
    }

    f32 distance_sq =
        radial_distance_sq + TerI->transformed_vertices[vertex_index].z * TerI->transformed_vertices[vertex_index].z;
    if (!(TerI->collision_radius_sq > distance_sq)) {
        return 0;
    }

    f32 distance = NuFsqrt(distance_sq);
    f32 overlap_time = distance - TerI->collision_radius;
    if (!(TerI->hit_time > overlap_time)) {
        return 0;
    }

    tertype *surface = TerI->working_surface;
    f32 primary_distance = (TerI->local_start.x - surface->vectors[vertex_index].x) * surface->normals[0].x +
                           (TerI->local_start.y - surface->vectors[vertex_index].y) * surface->normals[0].y +
                           (TerI->local_start.z - surface->vectors[vertex_index].z) * surface->normals[0].z;
    if (!(primary_distance > 0.0f)) {
        return 0;
    }

    TerI->hit_time = overlap_time;
    f32 inverse_distance = 0.0f;
    if (distance != 0.0f) {
        inverse_distance = 1.0f / distance;
    }
    TerI->hit_type = TERRAIN_HIT_TYPE_VERTEX | TERRAIN_HIT_TYPE_SECOND_NORMAL;
    TerI->movement_normal.x = -TerI->transformed_vertices[vertex_index].x * inverse_distance;
    TerI->movement_normal.y = -TerI->transformed_vertices[vertex_index].y * inverse_distance;
    TerI->movement_normal.z = -TerI->transformed_vertices[vertex_index].z * inverse_distance;
    return 1;
}

i32 CheckSphereTer(NUVEC *position, f32 radius) {
    const f32 terrain_radius = TerI->collision_radius;
    const f32 combined_radius = terrain_radius + radius;

    if (position->z < -terrain_radius - radius || position->z > TerI->movement_length + combined_radius) {
        return 0;
    }

    const f32 combined_radius_sq = combined_radius * combined_radius;
    const f32 radial_distance_sq = position->x * position->x + position->y * position->y;
    if (radial_distance_sq > combined_radius_sq) {
        return 0;
    }

    const f32 radial_extent = NuFsqrt(combined_radius_sq - radial_distance_sq);
    const f32 hit_distance = position->z - radial_extent;
    // The original rejection tests are ordered comparisons, so NaN distances fall through.
    if (!(hit_distance < 0.0f) && !(hit_distance > TerI->movement_length)) {
        const f32 hit_time = hit_distance / TerI->movement_length;
        if (!(TerI->hit_time > hit_time)) {
            return 0;
        }

        TerI->hit_time = hit_time;
        TerI->hit_type = TERRAIN_HIT_TYPE_SPHERE;
        TerI->movement_normal.x = -position->x;
        TerI->movement_normal.y = -position->y;
        TerI->movement_normal.z = -radial_extent;
        return 1;
    }

    const f32 distance_sq = radial_distance_sq + position->z * position->z;
    if (!(combined_radius_sq > distance_sq)) {
        return 0;
    }

    const f32 distance = NuFsqrt(distance_sq);
    f32 inverse_distance = 0.0f;
    if (distance != 0.0f) {
        inverse_distance = 1.0f / distance;
    }

    TerI->hit_time = 0.0f;
    TerI->hit_type = TERRAIN_HIT_TYPE_SPHERE | TERRAIN_HIT_TYPE_SECOND_NORMAL;
    TerI->movement_normal.x = -position->x * inverse_distance;
    TerI->movement_normal.y = -position->y * inverse_distance;
    TerI->movement_normal.z = -position->z * inverse_distance;
    return 1;
}

i32 HitPoly(f32 primary_start, f32 primary_end, f32 secondary_start, f32 secondary_end, tertype *surface) {
    TerrainQuery_s *query = TerI;
    f32 radius = query->collision_radius;
    const f32 no_secondary_normal = 65536.0f;

    i32 collision_found = 0;
    f32 candidate_time = 0.0f;
    NUVEC contact_point;

    const NUVEC &primary_origin = surface->vectors[0];
    NUVEC &primary_normal = surface->normals[0];
    const f32 primary_base_x = query->local_start.x - radius * primary_normal.x - primary_origin.x;
    const f32 primary_base_y = query->local_start.y - radius * primary_normal.y - primary_origin.y;
    const f32 primary_base_z = query->local_start.z - primary_normal.z * radius - primary_origin.z;

    i32 test_primary_face = 0;
    if (primary_start > 0.0f && primary_end < 0.0f) {
        candidate_time = primary_start / (primary_start - primary_end);
        contact_point.y = query->movement.y * candidate_time;
        contact_point.x = query->movement.x * candidate_time;
        contact_point.z = query->movement.z * candidate_time;
        test_primary_face = 1;
    } else if (__builtin_expect(primary_start <= 0.0f && primary_end <= 0.0f && primary_end >= -radius &&
                                    primary_start >= -radius,
                                0)) {
        candidate_time = primary_start;
        const f32 projection_distance = -primary_start;
        contact_point.y = primary_normal.y * projection_distance;
        contact_point.x = primary_normal.x * projection_distance;
        contact_point.z = primary_normal.z * projection_distance;
        test_primary_face = 1;
    }

    if (test_primary_face != 0) {
        const NUVEC edge_0_1 = {
            surface->vectors[1].x - primary_origin.x,
            surface->vectors[1].y - primary_origin.y,
            surface->vectors[1].z - primary_origin.z,
        };
        const NUVEC edge_0_2 = {
            surface->vectors[2].x - primary_origin.x,
            surface->vectors[2].y - primary_origin.y,
            surface->vectors[2].z - primary_origin.z,
        };
        if (InsidePolLines(contact_point.x + primary_base_x, contact_point.y + primary_base_y,
                           contact_point.z + primary_base_z,
                           edge_0_1.x, edge_0_1.y, edge_0_1.z, edge_0_2.x, edge_0_2.y, edge_0_2.z,
                           &primary_normal) != 0 &&
            candidate_time <= TerI->hit_time) {
            query = TerI;
            query->shape_adjusted = (surface->normal_flags & TERRAIN_SHAPE_NORMAL_FLAG_FIRST_STEEP) != 0;
            query->hit_time = candidate_time;
            query->hit_type =
                primary_start > 0.0f ? TERRAIN_HIT_TYPE_FACE : TERRAIN_HIT_TYPE_FACE | TERRAIN_HIT_TYPE_SECOND_NORMAL;
            query->movement_normal.x = primary_normal.x;
            query->movement_normal.y = primary_normal.y;
            query->movement_normal.z = primary_normal.z;
            collision_found = 1;
        }
    }

    query = TerI;
    radius = query->collision_radius;
    NUVEC &secondary_normal = surface->normals[1];
    if (secondary_normal.y < no_secondary_normal) {
        const NUVEC &secondary_origin = surface->vectors[3];
        const f32 secondary_base_x = query->local_start.x - radius * secondary_normal.x - secondary_origin.x;
        const f32 secondary_base_y = query->local_start.y - radius * secondary_normal.y - secondary_origin.y;
        const f32 secondary_base_z = query->local_start.z - secondary_normal.z * radius - secondary_origin.z;

        i32 test_secondary_face = 0;
        if (secondary_start > 0.0f && secondary_end < 0.0f) {
            candidate_time = secondary_start / (secondary_start - secondary_end);
            contact_point.x = query->movement.x * candidate_time;
            contact_point.y = query->movement.y * candidate_time;
            contact_point.z = query->movement.z * candidate_time;
            test_secondary_face = 1;
        } else if (__builtin_expect(secondary_start <= 0.0f && secondary_end <= 0.0f && secondary_start >= -radius &&
                                        secondary_end >= -radius,
                                    1)) {
            candidate_time = secondary_start;
            const f32 projection_distance = -secondary_start;
            contact_point.y = secondary_normal.y * projection_distance;
            contact_point.x = secondary_normal.x * projection_distance;
            contact_point.z = secondary_normal.z * projection_distance;
            test_secondary_face = 1;
        }

        if (test_secondary_face != 0) {
            const NUVEC edge_3_2 = {
                surface->vectors[2].x - secondary_origin.x,
                surface->vectors[2].y - secondary_origin.y,
                surface->vectors[2].z - secondary_origin.z,
            };
            const NUVEC edge_3_1 = {
                surface->vectors[1].x - secondary_origin.x,
                surface->vectors[1].y - secondary_origin.y,
                surface->vectors[1].z - secondary_origin.z,
            };
            if (InsidePolLines(
                    contact_point.x + secondary_base_x, contact_point.y + secondary_base_y,
                    contact_point.z + secondary_base_z,
                    edge_3_2.x, edge_3_2.y, edge_3_2.z, edge_3_1.x, edge_3_1.y, edge_3_1.z, &secondary_normal) != 0 &&
                candidate_time < TerI->hit_time) {
                query = TerI;
                query->hit_time = candidate_time;
                query->movement_normal.x = secondary_normal.x;
                query->movement_normal.y = secondary_normal.y;
                query->movement_normal.z = secondary_normal.z;
                query->shape_adjusted = (surface->normal_flags & TERRAIN_SHAPE_NORMAL_FLAG_SECOND_STEEP) != 0;
                query->hit_type = secondary_start > 0.0f ? TERRAIN_HIT_TYPE_FACE
                                                         : TERRAIN_HIT_TYPE_FACE | TERRAIN_HIT_TYPE_SECOND_NORMAL;
                collision_found = 1;
            }
        }
    }

    query = TerI;
    radius = query->collision_radius;
    if (radius != 0.0f) {
        query->working_surface = surface;
        i32 vertex_mask = 0xf;
        DeRotateTerrain(surface);

        if (primary_start >= -radius) {
            if (__builtin_expect(CheckCylinder(0, 1, &vertex_mask, 0xc) != 0, 0)) {
                query = TerI;
                query->shape_adjusted = (surface->normal_flags & TERRAIN_SHAPE_NORMAL_FLAG_FIRST_STEEP) != 0;
                query->hit_edge = TERRAIN_HIT_EDGE_0_1;
                collision_found = 1;
            }
            if (CheckCylinder(2, 0, &vertex_mask, 0xa) != 0) {
                query = TerI;
                query->shape_adjusted = (surface->normal_flags & TERRAIN_SHAPE_NORMAL_FLAG_FIRST_STEEP) != 0;
                query->hit_edge = TERRAIN_HIT_EDGE_2_0;
                collision_found = 1;
            }
        }

        if (CheckCylinder(1, 2, &vertex_mask, 0x9) != 0) {
            query = TerI;
            query->hit_edge = TERRAIN_HIT_EDGE_1_2;
            query->shape_adjusted = (surface->normal_flags & (TERRAIN_SHAPE_NORMAL_FLAG_FIRST_STEEP |
                                                              TERRAIN_SHAPE_NORMAL_FLAG_SECOND_STEEP)) != 0;
            collision_found = 1;
        }

        if (secondary_normal.y < no_secondary_normal && secondary_start >= -radius) {
            if (CheckCylinder(1, 3, &vertex_mask, 0x5) != 0) {
                query = TerI;
                query->hit_edge = TERRAIN_HIT_EDGE_1_3;
                query->shape_adjusted = (surface->normal_flags & TERRAIN_SHAPE_NORMAL_FLAG_SECOND_STEEP) != 0;
                collision_found = 1;
            }
            if (CheckCylinder(3, 2, &vertex_mask, 0x3) != 0) {
                query = TerI;
                query->hit_edge = TERRAIN_HIT_EDGE_3_2;
                query->shape_adjusted = (surface->normal_flags & TERRAIN_SHAPE_NORMAL_FLAG_SECOND_STEEP) != 0;
                collision_found = 1;
            }
            if ((vertex_mask & (1 << 3)) != 0 && CheckSphere(3) != 0) {
                TerI->shape_adjusted = (surface->normal_flags & TERRAIN_SHAPE_NORMAL_FLAG_SECOND_STEEP) != 0;
                collision_found = 1;
            }
        }

        if (primary_start >= -radius) {
            if ((vertex_mask & (1 << 0)) != 0 && CheckSphere(0) != 0) {
                TerI->shape_adjusted = (surface->normal_flags & TERRAIN_SHAPE_NORMAL_FLAG_FIRST_STEEP) != 0;
                collision_found = 1;
            }
            if ((vertex_mask & (1 << 1)) != 0 && CheckSphere(1) != 0) {
                TerI->shape_adjusted = (surface->normal_flags & (TERRAIN_SHAPE_NORMAL_FLAG_FIRST_STEEP |
                                                                 TERRAIN_SHAPE_NORMAL_FLAG_SECOND_STEEP)) != 0;
                collision_found = 1;
            }
        }

        if ((vertex_mask & (1 << 2)) != 0 && CheckSphere(2) != 0) {
            TerI->shape_adjusted = (surface->normal_flags & (TERRAIN_SHAPE_NORMAL_FLAG_FIRST_STEEP |
                                                             TERRAIN_SHAPE_NORMAL_FLAG_SECOND_STEEP)) != 0;
            collision_found = 1;
        }
    }

    query = TerI;
    if (collision_found != 0) {
        query->surface = surface;
    }
    query->unclamped_hit_time = query->hit_time;
    if (__builtin_expect(query->hit_time < 0.0f, 0)) {
        query->hit_time = 0.0f;
    }
    return collision_found;
}

i32 HitWallSpline() {
    f32 hit = 0.0f;
    NUVEC normal;
    normal.y = 0.0f;
    if (__builtin_expect(WallSplCount == 0, 0))
        return hit;
    for (i32 i = 0; i < WallSplCount; i += 2) {
        TerrainQuery_s *query = TerI;
        if (!(64.0f > fabsf(query->position.x - WallSplList[i].position.x) &&
              64.0f > fabsf(query->position.z - WallSplList[i].position.z)))
            continue;
        normal.x = WallSplList[i + 1].position.z - WallSplList[i].position.z;
        normal.z = WallSplList[i].position.x - WallSplList[i + 1].position.x;
        NuVecNorm(&normal, &normal);
        const f32 radius = query->collision_radius;
        const f32 px = query->position.x;
        const f32 mz = query->movement.z;
        const f32 mx = query->movement.x;
        const f32 pz = query->position.z;
        const f32 end_distance = ((mx + px) - WallSplList[i].position.x) * normal.x +
                                 ((mz + pz) - WallSplList[i].position.z) * normal.z - radius;
        const f32 start_distance =
            (px - WallSplList[i].position.x) * normal.x + (pz - WallSplList[i].position.z) * normal.z - radius;
        if (__builtin_expect((end_distance < 0.0f || start_distance < 0.0f) && start_distance > -radius, 0)) {
            f32 time, x, z;
            if (start_distance < 0.0f) {
                time = start_distance;
                x = (px - normal.x * start_distance) - normal.x * radius;
                z = (pz - normal.z * start_distance) - normal.z * radius;
            } else {
                time = start_distance / (start_distance - end_distance);
                x = (mx * time + px) - normal.x * radius;
                z = (mz * time + pz) - normal.z * radius;
            }
            const f32 dx = WallSplList[i + 1].position.x - WallSplList[i].position.x;
            const f32 dz = WallSplList[i + 1].position.z - WallSplList[i].position.z;
            if ((x - WallSplList[i].position.x) * dx + dz * (z - WallSplList[i].position.z) >= -0.00005f &&
                -dx * (x - WallSplList[i + 1].position.x) - (z - WallSplList[i + 1].position.z) * dz >= -0.00005f &&
                time < query->hit_time) {
                query->shape_adjusted = 4;
                query->terrain_group_index = -1;
                query->hit_type = start_distance > 0.0f ? 1 : 0x11;
                query->surface = NULL;
                TerrWallInfo = 1;
                query->movement_normal.x = normal.x;
                query->hit_time = time;
                query->movement_normal.y = normal.y;
                query->movement_normal.z = normal.z;
                TerrWallTab[0] = WallSplList[i].material[0];
                TerrWallTab[1] = WallSplList[i].material[1];
                hit = 1.0f;
            }
        }
        const f32 dx = WallSplList[i].position.x - px;
        const f32 dz = WallSplList[i].position.z - pz;
        const f32 reach = radius + 0.005f + query->horizontal_movement_length;
        const f32 distance_sq = dx * dx + dz * dz;
        if (!(64.0f > fabsf(dx) && 64.0f > fabsf(dz) && reach * reach > distance_sq))
            continue;
        NUVEC direction;
        direction.x = mx;
        direction.y = 0.0f;
        direction.z = mz;
        NuVecNorm(&direction, &direction);
        const f32 along = direction.x * dx + direction.z * dz;
        const f32 padded_radius = radius + 0.0005f;
        f32 time = 0.0f;
        bool penetrating = true;
        if (__builtin_expect(along >= 0.0f, 1)) {
            const f32 side_z = WallSplList[i].position.z - (direction.z * along + pz);
            const f32 side_x = WallSplList[i].position.x - (direction.x * along + px);
            const f32 side_x_sq = side_x * side_x;
            const f32 side_z_sq = side_z * side_z;
            if (__builtin_expect(side_x_sq + side_z_sq <= padded_radius * padded_radius, 0)) {
                const f32 movement_sq = mx * mx + mz * mz;
                const f32 distance = along - NuFsqrt((radius * radius - side_x_sq) - side_z_sq);
                if (distance >= -0.0005f && movement_sq >= distance * distance) {
                    const f32 length = NuFsqrt(movement_sq);
                    if (length != 0.0f && distance != 0.0f) {
                        time = distance / length;
                        if (time < 0.0f)
                            time = 0.0f;
                    }
                    if (!(query->hit_time > time))
                        continue;
                    normal.x = direction.x * distance + px - WallSplList[i].position.x;
                    normal.z = distance * direction.z + pz - WallSplList[i].position.z;
                    NuVecNorm(&normal, &normal);
                    penetrating = false;
                }
            }
        }
        if (penetrating) {
            if (!(padded_radius * padded_radius >= distance_sq))
                continue;
            normal.z = pz - WallSplList[i].position.z;
            normal.x = px - WallSplList[i].position.x;
            NuVecNorm(&normal, &normal);
            query->hit_type = 0x11;
            time = (NuFsqrt(distance_sq) - radius) - 0.0005f;
        } else {
            query->hit_type = 1;
        }
        query->movement_normal.x = normal.x;
        query->hit_time = time;
        query->movement_normal.y = normal.y;
        query->movement_normal.z = normal.z;
        query->surface = NULL;
        query->shape_adjusted = 4;
        query->terrain_group_index = -1;
        TerrWallInfo = 1;
        TerrWallTab[0] = WallSplList[i].material[0];
        TerrWallTab[1] = WallSplList[i].material[1];
        hit = 1.0f;
    }
    TerI->unclamped_hit_time = TerI->hit_time;
    if (!(TerI->hit_time >= 0.0f))
        TerI->hit_time = 0.0f;
    return hit;
}

i32 HitTerrain() {
    u8 *scan = reinterpret_cast<u8 *>(TerrOverRideScan);
    if (scan == NULL) {
        scan = TerI->scan_list_storage;
    }

    TerI->hit_time = 999.9f;
    const f32 radius = TerI->collision_radius;
    TerI->shape_adjusted = 0;
    TerI->hit_type = TERRAIN_HIT_TYPE_NONE;
    TerI->terrain_group_index = -1;

    HitWallSpline();

    TerI->horizontal_movement_length =
        NuFsqrt(TerI->movement.x * TerI->movement.x + TerI->movement.z * TerI->movement.z);

    i32 collision_found = 0;
    f32 primary_start_distance = 0.0f;
    f32 secondary_end_distance = 0.0f;
    f32 secondary_start_distance = 0.0f;
    const f32 negative_radius = -radius;

    i16 shape_count = *reinterpret_cast<i16 *>(scan);
    for (;;) {
        while (shape_count > 0) {
            // A scan group packs its count and terrain-group index into the first
            // pointer-sized slot, followed by the selected shape pointers.
            TERRAIN_GROUP *group = &CurTerr->groups[*reinterpret_cast<i16 *>(scan + sizeof(i16))];
            tertype **scan_entries = reinterpret_cast<tertype **>(scan);
            tertype **surfaces = scan_entries + 1;

            TerrainQuery_s *query = TerI;
            query->local_start.y = query->position.y - group->origin.y;
            query->local_start.x = query->position.x - group->origin.x;
            query->local_start.z = query->position.z - group->origin.z;
            query->local_end.y = query->position.y + query->movement.y - group->origin.y;
            query->local_end.x = query->position.x + query->movement.x - group->origin.x;
            query->local_end.z = query->position.z + query->movement.z - group->origin.z;

            const i32 last_shape_index = shape_count - 1;
            i32 shape_index = 0;
            for (;;) {
                tertype *surface = scan_entries[shape_index + 1];
                const NUVEC &primary_point = surface->vectors[0];
                const NUVEC &primary_normal = surface->normals[0];

                f32 primary_end_distance = (query->local_end.x - primary_point.x) * primary_normal.x +
                                           (query->local_end.y - primary_point.y) * primary_normal.y +
                                           (query->local_end.z - primary_point.z) * primary_normal.z - radius -
                                           query->compare_epsilon;

                i32 crosses_surface = 0;
                if (0.0f > primary_end_distance) {
                    primary_start_distance = (query->local_start.x - primary_point.x) * primary_normal.x +
                                             (query->local_start.y - primary_point.y) * primary_normal.y +
                                             (query->local_start.z - primary_point.z) * primary_normal.z - radius;
                    crosses_surface = primary_start_distance > negative_radius;
                }

                const NUVEC &secondary_point = surface->vectors[3];
                const NUVEC &secondary_normal = surface->normals[1];
                if (65536.0f > secondary_normal.y) {
                    secondary_end_distance = (query->local_end.x - secondary_point.x) * secondary_normal.x +
                                             (query->local_end.y - secondary_point.y) * secondary_normal.y +
                                             (query->local_end.z - secondary_point.z) * secondary_normal.z - radius -
                                             query->compare_epsilon;
                    if (!(0.0f <= secondary_end_distance)) {
                        secondary_start_distance = (query->local_start.x - secondary_point.x) * secondary_normal.x +
                                                   (query->local_start.y - secondary_point.y) * secondary_normal.y +
                                                   (query->local_start.z - secondary_point.z) * secondary_normal.z -
                                                   radius;
                        if (secondary_start_distance > negative_radius) {
                            crosses_surface = 1;
                        }
                    }
                }

                if (crosses_surface != 0 && HitPoly(primary_start_distance, primary_end_distance,
                                                    secondary_start_distance, secondary_end_distance, surface) != 0) {
                    query = TerI;
                    query->terrain_group_index = *reinterpret_cast<u16 *>(scan + sizeof(i16));
                    collision_found = 1;
                    tertype *hit_surface = query->surface;
                    if ((query->hit_type & TERRAIN_HIT_TYPE_SECOND_NORMAL) != 0 &&
                        (hit_surface->flags & TERRAIN_SHAPE_FLAG_MATERIAL_ALIAS) != 0) {
                        PlatCrush = hit_surface->material[0] + 1;
                    }
                }
                query = TerI;
                if (shape_index == last_shape_index) {
                    break;
                }
                ++shape_index;
            }

            const i16 next_shape_count = *reinterpret_cast<i16 *>(surfaces + shape_index + 1);
            scan = reinterpret_cast<u8 *>(surfaces + shape_count);
            shape_count = next_shape_count;
        }

        if (shape_count == 0) {
            break;
        }
        do {
            scan += (1 - shape_count) * sizeof(tertype *);
            shape_count = *reinterpret_cast<i16 *>(scan);
        } while (shape_count < 0);
    }

    NUVEC sphere_position;
    for (i32 sphere_index = 0; sphere_index < curSphereter; ++sphere_index) {
        sphere_position = SphereData[sphere_index].position;
        const f32 scaled_collision_radius = TerI->collision_radius * TerI->object_scale;
        sphere_position.y *= TerI->inverse_object_scale;
        sphere_position.y -= scaled_collision_radius;
        DeRotatePoint(&sphere_position);
        collision_found |= CheckSphereTer(&sphere_position, SphereData[sphere_index].radius);
    }

    TerrainQuery_s *query = TerI;
    if (query->hit_type != TERRAIN_HIT_TYPE_NONE && query->terrain_group_index != -1) {
        TERRAIN_GROUP *group = &CurTerr->groups[query->terrain_group_index];
        if (group->chunk_type == TERRAIN_CHUNK_GROUP_SECONDARY) {
            plathitid = group->scene_index;
        }
    }

    TerrOverRideScan = NULL;
    return collision_found;
}

i32 HitTerrPoly(tertype *surface, i32 group_index) {
    f32 radius = TerI->collision_radius;
    TerI->hit_type = 0;
    TerI->hit_time = 999.9f;
    TerI->horizontal_movement_length =
        NuFsqrt(TerI->movement.x * TerI->movement.x + TerI->movement.z * TerI->movement.z);
    NUVEC *origin = &CurTerr->groups[group_index].origin;
    TerI->local_start.x = TerI->position.x - origin->x;
    TerI->local_start.y = TerI->position.y - origin->y;
    TerI->local_start.z = TerI->position.z - origin->z;
    TerI->local_end.x = (TerI->position.x + TerI->movement.x) - origin->x;
    TerI->local_end.y = (TerI->position.y + TerI->movement.y) - origin->y;
    TerI->local_end.z = (TerI->position.z + TerI->movement.z) - origin->z;
    f32 primary_end = (((TerI->local_end.x - surface->vectors[0].x) * surface->normals[0].x +
                        (TerI->local_end.y - surface->vectors[0].y) * surface->normals[0].y) +
                       (TerI->local_end.z - surface->vectors[0].z) * surface->normals[0].z) -
                      radius - TerI->compare_epsilon;
    f32 primary_start = 0.0f;
    bool test = false;
    if (primary_end < 0.0f) {
        primary_start = ((TerI->local_start.x - surface->vectors[0].x) * surface->normals[0].x +
                         (TerI->local_start.y - surface->vectors[0].y) * surface->normals[0].y) +
                        (TerI->local_start.z - surface->vectors[0].z) * surface->normals[0].z - radius;
        test = primary_start > -radius;
    }
    f32 secondary_start = 0.0f;
    f32 secondary_end = 0.0f;
    if (surface->normals[1].y < 65536.0f) {
        secondary_end = (((TerI->local_end.x - surface->vectors[3].x) * surface->normals[1].x +
                          (TerI->local_end.y - surface->vectors[3].y) * surface->normals[1].y) +
                         (TerI->local_end.z - surface->vectors[3].z) * surface->normals[1].z) -
                        radius - TerI->compare_epsilon;
        if (secondary_end < 0.0f) {
            secondary_start = ((TerI->local_start.x - surface->vectors[3].x) * surface->normals[1].x +
                               (TerI->local_start.y - surface->vectors[3].y) * surface->normals[1].y) +
                              (TerI->local_start.z - surface->vectors[3].z) * surface->normals[1].z - radius;
            if (secondary_start > -radius)
                test = true;
        }
    }
    if (test && HitPoly(primary_start, primary_end, secondary_start, secondary_end, surface)) {
        TerI->terrain_group_index = group_index;
        return 1;
    }
    return 0;
}

void ScanWallSplineTerrain(i32, i32 terrain_mask, i32) {
    WallSplinesOnly = 0;
    ScaleTerrain = static_cast<TERRAIN_SHAPE *>(ScaleTerrainT1);
    platinrange = 0;
    TerrainQuery_s *const entry_query = TerI;
    entry_query->scan_group_index = -1;
    TerrainScanBounds bounds;
    f32 scan_radius;
    TERRAIN_GET_SCAN_BOUNDS(bounds, scan_radius, true);
    i16 *terminator = reinterpret_cast<i16 *>(entry_query->scan_list_storage);
    terminator[0] = 0;
    terminator[1] = 0;
    TerrainScanBounds wall_bounds = bounds;
    const i32 wall_mask = terrain_mask;
    wall_bounds.min_x -= 0.02f;
    wall_bounds.min_z -= 0.02f;
    wall_bounds.max_x += 0.02f;
    wall_bounds.max_z += 0.02f;
    WallSplCount = 0;
    for (TERRAIN_SPATIAL_NODE *node = CurTerr->spatial_nodes; node != NULL;
         node = *reinterpret_cast<TERRAIN_SPATIAL_NODE **>(reinterpret_cast<u8 *>(node) - sizeof(void *))) {
        // field_0x02 holds the material in its low byte and the mask in its high byte.
        const u8 *material_bytes = reinterpret_cast<const u8 *>(&node->field_0x02);
        const u8 mask = material_bytes[1];
        if (mask != 0 && (mask & wall_mask) == 0)
            continue;
        const u8 material = material_bytes[0];
        auto node_points = node->points;
        for (i32 first = 0; first < node->point_count; first += 16) {
            NUVEC *points = node_points + first;
            i32 end = node->point_count;
            if (points[0].y != 2147483648.0f) {
                if (points[1].y >= wall_bounds.min_x && wall_bounds.max_x >= points[0].y &&
                    points[3].y >= wall_bounds.min_z && wall_bounds.max_z >= points[2].y)
                    end = MIN(end, first + 16);
                else
                    end = 0;
            }
            NUVEC *point = points;
            for (i32 i = first; i < end; ++i, ++point) {
                NUVEC &a = *point;
                NUVEC &b = point[1];
                if (!((a.x >= wall_bounds.min_x && wall_bounds.max_x >= b.x) ||
                      (!(b.x < wall_bounds.min_x) && wall_bounds.max_x >= a.x)))
                    continue;
                if (!((a.z >= wall_bounds.min_z && wall_bounds.max_z >= b.z) ||
                      (b.z >= wall_bounds.min_z && wall_bounds.max_z >= a.z)))
                    continue;
                const i32 wall_index = WallSplCount;
                if (wall_index < 64) {
                    WallSplList[wall_index].position = a;
                    WallSplList[wall_index].material[2] = 0;
                    WallSplList[wall_index].material[3] = 0;
                    WallSplList[wall_index].material[0] = material;
                    WallSplList[wall_index].material[1] = mask;
                    WallSplList[wall_index + 1].position = b;
                    WallSplList[wall_index + 1].material[0] = material;
                    WallSplList[wall_index + 1].material[2] = 0;
                    WallSplList[wall_index + 1].material[3] = 0;
                    WallSplList[wall_index + 1].material[1] = mask;
                    WallSplCount = wall_index + 2;
                }
            }
        }
    }
    TerrOverRideScan = NULL;
}

void ScanTerrain(i32 scan_type, i32 terrain_mask, i32 scan_flags) {
    if (WallSplinesOnly != 0) {
        ScanWallSplineTerrain(scan_type, terrain_mask, scan_flags);
        return;
    }

    ScaleTerrain = static_cast<TERRAIN_SHAPE *>(ScaleTerrainT1);
    platinrange = 0;
    TerI->scan_group_index = -1;

    TerrainScanWriter writer;
    writer.group_header = TerI->scan_list_storage;
    writer.cursor = reinterpret_cast<TERRAIN_SHAPE **>(writer.group_header + sizeof(TERRAIN_SHAPE *));
    writer.limit = TerI->scan_list_storage + sizeof(TerI->scan_list_storage) - 12;
    writer.group_shape_count = 0;
    writer.scaled_shape_count = 0;

    TERRAIN_GROUP *terrain_groups = CurTerr->groups;
    TerrainScanBounds bounds;
    f32 scan_radius;

    TerrainQuery_s *scan_query = TerI;
    if (scan_query->scan_result != 1) {
        const f32 move_length =
            NuFsqrt(scan_query->movement.x * scan_query->movement.x + scan_query->movement.y * scan_query->movement.y +
                    scan_query->movement.z * scan_query->movement.z);
        scan_query = TerI;
        f32 reach = move_length;
        reach += 0.1f + scan_query->collision_radius;
        f32 vertical = reach;
        vertical *= scan_query->object_scale;
        bounds.min_y = scan_query->position.y - 0.05f - vertical;
        bounds.min_x = scan_query->position.x - 0.05f - reach;
        bounds.max_x = scan_query->position.x + 0.05f + reach;
        bounds.max_y = scan_query->position.y + 0.05f + vertical;
        bounds.min_z = scan_query->position.z - 0.05f - reach;
        bounds.max_z = scan_query->position.z + 0.05f + reach;
        scan_radius = reach;
    } else {
        const f32 radius = scan_query->collision_radius;
        if (!(scan_query->movement.x > 0.0f)) {
            bounds.min_x = scan_query->position.x + scan_query->movement.x - 0.02f - radius;
            bounds.max_x = scan_query->position.x + 0.02f + radius;
        } else {
            bounds.min_x = scan_query->position.x - 0.02f - radius;
            bounds.max_x = scan_query->position.x + scan_query->movement.x + 0.02f + radius;
        }
        if (__builtin_expect(!(scan_query->movement.y > 0.0f), 0)) {
            bounds.min_y = scan_query->position.y + scan_query->movement.y - 0.02f - radius;
            bounds.max_y = scan_query->position.y + 0.02f + radius;
        } else {
            bounds.min_y = scan_query->position.y - 0.02f - radius;
            bounds.max_y = scan_query->position.y + scan_query->movement.y + 0.02f + radius;
        }
        if (!(scan_query->movement.z > 0.0f)) {
            bounds.min_z = scan_query->position.z + scan_query->movement.z - 0.02f - radius;
            bounds.max_z = scan_query->position.z + 0.02f + radius;
        } else {
            bounds.min_z = scan_query->position.z - 0.02f - radius;
            bounds.max_z = scan_query->position.z + scan_query->movement.z + 0.02f + radius;
        }
        const f32 dy = bounds.min_y - bounds.max_y;
        const f32 dx = bounds.min_x - bounds.max_x;
        const f32 dz = bounds.min_z - bounds.max_z;
        scan_radius = NuFsqrt(dx * dx + dy * dy + dz * dz);
    }
    scan_query = TerI;
    if (__builtin_expect(scan_query->object_scale > 1.0f, 1))
        scan_radius += (scan_query->object_scale - 1.0f) * scan_query->collision_radius;

    for (i32 cell_index = 0; cell_index < CurTerr->used_cell_count; ++cell_index) {
        const TERRAIN_CELL &cell = CurTerr->cells[cell_index];
        if (!(bounds.max_x >= cell.min_x && bounds.max_z >= cell.min_z && cell.max_x >= bounds.min_x &&
              cell.max_z >= bounds.min_z)) {
            continue;
        }

        const i16 *group_indices = CurTerr->group_indices + cell.first_group;
        for (i32 cell_group = 0; cell_group < static_cast<i16>(cell.group_count); ++cell_group) {
            const i32 group_index = group_indices[cell_group];
            TERRAIN_GROUP &group = terrain_groups[group_index];
            if (!(bounds.max_x >= group.bounds_min.x && bounds.max_y >= group.bounds_min.y &&
                  bounds.max_z >= group.bounds_min.z && group.bounds_max.x >= bounds.min_x &&
                  group.bounds_max.y > bounds.min_y && group.bounds_max.z > bounds.min_z) ||
                group.chunk_type == -1) {
                continue;
            }

            f32 group_bounds_min_x = bounds.min_x;
            f32 group_bounds_min_y = bounds.min_y;
            f32 group_bounds_min_z = bounds.min_z;
            f32 group_bounds_max_x = bounds.max_x;
            f32 group_bounds_max_y = bounds.max_y;
            f32 group_bounds_max_z = bounds.max_z;
            group_bounds_min_x -= group.origin.x;
            group_bounds_max_x -= group.origin.x;
            group_bounds_max_y -= group.origin.y;
            group_bounds_min_y -= group.origin.y;
            group_bounds_min_z -= group.origin.z;
            group_bounds_max_z -= group.origin.z;

            if (static_cast<i16>(group.scene_index) < 0) {
                TerrainSkinAllocate(reinterpret_cast<terrsitu_s *>(&group));
            }

            TERRAIN_SHAPE_BATCH *batch = static_cast<TERRAIN_SHAPE_BATCH *>(group.data);
            while (batch->marker >= 0) {
                TERRAIN_SHAPE *shapes = reinterpret_cast<TERRAIN_SHAPE *>(batch + 1);
                const i32 shape_count = batch->shape_count;
                if (group_bounds_max_x >= batch->min_x && batch->max_x > group_bounds_min_x &&
                    group_bounds_max_z >= batch->min_z && batch->max_z > group_bounds_min_z) {
                    TERRAIN_SHAPE *shape_cursor = shapes;
                    for (i32 remaining = shape_count; remaining > 0; --remaining, ++shape_cursor) {
                        TERRAIN_SHAPE *candidate = shape_cursor;
                        if (!(group_bounds_max_x >= candidate->min_x && candidate->max_x > group_bounds_min_x &&
                              group_bounds_max_z >= candidate->min_z && candidate->max_z > group_bounds_min_z &&
                              group_bounds_max_y >= candidate->min_y && candidate->max_y > group_bounds_min_y) ||
                            reinterpret_cast<u8 *>(writer.cursor) >= writer.limit) {
                            continue;
                        }
                        if (candidate->material[1] != 0 && (candidate->material[1] & terrain_mask) == 0) {
                            continue;
                        }
                        if ((candidate->flags & scan_flags) == 0x40) {
                            continue;
                        }

                        TERRAIN_SCALE_SCAN_SHAPE(candidate, group, &writer);
                        *writer.cursor++ = candidate;
                        ++writer.group_shape_count;
                    }
                }
                batch = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(shapes + shape_count);
            }
            TerrainFinishScanGroup(&writer, group_index);
        }
    }

    for (i32 pick_index = 0; pick_index < curPickInst; ++pick_index) {
        const i32 group_index = CurTerr->max_groups + pick_index;
        TERRAIN_GROUP &group = terrain_groups[group_index];
        f32 local_bounds_min_x = bounds.min_x;
        f32 local_bounds_min_y = bounds.min_y;
        f32 local_bounds_min_z = bounds.min_z;
        f32 local_bounds_max_x = bounds.max_x;
        f32 local_bounds_max_y = bounds.max_y;
        f32 local_bounds_max_z = bounds.max_z;
        local_bounds_min_x -= group.origin.x;
        local_bounds_max_x -= group.origin.x;
        local_bounds_min_y -= group.origin.y;
        local_bounds_max_y -= group.origin.y;
        local_bounds_min_z -= group.origin.z;
        local_bounds_max_z -= group.origin.z;
        if (__builtin_expect(!(local_bounds_max_x >= group.bounds_min.x && local_bounds_max_y >= group.bounds_min.y &&
              !(local_bounds_max_z < group.bounds_min.z) && group.bounds_max.x >= local_bounds_min_x &&
              group.bounds_max.y > local_bounds_min_y && group.bounds_max.z > local_bounds_min_z) ||
            group.chunk_type == -1, 0)) {
            continue;
        }

        TERRAIN_SHAPE_BATCH *batch = static_cast<TERRAIN_SHAPE_BATCH *>(group.data);
        while (batch->marker >= 0) {
            TERRAIN_SHAPE *shapes = reinterpret_cast<TERRAIN_SHAPE *>(batch + 1);
            const i32 shape_count = batch->shape_count;
            if (__builtin_expect(local_bounds_max_x >= batch->min_x && batch->max_x > local_bounds_min_x &&
                local_bounds_max_z >= batch->min_z && batch->max_z > local_bounds_min_z, 0)) {
                TERRAIN_SHAPE *shape_cursor = shapes;
                for (i32 remaining = shape_count; remaining > 0; --remaining, ++shape_cursor) {
                    TERRAIN_SHAPE *candidate = shape_cursor;
                    if (__builtin_expect(
                            !(local_bounds_max_x >= candidate->min_x && candidate->max_x > local_bounds_min_x &&
                              local_bounds_max_z >= candidate->min_z && candidate->max_z > local_bounds_min_z &&
                              local_bounds_max_y >= candidate->min_y && candidate->max_y > local_bounds_min_y) ||
                                reinterpret_cast<u8 *>(writer.cursor) >= writer.limit,
                            1)) {
                        continue;
                    }
                    if (candidate->material[1] != 0 && (candidate->material[1] & terrain_mask) == 0) {
                        continue;
                    }
                    if (__builtin_expect((candidate->flags & scan_flags) == 0x40, 1)) {
                        continue;
                    }

                    TERRAIN_SCALE_SCAN_SHAPE(candidate, group, &writer);
                    *writer.cursor++ = candidate;
                    ++writer.group_shape_count;
                }
            }
            batch = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(shapes + shape_count);
        }
        TerrainFinishScanGroup(&writer, group_index);
    }

    // The saved pointer marks the start of platform groups, after the fixed
    // terrain and pickup groups; platform impact consumers start here.
    bounds.min_x -= 0.05f;
    bounds.min_y -= 0.05f;
    bounds.min_z -= 0.05f;
    bounds.max_x += 0.05f;
    bounds.max_y += 0.05f;
    bounds.max_z += 0.05f;
    TerI->scan_list = writer.group_header;
    if (__builtin_expect(scan_type != 0, 1)) {

        const i16 *groups = CurTerr->active_platform_groups;
        i32 count = CurTerr->active_platform_count;
        if (!(!(bounds.min_x <= CurTerr->platform_scan_min.x) && CurTerr->platform_scan_max.x > bounds.max_x &&
              bounds.min_z > CurTerr->platform_scan_min.z && CurTerr->platform_scan_max.z > bounds.max_z)) {
            const TERRAIN_CELL &cell = CurTerr->cells[TERRAIN_PLATFORM_CELL];
            count = static_cast<i16>(cell.group_count);
            groups = CurTerr->group_indices + cell.first_group;
        }
        for (i32 i = 0; i < count; ++i) {
            const TERRAIN_GROUP &group = terrain_groups[groups[i]];
            if (__builtin_expect(
                    group.origin.x - group.radius > bounds.max_x || group.origin.x + group.radius < bounds.min_x ||
                        group.origin.z - group.radius > bounds.max_z || group.origin.z + group.radius < bounds.min_z,
                    1))
                continue;
            {
                const i32 platform_group_index = groups[i];
                const TERRAIN_PLATFORM &platform = CurTerr->platforms[static_cast<i16>(group.scene_index)];
                TerrainScanWriter *scan_writer = &writer;
                if (platform.scene_transform != NULL) {
                    const u8 visible_mask = (platform.flags & TERRAIN_PLATFORM_FLAG_DISPLAY_LIST_BACKED) != 0 ? 2 : 1;
                    if ((*static_cast<u8 *>(platform.scene_transform) & visible_mask) == 0)
                        continue;
                }
                f32 local_min_x = bounds.min_x;
                f32 local_min_y = bounds.min_y;
                f32 local_min_z = bounds.min_z;
                f32 local_max_x = bounds.max_x;
                f32 local_max_y = bounds.max_y;
                f32 local_max_z = bounds.max_z;
                NUMTX *matrix = static_cast<NUMTX *>(platform.scene_object);
                if (matrix == NULL) {
                    local_min_x = bounds.min_x - group.origin.x;
                    local_min_y = bounds.min_y - group.origin.y;
                    local_max_y = bounds.max_y - group.origin.y;
                    local_max_x = bounds.max_x - group.origin.x;
                    local_min_z = bounds.min_z - group.origin.z;
                    local_max_z = bounds.max_z - group.origin.z;
                } else {
                    if (!(matrix->m30 > platform.previous_matrix.m30)) {
                        local_min_x = (matrix->m30 - platform.previous_matrix.m30) + bounds.min_x - group.origin.x;
                        local_max_x = bounds.max_x - group.origin.x;
                    } else {
                        local_max_x = (matrix->m30 - platform.previous_matrix.m30) + bounds.max_x - group.origin.x;
                        local_min_x = bounds.min_x - group.origin.x;
                    }
                    if (__builtin_expect(matrix->m31 > platform.previous_matrix.m31, 0)) {
                        local_max_y = (matrix->m31 - platform.previous_matrix.m31) + bounds.max_y - group.origin.y;
                        local_min_y = bounds.min_y - group.origin.y;
                    } else {
                        local_min_y = (matrix->m31 - platform.previous_matrix.m31) + bounds.min_y - group.origin.y;
                        local_max_y = bounds.max_y - group.origin.y;
                    }
                    if (__builtin_expect(matrix->m32 > platform.previous_matrix.m32, 1)) {
                        local_max_z = (matrix->m32 - platform.previous_matrix.m32) + bounds.max_z - group.origin.z;
                        local_min_z = bounds.min_z - group.origin.z;
                    } else {
                        local_min_z = (matrix->m32 - platform.previous_matrix.m32) + bounds.min_z - group.origin.z;
                        local_max_z = bounds.max_z - group.origin.z;
                    }
                }
                const bool rotating = (platform.flags & TERRAIN_PLATFORM_FLAG_ROTATING) != 0;
                if (__builtin_expect(!!(rotating), 1)) {
                    const f32 x = (bounds.max_x + bounds.min_x) * 0.5f - group.origin.x;
                    const f32 y = (bounds.max_y + bounds.min_y) * 0.5f - group.origin.y;
                    const f32 z = (bounds.max_z + bounds.min_z) * 0.5f - group.origin.z;
                    const f32 distance_sq = x * x + y * y + z * z;
                    if (group.chunk_type == -1)
                        continue;
                    const f32 reach = group.radius + scan_radius;
                    if (!(reach * reach > distance_sq) || matrix == NULL)
                        continue;
                } else {
                    if (__builtin_expect(!(local_max_x >= group.bounds_min.x && local_max_y >= group.bounds_min.y &&
                          local_max_z >= group.bounds_min.z && group.bounds_max.x >= local_min_x &&
                          group.bounds_max.y > local_min_y && group.bounds_max.z > local_min_z), 0))
                        continue;
                    if (group.chunk_type == -1)
                        continue;
                }
                if (rotating) {
                    TERRAIN_SHAPE_BATCH *batch = static_cast<TERRAIN_SHAPE_BATCH *>(group.data);
                    while (batch->marker >= 0) {
                        TERRAIN_SHAPE *shapes = reinterpret_cast<TERRAIN_SHAPE *>(batch + 1);
                        {
                            for (i32 i = 0; i < batch->shape_count; ++i) {
                                TERRAIN_SHAPE *shape = &shapes[i];
                                if (reinterpret_cast<u8 *>(scan_writer->cursor) >= scan_writer->limit ||
                                    (shape->material[1] != 0 && (shape->material[1] & terrain_mask) == 0) ||
                                    (shape->flags & scan_flags) == 0x40)
                                    continue;

                                bool quad;
                                TERRAIN_SHAPE *transformed;
                                {
                                    NUVEC4 vertices[4];
                                    for (i32 v = 0; v < 3; ++v) {
                                        vertices[v].x = shape->vectors[v].x;
                                        vertices[v].y = shape->vectors[v].y;
                                        vertices[v].z = shape->vectors[v].z;
                                        vertices[v].w = 0.0f;
                                    }
                                    NuVec4MtxTransformVU0x3(vertices, vertices, matrix);
                                    quad = shape->normals[1].y < 65535.0f;
                                    if (quad) {
                                        vertices[3].x = shape->vectors[3].x;
                                        vertices[3].y = shape->vectors[3].y;
                                        vertices[3].w = 0.0f;
                                        vertices[3].z = shape->vectors[3].z;
                                        NuVec4MtxTransformVU0(&vertices[3], &vertices[3], matrix);
                                    } else
                                        vertices[3] = vertices[2];
                                    if (__builtin_expect(!(vertices[0].x > local_min_x || vertices[1].x > local_min_x ||
                                          vertices[2].x > local_min_x || vertices[3].x > local_min_x), 0))
                                        continue;
                                    if (!(vertices[0].x < local_max_x || !(vertices[1].x >= local_max_x) ||
                                          vertices[2].x < local_max_x || vertices[3].x < local_max_x))
                                        continue;
                                    if (!(vertices[0].z > local_min_z || vertices[1].z > local_min_z ||
                                          vertices[2].z > local_min_z || vertices[3].z > local_min_z))
                                        continue;
                                    if (!(vertices[0].z < local_max_z || vertices[1].z < local_max_z ||
                                          vertices[2].z < local_max_z || vertices[3].z < local_max_z))
                                        continue;
                                    platinrange = 1;
                                    transformed = &ScaleTerrain[scan_writer->scaled_shape_count++];
                                    transformed->material[0] = shape->material[0];
                                    transformed->material[1] = shape->material[1];
                                    transformed->flags = shape->flags;
                                    transformed->normal_flags = shape->normal_flags;
                                    transformed->vectors[0].x = vertices[0].x;
                                    transformed->vectors[0].z = vertices[0].z;
                                    transformed->vectors[0].y =
                                        (vertices[0].y + group.origin.y) * TerI->inverse_object_scale - group.origin.y;
                                    transformed->vectors[1].x = vertices[1].x;
                                    transformed->vectors[1].z = vertices[1].z;
                                    transformed->vectors[1].y =
                                        (vertices[1].y + group.origin.y) * TerI->inverse_object_scale - group.origin.y;
                                    transformed->vectors[2].x = vertices[2].x;
                                    transformed->vectors[2].z = vertices[2].z;
                                    transformed->vectors[2].y =
                                        (vertices[2].y + group.origin.y) * TerI->inverse_object_scale - group.origin.y;
                                    quad = shape->normals[1].y < 65535.0f;
                                    if (quad) {
                                        transformed->vectors[3].x = vertices[3].x;
                                        transformed->vectors[3].z = vertices[3].z;
                                        transformed->vectors[3].y =
                                            (vertices[3].y + group.origin.y) * TerI->inverse_object_scale -
                                            group.origin.y;
                                    }

                                    if (!quad)
                                        transformed->normals[1].y = 65536.0f;
                                }
                                if (quad) {
                                    NUVEC a, b;
                                    a.x = transformed->vectors[1].x - transformed->vectors[3].x;
                                    b.x = transformed->vectors[2].x - transformed->vectors[3].x;
                                    a.y = transformed->vectors[1].y - transformed->vectors[3].y;
                                    b.y = transformed->vectors[2].y - transformed->vectors[3].y;
                                    a.z = transformed->vectors[1].z - transformed->vectors[3].z;
                                    b.z = transformed->vectors[2].z - transformed->vectors[3].z;
                                    transformed->normals[1] = TerCrossProduct(&a, &b);
                                    NUVEC &normal = transformed->normals[1];
                                    const f32 length =
                                        NuFsqrt(normal.x * normal.x + normal.y * normal.y + normal.z * normal.z);
                                    const f32 inverse = length == 0.0f ? 0.0f : 1.0f / length;
                                    normal.x *= inverse;
                                    normal.y *= inverse;
                                    normal.z *= inverse;
                                }
                                {
                                    NUVEC a, b;
                                    a.x = transformed->vectors[2].x - transformed->vectors[0].x;
                                    b.x = transformed->vectors[1].x - transformed->vectors[0].x;
                                    a.y = transformed->vectors[2].y - transformed->vectors[0].y;
                                    b.y = transformed->vectors[1].y - transformed->vectors[0].y;
                                    a.z = transformed->vectors[2].z - transformed->vectors[0].z;
                                    b.z = transformed->vectors[1].z - transformed->vectors[0].z;
                                    transformed->normals[0] = TerCrossProduct(&a, &b);
                                    NUVEC &normal = transformed->normals[0];
                                    const f32 length =
                                        NuFsqrt(normal.x * normal.x + normal.y * normal.y + normal.z * normal.z);
                                    const f32 inverse = length == 0.0f ? 0.0f : 1.0f / length;
                                    normal.x *= inverse;
                                    normal.y *= inverse;
                                    normal.z *= inverse;
                                }
                                shape = transformed;

                                *scan_writer->cursor++ = shape;
                                ++scan_writer->group_shape_count;
                            }
                        }
                        batch = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(shapes + batch->shape_count);
                    }
                } else {
                    TERRAIN_SHAPE_BATCH *batch = static_cast<TERRAIN_SHAPE_BATCH *>(group.data);
                    while (batch->marker >= 0) {
                        TERRAIN_SHAPE *shapes = reinterpret_cast<TERRAIN_SHAPE *>(batch + 1);
                        if ((local_max_x >= batch->min_x && batch->max_x > local_min_x && local_max_z >= batch->min_z &&
                             batch->max_z > local_min_z)) {
                            for (i32 i = 0; i < batch->shape_count; ++i) {
                                TERRAIN_SHAPE *shape = &shapes[i];
                                if (!(local_max_x >= shape->min_x && shape->max_x > local_min_x &&
                                      local_max_z >= shape->min_z && shape->max_z > local_min_z &&
                                      local_max_y >= shape->min_y && shape->max_y > local_min_y))
                                    continue;
                                if (reinterpret_cast<u8 *>(scan_writer->cursor) >= scan_writer->limit ||
                                    (shape->material[1] != 0 && (shape->material[1] & terrain_mask) == 0) ||
                                    (shape->flags & scan_flags) == 0x40)
                                    continue;

                                platinrange = 1;
                                TERRAIN_SCALE_SCAN_SHAPE(shape, group, scan_writer);

                                *scan_writer->cursor++ = shape;
                                ++scan_writer->group_shape_count;
                            }
                        }
                        batch = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(shapes + batch->shape_count);
                    }
                }
                TerrainFinishScanGroup(scan_writer, platform_group_index);
            }
        }
    }

    i16 *terminator = reinterpret_cast<i16 *>(writer.group_header);
    terminator[0] = 0;
    terminator[1] = 0;
    // Original 0x37ff7b consumes this one-scan suppression flag.
    WallSplCount = 0;
    f32 wall_bounds_min_x = bounds.min_x;
    f32 wall_bounds_min_z = bounds.min_z;
    f32 wall_bounds_max_x = bounds.max_x;
    f32 wall_bounds_max_z = bounds.max_z;
    wall_bounds_min_x -= 0.02f;
    wall_bounds_min_z -= 0.02f;
    wall_bounds_max_x += 0.02f;
    wall_bounds_max_z += 0.02f;

    if (IgnoreWallSplines != 0) {
        IgnoreWallSplines = 0;
    } else {

        WallSplCount = 0;
        for (TERRAIN_SPATIAL_NODE *node = CurTerr->spatial_nodes; node != NULL;
             node = *reinterpret_cast<TERRAIN_SPATIAL_NODE **>(reinterpret_cast<u8 *>(node) - sizeof(void *))) {
            const u8 mask = node->field_0x02 >> 8;
            if (mask != 0 && (mask & terrain_mask) == 0)
                continue;
            for (i32 first = 0; first < node->point_count; first += 16) {
                NUVEC *points = node->points + first;
                i32 end = node->point_count;
                if (points[0].y != 2147483648.0f) {
                    if (!(points[1].y >= wall_bounds_min_x && wall_bounds_max_x >= points[0].y &&
                          points[3].y >= wall_bounds_min_z && wall_bounds_max_z >= points[2].y))
                        continue;
                    end = MIN(end, first + 16);
                }
                for (i32 i = first; i < end; ++i) {
                    NUVEC &b = node->points[i + 1];
                    NUVEC &a = node->points[i];
                    if (__builtin_expect(!((a.x >= wall_bounds_min_x && wall_bounds_max_x >= b.x) ||
                                           (b.x >= wall_bounds_min_x && wall_bounds_max_x >= a.x)),
                                         0))
                        continue;
                    if (!((a.z >= wall_bounds_min_z && wall_bounds_max_z >= b.z) ||
                          (b.z >= wall_bounds_min_z && wall_bounds_max_z >= a.z)))
                        continue;
                    if (WallSplCount < 64) {
                        WallSplList[WallSplCount].position = a;
                        WallSplList[WallSplCount + 1].position = b;
                        for (i32 p = 0; p < 2; ++p) {
                            u8 *material = WallSplList[WallSplCount + p].material;
                            material[0] = static_cast<u8>(node->field_0x02);
                            material[1] = mask;
                            material[2] = 0;
                            material[3] = 0;
                        }
                        WallSplCount += 2;
                    }
                }
            }
        }
    }
    TerrOverRideScan = NULL;
}

extern "C" {
extern "C" void TerrainScanWallSpline(TERRAIN_SPATIAL_NODE *node) {
    const i32 point_count = node->point_count;
    if (point_count > 2) {
        i32 count = point_count <= 14 ? point_count + 1 : 16;
        f32 first_x = node->points[0].x;
        f32 first_z = node->points[0].z;
        // The original Android binary repeats this block without advancing
        // the spline or terminating when point_count is greater than two.
        for (;;) {
            f32 min_x = first_x;
            f32 min_z = first_z;
            f32 max_x = first_x;
            f32 max_z = first_z;
            for (i32 i = 1; i < count; ++i) {
                f32 x = node->points[i].x;
                f32 z = node->points[i].z;
                min_x = x < min_x ? x : min_x;
                min_z = z < min_z ? z : min_z;
                max_x = x > max_x ? x : max_x;
                max_z = z > max_z ? z : max_z;
            }
            node->points[0].y = min_x;
            node->points[1].y = max_x;
            node->points[2].y = min_z;
            node->points[3].y = max_z;
        }
    }
    node->points[0].y = 2147483648.0f;
}

extern "C" void TerrainAddWallSpline(TERRAIN_SPATIAL_NODE *node, TERRSET *terrain) {
    reinterpret_cast<TERRAIN_SPATIAL_NODE **>(node)[-1] = terrain->spatial_nodes;
    terrain->spatial_nodes = node;
}

extern "C" void TerrainRemoveWallSpline(TERRAIN_SPATIAL_NODE *node, TERRSET *terrain) {
    if (terrain == NULL)
        return;
    TERRAIN_SPATIAL_NODE *previous = terrain->spatial_nodes;
    if (previous == NULL)
        return;
    if (previous == node) {
        terrain->spatial_nodes = reinterpret_cast<TERRAIN_SPATIAL_NODE **>(previous)[-1];
        return;
    }
    TERRAIN_SPATIAL_NODE *next = reinterpret_cast<TERRAIN_SPATIAL_NODE **>(previous)[-1];
    while (next != NULL && next != node) {
        previous = next;
        next = reinterpret_cast<TERRAIN_SPATIAL_NODE **>(previous)[-1];
    }
    if (next == node)
        reinterpret_cast<TERRAIN_SPATIAL_NODE **>(previous)[-1] = reinterpret_cast<TERRAIN_SPATIAL_NODE **>(node)[-1];
}

extern "C" void FullDeflect(NUVEC *normal, NUVEC *movement, NUVEC *result) {
    const f32 normal_x = normal->x;
    const f32 normal_y = normal->y;
    const f32 normal_z = normal->z;
    const f32 movement_x = movement->x;
    const f32 movement_y = movement->y;
    const f32 movement_z = movement->z;
    const f32 deflection = -movement_y * normal_y - movement_x * normal_x - movement_z * normal_z + 0.0003f;
    result->x = movement_x + normal_x * deflection;
    result->y = movement_y + normal_y * deflection;
    result->z = movement_z + normal_z * deflection;
}

}

void FullDeflectSmallY(NUVEC *normal, NUVEC *movement, NUVEC *result) {
    // Move just far enough out of the surface to retain a small separation.
    const f32 normal_x = normal->x;
    const f32 normal_y = normal->y;
    const f32 normal_z = normal->z;
    const f32 movement_x = movement->x;
    const f32 movement_y = movement->y;
    const f32 movement_z = movement->z;
    const f32 deflection = -movement_y * normal_y - movement_x * normal_x - movement_z * normal_z + 0.0003f;
    result->x = movement_x + normal_x * deflection;
    result->y = movement_y + normal_y * deflection * TerrWallDeflectYScale;
    result->z = movement_z + normal_z * deflection;
}

i32 FullDeflectTest(nuvec_s *normal, nuvec_s *movement, nuvec_s *result) {
    f32 deflection = ((-movement->y * normal->y - movement->x * normal->x) - movement->z * normal->z) + 0.0003f;
    NUVEC output = {normal->x * deflection + movement->x, normal->y * deflection + movement->y,
                    normal->z * deflection + movement->z};
    *result = output;
    return deflection > 0.0f;
}

void FullDeflectSize(nuvec_s *normal, nuvec_s *movement, nuvec_s *result) {
    f32 deflection = (-movement->y * normal->y - movement->x * normal->x) - movement->z * normal->z;
    f32 original_length = NuFsqrt(movement->x * movement->x + movement->y * movement->y + movement->z * movement->z);
    NUVEC output = {normal->x * deflection + movement->x, normal->y * deflection + movement->y,
                    normal->z * deflection + movement->z};
    *result = output;
    f32 deflected_length = NuFsqrt(output.x * output.x + output.y * output.y + output.z * output.z);
    if (deflected_length != 0.0f) {
        f32 scale = (original_length * 0.75f) / deflected_length + 0.25f;
        result->x *= scale;
        result->y *= scale;
        result->z *= scale;
    }
}

extern "C" {
extern "C" void FullReflect(NUVEC *normal, NUVEC *movement, NUVEC *result) {
    const f32 normal_x = normal->x;
    const f32 normal_y = normal->y;
    const f32 normal_z = normal->z;
    const f32 movement_x = movement->x;
    const f32 movement_y = movement->y;
    const f32 movement_z = movement->z;
    const f32 reflection = -movement_y * normal_y - movement_x * normal_x - movement_z * normal_z;
    result->x = movement_x + 2.0f * (normal_x * reflection);
    result->y = movement_y + 2.0f * (normal_y * reflection);
    result->z = movement_z + 2.0f * (normal_z * reflection);
}

}

void FullReflectTest(nuvec_s *normal, nuvec_s *movement, nuvec_s *result) {
    f32 deflection = (-movement->y * normal->y - movement->x * normal->x) - movement->z * normal->z;
    f32 original_length = NuFsqrt(movement->x * movement->x + movement->y * movement->y + movement->z * movement->z);
    NUVEC output = {(normal->x * deflection) * 2.0f + movement->x, (normal->y * deflection) * 2.0f + movement->y,
                    (normal->z * deflection) * 2.0f + movement->z};
    *result = output;
    f32 deflected_length = NuFsqrt(output.x * output.x + output.y * output.y + output.z * output.z);
    if (deflected_length != 0.0f) {
        f32 scale = original_length / deflected_length;
        result->x *= scale;
        result->y *= scale;
        result->z *= scale;
    }
}

void NewTerrStoreAnyInfo() {
    TerrainQuery_s *query = TerI;
    TERRAIN_SHAPE *surface = query->surface;
    if (surface == NULL || query->terrain_group_index == -1) {
        return;
    }

    if (surface->material[0] != 0) {
        TerrPolyInfo.material[0] = surface->material[0];
    }
    if (surface->material[1] != 0) {
        TerrPolyInfo.material[1] = surface->material[1];
    }
    if (surface->flags != 0) {
        TerrPolyInfo.flags = surface->flags;
    }
    if (surface->normal_flags != 0) {
        TerrPolyInfo.normal_flags = surface->normal_flags;
    }
}

void TerrainMoveImpactData() {
    switch (TerI->hit_type) {
        case TERRAIN_HIT_TYPE_FACE:
        case TERRAIN_HIT_TYPE_CYLINDER:
        case TERRAIN_HIT_TYPE_VERTEX:
        case TERRAIN_HIT_TYPE_SPHERE:
        case TERRAIN_HIT_TYPE_FACE | TERRAIN_HIT_TYPE_SECOND_NORMAL:
        case TERRAIN_HIT_TYPE_CYLINDER | TERRAIN_HIT_TYPE_SECOND_NORMAL:
        case TERRAIN_HIT_TYPE_VERTEX | TERRAIN_HIT_TYPE_SECOND_NORMAL:
        case TERRAIN_HIT_TYPE_SPHERE | TERRAIN_HIT_TYPE_SECOND_NORMAL:
            break;
        default:
            return;
    }

    if (TerI->terrain_group_index == -1) {
        return;
    }

    NewTerrStoreAnyInfo();
    TerrPoly = &TerrPolyInfo;
    TerrPolyObj = TerI->terrain_group_index;
}

void TerrainImpactNorm() {
    TerrainMoveImpactData();

    switch (TerI->hit_type) {
        case TERRAIN_HIT_TYPE_SPHERE:
        case TERRAIN_HIT_TYPE_SPHERE | TERRAIN_HIT_TYPE_SECOND_NORMAL:
            terrhitflags |= 4;
            // Fall through to rotate curved hit normals.
        case TERRAIN_HIT_TYPE_CYLINDER:
        case TERRAIN_HIT_TYPE_CYLINDER | TERRAIN_HIT_TYPE_SECOND_NORMAL:
        case TERRAIN_HIT_TYPE_VERTEX:
        case TERRAIN_HIT_TYPE_VERTEX | TERRAIN_HIT_TYPE_SECOND_NORMAL:
            RotateVec(&TerI->movement_normal, &TerI->movement_normal);
            if ((TerI->hit_type & TERRAIN_HIT_TYPE_SECOND_NORMAL) == 0) {
                TerI->movement_normal.x *= TerI->inverse_collision_radius;
                TerI->movement_normal.y *= TerI->inverse_collision_radius;
                TerI->movement_normal.z *= TerI->inverse_collision_radius;
            }
            // Fall through to the common normal output.
        case TERRAIN_HIT_TYPE_FACE:
        case TERRAIN_HIT_TYPE_FACE | TERRAIN_HIT_TYPE_SECOND_NORMAL:
            break;
        default:
            return;
    }

    TerrainQuery_s *query = TerI;

    if (query->object_scale == 1.0f) {
        query->impact_normal.x = query->movement_normal.x;
        query->impact_normal.y = query->movement_normal.y;
        query->impact_normal.z = query->movement_normal.z;
        return;
    }

    const f32 normal_length =
        NuFsqrt(query->movement_normal.x * query->movement_normal.x +
                query->movement_normal.y * query->movement_normal.y * query->inverse_object_scale_sq +
                query->movement_normal.z * query->movement_normal.z);
    f32 inverse_normal_length = 0.0f;
    if (normal_length != 0.0f) {
        inverse_normal_length = 1.0f / normal_length;
    }

    query = TerI;
    query->impact_normal.x = query->movement_normal.x * inverse_normal_length;
    query->impact_normal.y = query->movement_normal.y * query->inverse_object_scale * inverse_normal_length;
    query->impact_normal.z = query->movement_normal.z * inverse_normal_length;
}

void RayImpact(NUVEC *movement) {
    TerrainMoveImpactData();
    switch (TerI->hit_type) {
        case 1:
        case 2:
        case 3:
        case 4: {
            TerI->hit_time -= TerI->separation_epsilon;
            if (TerI->hit_time < 0.0f)
                TerI->hit_time = 0.0f;
            f32 time = TerI->hit_time;
            movement->x = TerI->movement.x * time;
            movement->y = TerI->movement.y * time;
            movement->z = TerI->movement.z * time;
            break;
        }
        case 0x11:
        case 0x12:
        case 0x13:
        case 0x14:
            movement->x = 0.0f;
            movement->y = 0.0f;
            movement->z = 0.0f;
            break;
    }
}

void PlatformConnect(char *track_id, NUVEC *position_delta, NUVEC *movement_delta, i32 platform_index) {
    if (CurTrackInfo == NULL) {
        CurTrackInfo = AllocTerrId();
        if (CurTrackInfo != NULL) {
            CurTrackInfo->flags |= TERRAIN_TRACK_FLAG_CONNECTED;
            CurTrackInfo->platform_index = static_cast<i16>(platform_index);
            CurTrackInfo->id = track_id;
            CurTrackInfo->platform_contact_state = TERRAIN_TRACK_CONTACT_ACTIVE;
            position_delta->y = 0.0f;
            movement_delta->y = 0.0f;
        }
    } else {
        CurTrackInfo->flags |= TERRAIN_TRACK_FLAG_CONNECTED;
        CurTrackInfo->platform_index = static_cast<i16>(platform_index);
        CurTrackInfo->platform_contact_state = TERRAIN_TRACK_CONTACT_ACTIVE;
    }

    castnum = CurTerr->platforms[platform_index].terrain_group_index;
}

extern "C" {
extern "C" void TerrainWallAng(f32 slope) {
    wallover = slope;
}

}

void TerrainImpact(NUVEC *position, NUVEC *movement, u8 *hit_flags) {
    TerrainMoveImpactData();

    // Collision callbacks and track allocation can replace the active query.
    // Read TerI again after those calls, as the original response does.

    u8 hit_type = TerI->hit_type;
    f32 walkable_normal_y = 0.0f;

    TERRAIN_SHAPE *surface;
    TERRAIN_GROUP *group;
    bool platform_group;
    if (hit_type != TERRAIN_HIT_TYPE_NONE) {
        surface = TerI->surface;
        f32 surface_alignment = 0.707f;
        if (surface != NULL) {
            surface_alignment = TerI->movement_normal.x * surface->normals[0].x +
                                TerI->movement_normal.y * surface->normals[0].y +
                                TerI->movement_normal.z * surface->normals[0].z;
        }

        group = NULL;
        if (TerI->terrain_group_index != -1) {
            group = &CurTerr->groups[TerI->terrain_group_index];
        }
        platform_group = group != NULL && group->chunk_type == TERRAIN_CHUNK_GROUP_SECONDARY;

        if (platform_group) {
            const u8 base_hit_type = hit_type & TERRAIN_HIT_TYPE_CLASS_MASK;
            if (base_hit_type > TERRAIN_HIT_TYPE_FACE && surface_alignment < 0.95f) {
                walkable_normal_y = 0.98f;
            } else {
                walkable_normal_y = 0.707f;
            }
        } else {
            walkable_normal_y = TerI->shape_adjusted != 0 ? 1.1f : -1.1f;
        }

        // A non-negative group index on a hit always comes with a surface.
        if (TerI->terrain_group_index >= 0 &&
            (surface->normal_flags & TERRAIN_SURFACE_CLASS_MASK) == TERRAIN_SURFACE_CLASS_WALL_OVERRIDE) {
            // Original 0x382168 uses the scaled movement normal (+0xa8).
            TerI->position.x += TerI->movement_normal.x * 0.0015f;
            TerI->position.z += TerI->movement_normal.z * 0.0015f;
            walkable_normal_y = 1.1f;
        }
        if (wallover != 0.0f) {
            walkable_normal_y = wallover;
        }
    }

    switch (hit_type) {
        case TERRAIN_HIT_TYPE_CYLINDER:
        case TERRAIN_HIT_TYPE_VERTEX:
        case TERRAIN_HIT_TYPE_SPHERE:
            if (!(TerI->terrain_group_index >= 0 &&
                  (surface->normal_flags & TERRAIN_SURFACE_CLASS_MASK) == TERRAIN_SURFACE_CLASS_WALL_OVERRIDE))
                walkable_normal_y = 0.707f;
            // Fall through to the shared first-normal response.
        case TERRAIN_HIT_TYPE_FACE: {

            TerI->hit_time -= TerI->separation_epsilon;
            if (TerI->hit_time < 0.0f) {
                TerI->hit_time = 0.0f;
            }

            const f32 advance = TerI->hit_time;
            const NUVEC travelled = {
                TerI->movement.x * advance,
                TerI->movement.y * advance,
                TerI->movement.z * advance,
            };
            TerI->position.x += travelled.x;
            TerI->position.y += travelled.y;
            TerI->position.z += travelled.z;
            TerI->movement.x -= travelled.x;
            TerI->movement.y -= travelled.y;
            TerI->movement.z -= travelled.z;

            if (!(walkable_normal_y > TerI->impact_normal.y)) {
                FullDeflect(&TerI->movement_normal, &TerI->movement, &TerI->movement);
                FullDeflect(&TerI->impact_normal, movement, movement);

                terrhitflags |= TERRAIN_IMPACT_RESULT_GROUND;
                hit_flags[0] = 1;
                hit_flags[1] = 1;
                TerI->position.y += TerI->movement_normal.y * 0.0003f;

                if (TerI->terrain_group_index != -1) {
                    group = &CurTerr->groups[TerI->terrain_group_index];
                    if (group->chunk_type == TERRAIN_CHUNK_GROUP_SECONDARY) {
                        CurTerr->platforms[group->scene_index].flags |= TERRAIN_PLATFORM_FLAG_COLLIDED;
                    }
                }
            } else {
                hit_flags[0] = 0;
                terrhitflags |= TERRAIN_IMPACT_RESULT_WALL;
                if (TerI->terrain_group_index == -1 ||
                    CurTerr->groups[TerI->terrain_group_index].chunk_type != TERRAIN_CHUNK_GROUP_SECONDARY) {
                    terrhitflags |= TERRAIN_IMPACT_RESULT_STATIC_WALL;
                }

                TerI->position.x += TerI->movement_normal.x * 0.0006f;
                TerI->position.z += TerI->movement_normal.z * 0.0006f;
                TerI->movement.x += TerI->movement_normal.x * 0.0006f;
                TerI->movement.z += TerI->movement_normal.z * 0.0006f;
                movement->x += TerI->movement_normal.x * 0.0009f;
                movement->z += TerI->movement_normal.z * 0.0009f;

                FullDeflect(&TerI->movement_normal, &TerI->movement, &TerI->movement);
                FullDeflectSmallY(&TerI->impact_normal, movement, movement);

                if (CurTrackInfo == NULL) {
                    CurTrackInfo = AllocTerrId();
                    CurTrackInfo->id = TerI->hit_flags;
                    CurTrackInfo->flags = TERRAIN_TRACK_FLAG_NONE;
                    CurTrackInfo->platform_contact_state = TERRAIN_TRACK_CONTACT_NONE;
                    CurTrackInfo->platform_index = 0;
                }
                CurTrackInfo->wall_contact_state = TERRAIN_TRACK_CONTACT_ACTIVE;
                CurTrackInfo->impact_normal = TerI->impact_normal;
                TerrWallNorm = TerI->impact_normal;
            }

            TerI->flags &= static_cast<u8>(~TERRAIN_QUERY_FLAG_PREVIOUS_NORMAL);

            break;
        }
        case TERRAIN_HIT_TYPE_SECOND_NORMAL | TERRAIN_HIT_TYPE_CYLINDER:
        case TERRAIN_HIT_TYPE_SECOND_NORMAL | TERRAIN_HIT_TYPE_VERTEX:
        case TERRAIN_HIT_TYPE_SECOND_NORMAL | TERRAIN_HIT_TYPE_SPHERE:
            walkable_normal_y = 0.707f;
            // Fall through to the shared second-normal response.
        case TERRAIN_HIT_TYPE_SECOND_NORMAL | TERRAIN_HIT_TYPE_FACE: {

            NUVEC response_normal = TerI->movement_normal;
            if ((TerI->flags & TERRAIN_QUERY_FLAG_PREVIOUS_NORMAL) != 0) {
                const f32 previous_alignment = response_normal.x * TerI->previous_movement_normal.x +
                                               response_normal.y * TerI->previous_movement_normal.y +
                                               response_normal.z * TerI->previous_movement_normal.z;
                if (previous_alignment < 0.0f) {
                    NUVEC corrected_normal;
                    FullDeflect(&response_normal, &TerI->previous_movement_normal, &corrected_normal);
                    const f32 correction_alignment = corrected_normal.x * response_normal.x +
                                                     corrected_normal.y * response_normal.y +
                                                     corrected_normal.z * response_normal.z;
                    if (correction_alignment > 0.25f) {
                        response_normal.x = corrected_normal.x / correction_alignment;
                        response_normal.y = corrected_normal.y / correction_alignment;
                        response_normal.z = corrected_normal.z / correction_alignment;
                    }
                }
            }

            const f32 contact_push = 0.0035f - TerI->unclamped_hit_time * 1.05f;
            if (walkable_normal_y > TerI->impact_normal.y) {
                TerI->position.x += response_normal.x * contact_push;
                TerI->position.y += response_normal.y * contact_push;
                const f32 movement_push = 0.0035f - TerI->unclamped_hit_time * 0.35f;
                TerI->position.z += response_normal.z * contact_push;
                TerI->movement.x += response_normal.x * movement_push;
                TerI->movement.y += response_normal.y * movement_push;
                TerI->movement.z += response_normal.z * movement_push;
                hit_flags[0] = 1;

                FullDeflect(&response_normal, &TerI->movement, &TerI->movement);
                FullDeflectSmallY(&TerI->impact_normal, movement, movement);

                if (CurTrackInfo == NULL) {
                    CurTrackInfo = AllocTerrId();
                    CurTrackInfo->id = TerI->hit_flags;
                    CurTrackInfo->flags = TERRAIN_TRACK_FLAG_NONE;
                    CurTrackInfo->platform_contact_state = TERRAIN_TRACK_CONTACT_NONE;
                    CurTrackInfo->platform_index = 0;
                }
                CurTrackInfo->wall_contact_state = TERRAIN_TRACK_CONTACT_ACTIVE;
                CurTrackInfo->impact_normal = TerI->impact_normal;
            } else {
                TerI->position.x += response_normal.x * contact_push;
                TerI->position.y += response_normal.y * contact_push;
                TerI->position.z += response_normal.z * contact_push;
                TerI->position.y += response_normal.y * 0.01f;
                TerI->movement.y += response_normal.y * 0.01f;

                FullDeflect(&response_normal, &TerI->movement, &TerI->movement);
                FullDeflect(&TerI->impact_normal, movement, movement);
            }

            TerI->flags |= TERRAIN_QUERY_FLAG_PREVIOUS_NORMAL;
            TerI->previous_movement_normal = TerI->movement_normal;

            break;
        }
        case TERRAIN_HIT_TYPE_NONE:
            hit_flags[0] = 0;
            position->x = TerI->position.x + TerI->movement.x;
            position->y = (TerI->position.y + TerI->movement.y) * TerI->object_scale -
                          TerI->object_scale * TerI->collision_radius;
            TerI->flags &= static_cast<u8>(~TERRAIN_QUERY_FLAG_PREVIOUS_NORMAL);
            position->z = TerI->position.z + TerI->movement.z;
    }

    hit_type = TerI->hit_type;
    if (hit_type >= TERRAIN_HIT_TYPE_FACE && hit_type <= TERRAIN_HIT_TYPE_CLASS_MASK &&
        TerI->terrain_group_index != -1) {
        TERRAIN_GROUP *group = &CurTerr->groups[TerI->terrain_group_index];
        if (group->chunk_type == TERRAIN_CHUNK_GROUP_SECONDARY && TerI->impact_normal.y >= walkable_normal_y) {
            PlatformConnect(reinterpret_cast<char *>(TerI->hit_flags), &TerI->movement, movement, group->scene_index);
        }
    }

    if (TerImpactData == NULL || *TerImpactDataCount >= TerImpactDataMax) {
        return;
    }

    if (TerI->hit_type == TERRAIN_HIT_TYPE_NONE) {
        return;
    }

    TERRAIN_IMPACT_RECORD *records = static_cast<TERRAIN_IMPACT_RECORD *>(TerImpactData);
    TERRAIN_IMPACT_RECORD &record = records[*TerImpactDataCount];
    record.position.x = TerI->position.x - TerI->movement_normal.x * TerI->collision_radius;
    record.position.y = (TerI->position.y - TerI->movement_normal.y * TerI->collision_radius) * TerI->object_scale;
    record.position.z = TerI->position.z - TerI->movement_normal.z * TerI->collision_radius;
    record.normal = TerI->movement_normal;

    if (TerI->surface != NULL) {
        records[*TerImpactDataCount].material[0] = TerI->surface->material[0];
        records[*TerImpactDataCount].material[1] = TerI->surface->material[1];
        records[*TerImpactDataCount].flags = TerI->surface->flags;
        records[*TerImpactDataCount].normal_flags = TerI->surface->normal_flags;
    } else if (TerrWallInfo != 0) {
        records[*TerImpactDataCount].material[0] = TerrWallTab[0];
        records[*TerImpactDataCount].material[1] = TerrWallTab[1];
        records[*TerImpactDataCount].flags = 0;
        records[*TerImpactDataCount].normal_flags = 0;
    }
    ++*TerImpactDataCount;
}

i32 TerrainImpactPlatform(unsigned char *hit_flags) {
    TerrainMoveImpactData();

    TerrainQuery_s *query = TerI;
    switch (query->hit_type) {
        case TERRAIN_HIT_TYPE_NONE:
            hit_flags[0] = 0;
            query->position.x += query->movement.x;
            query->position.y += query->movement.y;
            query->position.z += query->movement.z;
            return 0;
        case TERRAIN_HIT_TYPE_FACE:
        case TERRAIN_HIT_TYPE_CYLINDER:
        case TERRAIN_HIT_TYPE_VERTEX:
        case TERRAIN_HIT_TYPE_SPHERE: {
            query->hit_time -= query->separation_epsilon;
            if (query->hit_time < 0.0f) {
                query->hit_time = 0.0f;
            }

            query->position.x += query->movement.x * query->hit_time;
            query->position.y += query->movement.y * query->hit_time;
            query->position.z += query->movement.z * query->hit_time;

            const f32 minimum_walkable_normal_y = 0.707f;
            if (query->impact_normal.y < minimum_walkable_normal_y) {
                hit_flags[0] = 0;
                return 0;
            }

            hit_flags[0] = 1;
            hit_flags[1] = 1;
            query->position.y += query->movement_normal.y * 0.004f;
            return 0;
        }
        default:
            return 1;
    }
}

i32 TerrainPlatformMoveCheck(nuvec_s *position, nuvec_s *normal, i32 platform_index, i32 resolve_impact,
                             i32 keep_embedded_disabled) {
    i32 group_index = CurTerr->platforms[platform_index].terrain_group_index;
    u8 *entry = static_cast<u8 *>(TerI->scan_list);
    while (*reinterpret_cast<i16 *>(entry) > 0) {
        i16 *header = reinterpret_cast<i16 *>(entry);
        if (header[1] == group_index)
            header[0] = -header[0];
        i32 count = header[0];
        if (count < 0)
            count = -count;
        entry += 4 + count * 4;
    }
    if (position->y > TerI->position.y && TerI->position.y + 0.01f > position->y)
        TerI->position.y = position->y;
    NUVEC saved_movement = TerI->movement;
    TERRAIN_SHAPE *saved_surface = TerI->surface;
    i16 saved_group = TerI->terrain_group_index;
    i16 saved_scan_group = TerI->scan_group_index;
    f32 saved_time = TerI->hit_time;
    f32 saved_unclamped_time = TerI->unclamped_hit_time;
    NUVEC saved_movement_normal = TerI->movement_normal;
    u8 saved_hit_type = TerI->hit_type;
    NUVEC saved_impact_normal = TerI->impact_normal;
    TerI->movement.x = position->x - TerI->position.x;
    TerI->movement.y = position->y - TerI->position.y;
    TerI->movement.z = position->z - TerI->position.z;
    DerotateMovementVector();
    HitTerrain();
    if (resolve_impact != 0 && TerI->hit_type != 0) {
        TerrainImpactNorm();
        TerrainImpactPlatform(TerI->hit_flags);
        if (normal != NULL)
            *normal = TerI->movement_normal;
        *position = TerI->position;
    }
    u8 hit_type = TerI->hit_type;
    TerI->movement = saved_movement;
    TerI->terrain_group_index = saved_group;
    TerI->surface = saved_surface;
    TerI->scan_group_index = saved_scan_group;
    TerI->hit_time = saved_time;
    TerI->unclamped_hit_time = saved_unclamped_time;
    TerI->movement_normal = saved_movement_normal;
    TerI->impact_normal = saved_impact_normal;
    if (hit_type <= 15 || keep_embedded_disabled == 0) {
        entry = static_cast<u8 *>(TerI->scan_list);
        while (*reinterpret_cast<i16 *>(entry) != 0) {
            i16 *header = reinterpret_cast<i16 *>(entry);
            i32 count = header[0];
            if (count < 0)
                count = -count;
            if (header[1] == group_index)
                header[0] = count;
            entry += 4 + count * 4;
        }
    }
    TerI->hit_type = saved_hit_type;
    return hit_type == 0;
}

i32 TerrainPlatformEmbedded(nuvec_s *movement_delta) {
    TerrainQuery_s *old_query = TerI;
    i32 platform_index = CurTerr->groups[old_query->terrain_group_index].scene_index;
    NUMTX *matrix = static_cast<NUMTX *>(CurTerr->platforms[platform_index].scene_object);
    if (__builtin_expect(matrix == NULL, 0))
        return 1;
    NUMTX *previous = &CurTerr->platforms[platform_index].previous_matrix;
    if (previous->m30 == matrix->m30 && previous->m31 == matrix->m31 && previous->m32 == matrix->m32) {
        if (__builtin_expect(!(CurTerr->platforms[platform_index].flags & 1), 0))
            return 1;
        if (__builtin_expect(previous->m00 == matrix->m00 && previous->m01 == matrix->m01 && previous->m02 == matrix->m02 &&
            previous->m10 == matrix->m10 && previous->m11 == matrix->m11 && previous->m12 == matrix->m12 &&
            previous->m20 == matrix->m20 && previous->m21 == matrix->m21 && previous->m22 == matrix->m22, 1))
            return 1;
    }
    i32 saved_sphere = curSphereter;
    curSphereter = 0;
    ScaleTerrain = static_cast<TERRAIN_SHAPE *>(ScaleTerrainT2);
    TerrainQuery_s *query = static_cast<TerrainQuery_s *>(NuScratchAlloc32(sizeof(TerrainQuery_s)));
    TerI = query;
    void *scratch = NuScratchAlloc32(0xd0);
    NUVEC4 *vertices = reinterpret_cast<NUVEC4 *>((reinterpret_cast<uintptr_t>(scratch) + 31) & ~uintptr_t(15));
    query->collision_radius = old_query->collision_radius;
    query->object_index = old_query->object_index;
    query->inverse_object_scale_sq = old_query->inverse_object_scale_sq;
    query->hit_flags = old_query->hit_flags;
    query->inverse_collision_radius = old_query->inverse_collision_radius;
    query->scan_result = old_query->scan_result;
    query->separation_epsilon = old_query->separation_epsilon;
    query->compare_epsilon = old_query->compare_epsilon;
    query->collision_radius_sq = old_query->collision_radius_sq;
    query->object_scale_sq = old_query->object_scale_sq;
    query->inverse_object_scale = old_query->inverse_object_scale;
    query->radius = old_query->radius;
    query->object_scale = old_query->object_scale;
    query->movement.x = (previous->m30 - matrix->m30) * 1.73f;
    query->movement.y = ((previous->m31 - matrix->m31) * 1.73f) * query->inverse_object_scale;
    query->movement.z = (previous->m32 - matrix->m32) * 1.73f;
    if (CurTerr->platforms[platform_index].flags & 1) {
        NuMtxInvRSS(&tertempmat, previous);
        tertempvec4.z = old_query->position.z - previous->m32;
        tertempvec4.x = old_query->position.x - previous->m30;
        tertempvec4.y = (old_query->position.y - query->collision_radius) * query->object_scale - previous->m31;
        tertempvec4.w = 1.0f;
        NuVec4MtxTransformVU0(&tertempvec4, &tertempvec4, &tertempmat);
        NuVec4MtxTransformVU0(&tertempvec4, &tertempvec4, matrix);
        query->movement.x = (old_query->position.x - tertempvec4.x) * 1.3f;
        query->movement.y =
            (old_query->position.y - (tertempvec4.y * query->inverse_object_scale + query->collision_radius)) * 1.3f;
        query->movement.z = (old_query->position.z - tertempvec4.z) * 1.3f;
    }
    query->movement.x -= 0.01f * old_query->movement_normal.x;
    query->movement.y -= 0.01f * old_query->movement_normal.y;
    query->movement.z -= 0.01f * old_query->movement_normal.z;
    query->position.x = old_query->position.x - query->movement.x * 0.91f;
    query->position.y = old_query->position.y - query->movement.y * 0.91f;
    query->position.z = old_query->position.z - query->movement.z * 0.91f;

    TERRAIN_SHAPE **cursor = reinterpret_cast<TERRAIN_SHAPE **>(query->scan_list_storage + 4);
    i32 transformed_count = 0;
    i32 count = 0;
    TERRAIN_SHAPE_BATCH *batch =
        static_cast<TERRAIN_SHAPE_BATCH *>(CurTerr->groups[old_query->terrain_group_index].data);
    if (query->object_scale == 1.0f) {
        if (CurTerr->platforms[platform_index].flags & 1) {
            while (batch->marker >= 0) {
                i32 shape_count = batch->shape_count;
                TERRAIN_SHAPE *source = reinterpret_cast<TERRAIN_SHAPE *>(batch + 1);
                for (i32 remaining = shape_count; remaining > 0; --remaining, ++source) {
                    if (source->material[1] != 0)
                        continue;
                    vertices[0].x = source->vectors[0].x;
                    vertices[0].y = source->vectors[0].y;
                    vertices[0].z = source->vectors[0].z;
                    vertices[0].w = 0.0f;
                    vertices[1].x = source->vectors[1].x;
                    vertices[1].y = source->vectors[1].y;
                    vertices[1].z = source->vectors[1].z;
                    vertices[1].w = 0.0f;
                    vertices[2].x = source->vectors[2].x;
                    vertices[2].y = source->vectors[2].y;
                    vertices[2].w = 0.0f;
                    vertices[2].z = source->vectors[2].z;
                    NuVec4MtxTransformVU0x3(
                        vertices, vertices,
                        static_cast<NUMTX *>(
                            CurTerr->platforms[CurTerr->groups[old_query->terrain_group_index].scene_index]
                                .scene_object));
                    bool quad = !(source->normals[1].y >= 65535.0f);
                    if (!quad) {
                        vertices[3] = vertices[2];
                    } else {
                        vertices[3].x = source->vectors[3].x;
                        vertices[3].y = source->vectors[3].y;
                        vertices[3].z = source->vectors[3].z;
                        vertices[3].w = 0.0f;
                        NuVec4MtxTransformVU0(
                            &vertices[3], &vertices[3],
                            static_cast<NUMTX *>(
                                CurTerr->platforms[CurTerr->groups[old_query->terrain_group_index].scene_index]
                                    .scene_object));
                    }
                    TERRAIN_SHAPE *surface = &ScaleTerrain[transformed_count];
                    memcpy(surface->material, source->material, 4);
                    surface->vectors[0].x = vertices[0].x;
                    surface->vectors[0].y = vertices[0].y;
                    surface->vectors[0].z = vertices[0].z;
                    surface->vectors[1].x = vertices[1].x;
                    surface->vectors[1].y = vertices[1].y;
                    surface->vectors[1].z = vertices[1].z;
                    surface->vectors[2].x = vertices[2].x;
                    surface->vectors[2].z = vertices[2].z;
                    surface->vectors[2].y = vertices[2].y;
                    if (quad) {
                        surface->vectors[3].x = vertices[3].x;
                        surface->vectors[3].y = vertices[3].y;
                        surface->vectors[3].z = vertices[3].z;
                    }
                    if (__builtin_expect(!quad, 0)) {
                        surface->normals[1].y = 65536.0f;
                    } else {
                        vertices[0].x = surface->vectors[1].x - surface->vectors[3].x;
                        vertices[0].z = surface->vectors[1].z - surface->vectors[3].z;
                        vertices[0].y = surface->vectors[1].y - surface->vectors[3].y;
                        vertices[1].x = surface->vectors[2].x - surface->vectors[3].x;
                        vertices[1].z = surface->vectors[2].z - surface->vectors[3].z;
                        vertices[1].y = surface->vectors[2].y - surface->vectors[3].y;
                        surface->normals[1] = TerCrossProduct(reinterpret_cast<NUVEC *>(&vertices[0]),
                                                              reinterpret_cast<NUVEC *>(&vertices[1]));
                        surface = &ScaleTerrain[transformed_count];
                        NUVEC *normal = &surface->normals[1];
                        f32 length = NuFsqrt(normal->x * normal->x + normal->y * normal->y + normal->z * normal->z);
                        f32 inverse = length == 0.0f ? 0.0f : 1.0f / length;
                        surface = &ScaleTerrain[transformed_count];
                        surface->normals[1].x *= inverse;
                        surface->normals[1].y *= inverse;
                        surface->normals[1].z *= inverse;
                    }
                    vertices[0].y = surface->vectors[2].y - surface->vectors[0].y;
                    vertices[0].x = surface->vectors[2].x - surface->vectors[0].x;
                    vertices[1].x = surface->vectors[1].x - surface->vectors[0].x;
                    vertices[0].z = surface->vectors[2].z - surface->vectors[0].z;
                    vertices[1].z = surface->vectors[1].z - surface->vectors[0].z;
                    vertices[1].y = surface->vectors[1].y - surface->vectors[0].y;
                    surface->normals[0] = TerCrossProduct(reinterpret_cast<NUVEC *>(&vertices[0]),
                                                          reinterpret_cast<NUVEC *>(&vertices[1]));
                    surface = &ScaleTerrain[transformed_count];
                    NUVEC *normal = &surface->normals[0];
                    f32 length = NuFsqrt(normal->x * normal->x + normal->y * normal->y + normal->z * normal->z);
                    surface = &ScaleTerrain[transformed_count];
                    f32 inverse = length == 0.0f ? 0.0f : 1.0f / length;
                    surface->normals[0].x *= inverse;
                    surface->normals[0].y *= inverse;
                    surface->normals[0].z *= inverse;
                    *cursor++ = surface;
                    ++count;
                    ++transformed_count;
                }
                batch = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(source);
            }
        } else {
            while (batch->marker >= 0) {
                TERRAIN_SHAPE *source = reinterpret_cast<TERRAIN_SHAPE *>(batch + 1);
                i32 shape_count = batch->shape_count;
                for (i32 remaining = shape_count; remaining > 0; --remaining, ++source) {
                    if (source->material[1] != 0)
                        continue;
                    *cursor++ = source;
                    ++count;
                }
                batch = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(source);
            }
        }
    } else {
        if (CurTerr->platforms[platform_index].flags & 1) {
            while (batch->marker >= 0) {
                i32 shape_count = batch->shape_count;
                TERRAIN_SHAPE *source = reinterpret_cast<TERRAIN_SHAPE *>(batch + 1);
                for (i32 remaining = shape_count; remaining > 0; --remaining, ++source) {
                    if (source->material[1] != 0)
                        continue;
                    vertices[0].x = source->vectors[0].x;
                    vertices[0].y = source->vectors[0].y;
                    vertices[0].z = source->vectors[0].z;
                    vertices[0].w = 0.0f;
                    vertices[1].x = source->vectors[1].x;
                    vertices[1].y = source->vectors[1].y;
                    vertices[1].z = source->vectors[1].z;
                    vertices[1].w = 0.0f;
                    vertices[2].y = source->vectors[2].y;
                    vertices[2].x = source->vectors[2].x;
                    vertices[2].z = source->vectors[2].z;
                    vertices[2].w = 0.0f;
                    NuVec4MtxTransformVU0x3(
                        vertices, vertices,
                        static_cast<NUMTX *>(
                            CurTerr->platforms[CurTerr->groups[old_query->terrain_group_index].scene_index]
                                .scene_object));
                    bool quad = source->normals[1].y < 65535.0f;
                    if (quad) {
                        vertices[3].x = source->vectors[3].x;
                        vertices[3].y = source->vectors[3].y;
                        vertices[3].z = source->vectors[3].z;
                        vertices[3].w = 0.0f;
                        NuVec4MtxTransformVU0(
                            &vertices[3], &vertices[3],
                            static_cast<NUMTX *>(
                                CurTerr->platforms[CurTerr->groups[old_query->terrain_group_index].scene_index]
                                    .scene_object));
                    } else {
                        vertices[3] = vertices[2];
                    }
                    TERRAIN_SHAPE *surface = &ScaleTerrain[transformed_count];
                    memcpy(surface->material, source->material, 4);
                    surface->vectors[0].x = vertices[0].x;
                    surface->vectors[0].y = (vertices[0].y + CurTerr->groups[old_query->terrain_group_index].origin.y) *
                                                query->inverse_object_scale -
                                            CurTerr->groups[old_query->terrain_group_index].origin.y;
                    surface->vectors[0].z = vertices[0].z;
                    surface->vectors[1].x = vertices[1].x;
                    surface->vectors[1].y = (vertices[1].y + CurTerr->groups[old_query->terrain_group_index].origin.y) *
                                                query->inverse_object_scale -
                                            CurTerr->groups[old_query->terrain_group_index].origin.y;
                    surface->vectors[1].z = vertices[1].z;
                    surface->vectors[2].x = vertices[2].x;
                    surface->vectors[2].y = (vertices[2].y + CurTerr->groups[old_query->terrain_group_index].origin.y) *
                                                query->inverse_object_scale -
                                            CurTerr->groups[old_query->terrain_group_index].origin.y;
                    surface->vectors[2].z = vertices[2].z;
                    if (quad) {
                        surface->vectors[3].x = vertices[3].x;
                        surface->vectors[3].y =
                            (vertices[3].y + CurTerr->groups[old_query->terrain_group_index].origin.y) *
                                query->inverse_object_scale -
                            CurTerr->groups[old_query->terrain_group_index].origin.y;
                        surface->vectors[3].z = vertices[3].z;
                    }
                    if (__builtin_expect(!quad, 1)) {
                        surface->normals[1].y = 65536.0f;
                    } else {
                        vertices[0].x = surface->vectors[1].x - surface->vectors[3].x;
                        vertices[0].y = surface->vectors[1].y - surface->vectors[3].y;
                        vertices[0].z = surface->vectors[1].z - surface->vectors[3].z;
                        vertices[1].x = surface->vectors[2].x - surface->vectors[3].x;
                        vertices[1].y = surface->vectors[2].y - surface->vectors[3].y;
                        vertices[1].z = surface->vectors[2].z - surface->vectors[3].z;
                        surface->normals[1] = TerCrossProduct(reinterpret_cast<NUVEC *>(&vertices[0]),
                                                              reinterpret_cast<NUVEC *>(&vertices[1]));
                        surface = &ScaleTerrain[transformed_count];
                        NUVEC *normal = &surface->normals[1];
                        f32 length = NuFsqrt(normal->x * normal->x + normal->y * normal->y + normal->z * normal->z);
                        f32 inverse = length == 0.0f ? 0.0f : 1.0f / length;
                        surface = &ScaleTerrain[transformed_count];
                        surface->normals[1].x *= inverse;
                        surface->normals[1].y *= inverse;
                        surface->normals[1].z *= inverse;
                    }
                    vertices[0].x = surface->vectors[2].x - surface->vectors[0].x;
                    vertices[0].y = surface->vectors[2].y - surface->vectors[0].y;
                    vertices[1].x = surface->vectors[1].x - surface->vectors[0].x;
                    vertices[0].z = surface->vectors[2].z - surface->vectors[0].z;
                    vertices[1].y = surface->vectors[1].y - surface->vectors[0].y;
                    vertices[1].z = surface->vectors[1].z - surface->vectors[0].z;
                    surface->normals[0] = TerCrossProduct(reinterpret_cast<NUVEC *>(&vertices[0]),
                                                          reinterpret_cast<NUVEC *>(&vertices[1]));
                    surface = &ScaleTerrain[transformed_count];
                    NUVEC *normal = &surface->normals[0];
                    f32 length = NuFsqrt(normal->x * normal->x + normal->y * normal->y + normal->z * normal->z);
                    f32 inverse = length == 0.0f ? 0.0f : 1.0f / length;
                    surface = &ScaleTerrain[transformed_count];
                    surface->normals[0].x *= inverse;
                    surface->normals[0].y *= inverse;
                    surface->normals[0].z *= inverse;
                    *cursor++ = surface;
                    ++count;
                    ++transformed_count;
                }
                batch = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(source);
            }
        } else {
            auto query_object_scale = query->object_scale;
            while (batch->marker >= 0) {
                i32 shape_count = batch->shape_count;
                TERRAIN_SHAPE *source = reinterpret_cast<TERRAIN_SHAPE *>(batch + 1);
                for (i32 remaining = shape_count; remaining > 0; --remaining, ++source) {
                    if (__builtin_expect(source->material[1] != 0, 0))
                        continue;
                    bool quad = source->normals[1].y < 65535.0f;
                    TERRAIN_SHAPE *surface = &ScaleTerrain[transformed_count];
                    memcpy(surface->material, source->material, 4);
                    surface->vectors[0].x = source->vectors[0].x;
                    surface->vectors[0].y =
                        (source->vectors[0].y + CurTerr->groups[old_query->terrain_group_index].origin.y) *
                            query->inverse_object_scale -
                        CurTerr->groups[old_query->terrain_group_index].origin.y;
                    surface->vectors[0].z = source->vectors[0].z;
                    surface->vectors[1].x = source->vectors[1].x;
                    surface->vectors[1].y =
                        (source->vectors[1].y + CurTerr->groups[old_query->terrain_group_index].origin.y) *
                            query->inverse_object_scale -
                        CurTerr->groups[old_query->terrain_group_index].origin.y;
                    surface->vectors[1].z = source->vectors[1].z;
                    surface->vectors[2].x = source->vectors[2].x;
                    surface->vectors[2].y =
                        (source->vectors[2].y + CurTerr->groups[old_query->terrain_group_index].origin.y) *
                            query->inverse_object_scale -
                        CurTerr->groups[old_query->terrain_group_index].origin.y;
                    surface->vectors[2].z = source->vectors[2].z;
                    if (quad) {
                        surface->vectors[3].x = source->vectors[3].x;
                        surface->vectors[3].y =
                            (source->vectors[3].y + CurTerr->groups[old_query->terrain_group_index].origin.y) *
                                query->inverse_object_scale -
                            CurTerr->groups[old_query->terrain_group_index].origin.y;
                        surface->vectors[3].z = source->vectors[3].z;
                    }
                    if (__builtin_expect(!!(quad), 0)) {
                        NUVEC *normal = &source->normals[1];
                        f32 length = NuFsqrt(normal->x * normal->x + (normal->y * normal->y) * query->object_scale_sq +
                                             normal->z * normal->z);
                        f32 inverse = length == 0.0f ? 0.0f : 1.0f / length;
                        surface = &ScaleTerrain[transformed_count];
                        surface->normals[1].y = (normal->y * query_object_scale) * inverse;
                        surface->normals[1].x = normal->x * inverse;
                        surface->normals[1].z = normal->z * inverse;
                    } else {
                        surface->normals[1].y = 65536.0f;
                    }
                    f32 length = NuFsqrt(source->normals[0].x * source->normals[0].x +
                                         (source->normals[0].y * source->normals[0].y) * query->object_scale_sq +
                                         source->normals[0].z * source->normals[0].z);
                    f32 inverse = length == 0.0f ? 0.0f : 1.0f / length;
                    surface = &ScaleTerrain[transformed_count];
                    surface->normals[0].x = source->normals[0].x * inverse;
                    surface->normals[0].y = (source->normals[0].y * query_object_scale) * inverse;
                    surface->normals[0].z = source->normals[0].z * inverse;
                    *cursor++ = surface;
                    ++count;
                    ++transformed_count;
                }
                batch = reinterpret_cast<TERRAIN_SHAPE_BATCH *>(source);
            }
        }
    }
    i16 *header = reinterpret_cast<i16 *>(query->scan_list_storage);
    if (count != 0) {
        header[0] = count;
        header[1] = old_query->terrain_group_index;
        header = reinterpret_cast<i16 *>(cursor);
    }
    header[0] = 0;
    header[1] = 0;
    u8 flags[2] = {0, 0};
    DerotateMovementVector();
    HitTerrain();
    TerrainImpactNorm();
    if (__builtin_expect(TerrainImpactPlatform(flags) != 0, 0)) {
        NuScratchRelease();
        NuScratchRelease();
        TerI = old_query;
        ScaleTerrain = static_cast<TERRAIN_SHAPE *>(ScaleTerrainT1);
        curSphereter = saved_sphere;
        return 1;
    }
    query->start_position = query->position;
    TerI->movement.x = 0.0f;
    TerI->movement.y = -0.05f;
    TerI->movement.z = 0.0f;
    TerI->position.y = query->start_position.y + 0.025f;
    DerotateMovementVector();
    TerrOverRideScan = reinterpret_cast<tertype **>(old_query->scan_list_storage);
    HitTerrain();
    TerI->position.y = query->start_position.y;
    flags[0] = 0;
    if (TerI->hit_type >= 1 && TerI->hit_type <= 15) {
        query->start_position.y = ((TerI->movement.y * TerI->hit_time + query->start_position.y) + 0.001f) + 0.025f;
        TerI = old_query;
        if (!(query->start_position.y >= 2000000.0f)) {
            f32 delta = query->start_position.y - query->position.y;
            if (!(delta < -0.008f) &&
                (delta < 0.01f || query->movement.x * query->movement.x + query->movement.z * query->movement.z >
                                      (delta - 0.0025f) * (delta - 0.0025f))) {
                query->position.y += delta;
                flags[0] = 1;
            }
        } else {
            query->start_position.y = query->position.y;
        }
    } else {
        TerI = old_query;
        query->start_position.y = query->position.y;
    }
    if (__builtin_expect(!TerrainPlatformMoveCheck(&query->position, NULL, platform_index, 1, 1), 0))
        flags[0] = 0;
    TerI->position.x = query->position.x;
    TerI->position.y = query->position.y;
    TerI->position.z = query->position.z;
    if (flags[0] != 0 && CurTerr->groups[castnum].chunk_type == 1) {
        TerI->hit_flags[1] = 1;
        PlatformConnect(reinterpret_cast<char *>(old_query->hit_flags), &old_query->movement, movement_delta,
                        CurTerr->groups[castnum].scene_index);
    } else if (__builtin_expect(CurTrackInfo != NULL, 1)) {
        CurTrackInfo->flags &= ~TERRAIN_TRACK_FLAG_CONNECTED;
    }
    NuScratchRelease();
    NuScratchRelease();
    ScaleTerrain = static_cast<TERRAIN_SHAPE *>(ScaleTerrainT1);
    curSphereter = saved_sphere;
    TerI = old_query;
    return 0;
}

void StorePlatImpact() {
    TerrainQuery_s *query = TerI;
    const u8 hit_type = query->hit_type;
    if (hit_type == TERRAIN_HIT_TYPE_NONE || query->terrain_group_index == -1) {
        return;
    }

    TERRAIN_GROUP *group = &CurTerr->groups[query->terrain_group_index];
    if (group->chunk_type != TERRAIN_CHUNK_GROUP_SECONDARY) {
        return;
    }

    castnum = query->terrain_group_index;
    NUVEC impact_normal = query->movement_normal;

    switch (hit_type) {
        case TERRAIN_HIT_TYPE_CYLINDER:
        case TERRAIN_HIT_TYPE_VERTEX:
        case TERRAIN_HIT_TYPE_SPHERE:
        case TERRAIN_HIT_TYPE_CYLINDER | TERRAIN_HIT_TYPE_SECOND_NORMAL:
        case TERRAIN_HIT_TYPE_VERTEX | TERRAIN_HIT_TYPE_SECOND_NORMAL:
        case TERRAIN_HIT_TYPE_SPHERE | TERRAIN_HIT_TYPE_SECOND_NORMAL:
            RotateVec(&impact_normal, &impact_normal);
            query = TerI;
            if ((query->hit_type & TERRAIN_HIT_TYPE_SECOND_NORMAL) == 0) {
                impact_normal.x *= query->inverse_collision_radius;
                impact_normal.y *= query->inverse_collision_radius;
                impact_normal.z *= query->inverse_collision_radius;
            }
        case TERRAIN_HIT_TYPE_FACE:
        case TERRAIN_HIT_TYPE_FACE | TERRAIN_HIT_TYPE_SECOND_NORMAL:
            break;
        default:
            return;
    }

    const f32 unit_scale = 1.0f;
    if (query->object_scale != unit_scale) {
        const f32 normal_length = NuFsqrt(impact_normal.x * impact_normal.x +
                                          impact_normal.y * impact_normal.y * query->inverse_object_scale_sq +
                                          impact_normal.z * impact_normal.z);
        f32 inverse_normal_length = 0.0f;
        if (normal_length != 0.0f) {
            inverse_normal_length = unit_scale / normal_length;
        }

        query = TerI;
        impact_normal.x *= inverse_normal_length;
        impact_normal.y *= query->inverse_object_scale * inverse_normal_length;
        impact_normal.z *= inverse_normal_length;
    }

    query = TerI;
    PlatImpactId = CurTerr->groups[query->terrain_group_index].scene_index;
    PlatImpactNorm = impact_normal;
    PlatImpactTer = *query->surface;
}

i32 PlatformChecks(i32 count, nuvec_s *movement) {
    TerrainQuery_s *old_query = TerI;
    if (old_query->scan_list == NULL || *static_cast<i16 *>(old_query->scan_list) == 0 || CurTrackInfo == NULL ||
        CurTrackInfo->platform_contact_state == 0 || TerConTol == 0.0f)
        return count;
    TerrainQuery_s *query = static_cast<TerrainQuery_s *>(NuScratchAlloc32(sizeof(TerrainQuery_s)));
    TerI = query;
    u8 *input = static_cast<u8 *>(old_query->scan_list);
    u8 *output = query->scan_list_storage;
    while (*reinterpret_cast<i16 *>(input) > 0) {
        i16 *input_header = reinterpret_cast<i16 *>(input);
        i16 *output_header = reinterpret_cast<i16 *>(output);
        i32 shape_count = input_header[0];
        output_header[0] = input_header[0];
        output_header[1] = input_header[1];
        TERRAIN_SHAPE **input_shapes = reinterpret_cast<TERRAIN_SHAPE **>(input) + 1;
        TERRAIN_SHAPE **output_shapes = reinterpret_cast<TERRAIN_SHAPE **>(output) + 1;
        // The packed scan list is copied in 16-bit words, including both halves
        // of each target pointer. Preserve the full pointer on wider diagnostic hosts.
        i16 *input_words = reinterpret_cast<i16 *>(input_shapes);
        i16 *output_words = reinterpret_cast<i16 *>(output_shapes);
        for (i32 remaining = shape_count; remaining != 0; --remaining) {
            for (u32 word = 0; word < sizeof(TERRAIN_SHAPE *) / sizeof(i16); ++word)
                output_words[word] = input_words[word];
            output_words += sizeof(TERRAIN_SHAPE *) / sizeof(i16);
            input_words += sizeof(TERRAIN_SHAPE *) / sizeof(i16);
        }
        input = reinterpret_cast<u8 *>(input_words);
        output = reinterpret_cast<u8 *>(output_words);
    }
    reinterpret_cast<i16 *>(output)[0] = 0;
    reinterpret_cast<i16 *>(output)[1] = 0;
    TerI->collision_radius = old_query->collision_radius;
    TerI->object_scale = old_query->object_scale;
    TerI->inverse_object_scale_sq = old_query->inverse_object_scale_sq;
    TerI->inverse_collision_radius = old_query->inverse_collision_radius;
    TerI->separation_epsilon = old_query->separation_epsilon;
    TerI->inverse_object_scale = old_query->inverse_object_scale;
    TerI->compare_epsilon = old_query->compare_epsilon;
    TerI->collision_radius_sq = old_query->collision_radius_sq;
    TerI->object_scale_sq = old_query->object_scale_sq;
    TerI->platform_position = old_query->position;
    if (CurTrackInfo != NULL && (CurTrackInfo->flags & TERRAIN_TRACK_FLAG_CONNECTED)) {
        TERRAIN_PLATFORM *platform = &CurTerr->platforms[CurTrackInfo->platform_index];
        NUMTX *matrix = static_cast<NUMTX *>(platform->scene_object);
        NUMTX *previous = &platform->previous_matrix;
        if (platform->flags & 1) {
            NuMtxInvRSS(&tertempmat, previous);
            platform = &CurTerr->platforms[CurTrackInfo->platform_index];
            previous = &platform->previous_matrix;
            tertempvec4.x = old_query->position.x - previous->m30;
            tertempvec4.y = (old_query->position.y - TerI->collision_radius) * TerI->object_scale - previous->m31;
            tertempvec4.z = old_query->position.z - previous->m32;
            tertempvec4.w = 1.0f;
            NuVec4MtxTransformVU0(&tertempvec4, &tertempvec4, &tertempmat);
            NuVec4MtxTransformVU0(&tertempvec4, &tertempvec4,
                                  static_cast<NUMTX *>(CurTerr->platforms[CurTrackInfo->platform_index].scene_object));
            TerI->platform_position.x = tertempvec4.x;
            TerI->platform_position.y = tertempvec4.y * TerI->inverse_object_scale + TerI->collision_radius;
            TerI->platform_position.z = tertempvec4.z;
        } else {
            TerI->platform_position.x += matrix->m30 - previous->m30;
            TerI->platform_position.y += (matrix->m31 - previous->m31) * old_query->inverse_object_scale;
            TerI->platform_position.z += matrix->m32 - previous->m32;
        }
    }
    TerI->platform_normal = TerI->platform_position;
    TerI->position = TerI->platform_position;
    TerI->movement.x = 0.0f;
    TerI->movement.y = TerConTol * -2.0f;
    TerI->movement.z = 0.0f;
    TerI->position.y += TerConTol;
    DerotateMovementVector();
    f32 saved_epsilon = TerI->separation_epsilon;
    TerI->separation_epsilon = 0.0f;
    HitTerrain();
    StorePlatImpact();
    TerI->separation_epsilon = saved_epsilon;
    TerrainImpactNorm();
    u8 flags[2];
    TerrainImpactPlatform(flags);
    if (TerI->hit_type != 0)
        ShadNorm = TerI->impact_normal;
    TerI->platform_position.y = TerI->position.y - TerI->collision_radius;
    TerI = old_query;
    if (query->hit_type == 0 ||
        fabsf((query->platform_normal.y - query->platform_position.y) - old_query->collision_radius) >
            TerConTol * 0.5f ||
        query->movement_normal.y < 0.707f) {
        NuScratchRelease();
        return count;
    }
    TERRAIN_GROUP *group = &CurTerr->groups[query->terrain_group_index];
    i32 platform_index = group->scene_index;
    if (movement->y > TerConTol * 0.5f) {
        TERRAIN_PLATFORM *platform = &CurTerr->platforms[platform_index];
        NUMTX *matrix = static_cast<NUMTX *>(platform->scene_object);
        if (__builtin_expect(movement->y > (TerConTol * 0.5f + matrix->m31) - platform->previous_matrix.m31, 0)) {
            NuScratchRelease();
            return count;
        }
    }
    if (!(query->movement_normal.y < 0.707f) && query->terrain_group_index >= 0 && group->chunk_type == 1)
        CurTerr->platforms[platform_index].flags |= 2;
    old_query->platform_position.x = query->platform_position.x;
    old_query->platform_position.y = query->platform_position.y + old_query->collision_radius;
    if (!(CurTerr->platforms[CurTrackInfo->platform_index].flags & 1))
        old_query->platform_position.y += 0.0025f;
    old_query->platform_position.z = query->platform_position.z;
    NUVEC direction = {old_query->platform_position.x - old_query->position.x,
                       old_query->platform_position.y - old_query->position.y,
                       old_query->platform_position.z - old_query->position.z};
    f32 distance = NuFsqrt(direction.x * direction.x + direction.y * direction.y + direction.z * direction.z);
    if (distance == 0.0f || direction.x == 0.0f) {
        direction.x = 0.0f;
    } else {
        direction.x = direction.x / distance;
    }
    if (distance == 0.0f || direction.y == 0.0f) {
        direction.y = 0.0f;
    } else {
        direction.y = direction.y / distance;
    }
    if (distance == 0.0f || direction.z == 0.0f) {
        direction.z = 0.0f;
    } else {
        direction.z = direction.z / distance;
    }
    NUVEC previous_position = TerI->position;
    i32 clear = TerrainPlatformMoveCheck(&TerI->platform_position, &TerI->platform_normal, platform_index, 1, 0);
    bool opposing_contact = false;
    if (TerI->hit_type != 0 && TerI->terrain_group_index >= 0) {
        TERRAIN_GROUP *hit_group = &CurTerr->groups[TerI->terrain_group_index];
        if (__builtin_expect(hit_group->chunk_type == 1, 0))
            CurTrackInfo->platform_index = hit_group->scene_index;
        f32 dot = direction.x * TerI->platform_normal.x + direction.y * TerI->platform_normal.y +
                  direction.z * TerI->platform_normal.z;
        opposing_contact = dot < -0.7f;
    }
    if (opposing_contact || clear != 0) {
        TerrPoly = query->surface;
        TerI->position = TerI->platform_position;
        if (movement->y >= 0.0f) {
            TerI->movement.y *= 0.75f;
        } else {
            FullDeflect(&ShadNorm, &TerI->movement, &TerI->movement);
            FullDeflect(&ShadNorm, movement, movement);
        }
        TerI->hit_flags[1] = 1;
        PlatformConnect(reinterpret_cast<char *>(old_query->hit_flags), &old_query->movement, movement,
                        CurTerr->groups[query->terrain_group_index].scene_index);
    } else if (count - 1 > 0) {
        f32 travelled = (TerI->position.x - previous_position.x) * direction.x +
                        (TerI->position.y - previous_position.y) * direction.y +
                        (TerI->position.z - previous_position.z) * direction.z;
        if (distance > travelled && FullDeflectTest(&TerI->platform_normal, &direction, &TerI->platform_position)) {
            f32 dot = direction.x * TerI->platform_position.x + direction.y * TerI->platform_position.y +
                      direction.z * TerI->platform_position.z;
            if (dot > 0.0f) {
                f32 fraction = (distance - travelled) / dot;
                if (__builtin_expect(fraction < 0.8f, 0)) {
                    TerI->platform_position.x = TerI->platform_position.x * fraction + TerI->position.x;
                    TerI->platform_position.y = TerI->platform_position.y * fraction + TerI->position.y;
                    TerI->platform_position.z = TerI->platform_position.z * fraction + TerI->position.z;
                }
            }
        }
    }
    NuScratchRelease();
    TerI = old_query;
    return count - 1;
}

