extern "C" {
    i32 edanimLoadPage(char *path, NUGSCN *scene) {
        i32 page;
        for (page = 0; page < 8; ++page) {
            if (edanim_page_used[page] == 0)
                break;
        }
        if (page == 8)
            return -1;
        EdFileSetMedia(1);
        if (EdFileOpen(path, NUFILE_READ) == 0)
            return -1;
        EdFileSetReadWrongEndianess(1);
        i32 version = EdFileReadInt();
        if (version > 6) {
            EdFileSetReadWrongEndianess(0);
            EdFileClose();
            return -1;
        }
        i32 count = EdFileReadInt();
        if (count + edanim_params_used > 64)
            count = 64 - edanim_params_used;
        i32 slot = 0;
        for (i32 index = 0; index < count; ++index) {
            while (AnimParams[slot].instance_id != -1 && slot < 64)
                ++slot;
            if (slot >= 64)
                continue;
            char name[20];
            EdFileRead(name, 20);
            AnimParams[slot].instance_id = edanimLookupSpecial(name, scene);
            AnimParams[slot].effect_count = EdFileReadInt();
            if (__builtin_expect(version > 1, 1)) {
                AnimParams[slot].sound_count = EdFileReadInt();
            } else {
                AnimParams[slot].sound_count = 0;
            }
            AnimParams[slot].field_00c = EdFileReadInt();
            AnimParams[slot].field_010 = EdFileReadInt();
            AnimParams[slot].field_014 = EdFileReadFloat();
            AnimParams[slot].field_018 = EdFileReadFloat();
            if (AnimParams[slot].effect_count > 8)
                AnimParams[slot].effect_count = 8;
            for (i32 effect = 0; effect < AnimParams[slot].effect_count; ++effect) {
                EdFileRead(AnimParams[slot].effect_names[effect], 16);
                AnimParams[slot].effect_ids[effect] = -1;
                if (version > 4) {
                    if (version == 5) {
                        AnimParams[slot].effect_intervals[effect] = static_cast<i32>(EdFileReadFloat());
                    } else {
                        AnimParams[slot].effect_intervals[effect] = EdFileReadInt();
                    }
                } else {
                    i32 interval = EdFileReadInt();
                    AnimParams[slot].effect_intervals[effect] = interval > 0    ? interval * 60
                                                                : interval == 0 ? 0
                                                                                : -60 / interval;
                }
                AnimParams[slot].effect_flags[effect] = EdFileReadInt();
                EdFileReadNuVec(reinterpret_cast<NUVEC *>(AnimParams[slot].effect_positions[effect]));
                if (version > 2) {
                    AnimParams[slot].effect_angles[effect] = EdFileReadShort();
                    AnimParams[slot].effect_angle_ranges[effect] = EdFileReadShort();
                } else {
                    AnimParams[slot].effect_angles[effect] = 0;
                    AnimParams[slot].effect_angle_ranges[effect] = 0;
                }
            }
            AnimParams[slot].field_17c = 0.99f;
            if (__builtin_expect(version > 1, 1)) {
                if (__builtin_expect(AnimParams[slot].sound_count > 8, 1))
                    AnimParams[slot].sound_count = 8;
                for (i32 sound = 0; sound < AnimParams[slot].sound_count; ++sound) {
                    EdFileRead(AnimParams[slot].sound_names[sound], 16);
                    AnimParams[slot].sound_ids[sound] = -1;
                    AnimParams[slot].sound_flags[sound] = EdFileReadInt();
                    AnimParams[slot].sound_values[sound] = EdFileReadFloat();
                    EdFileReadNuVec(reinterpret_cast<NUVEC *>(AnimParams[slot].sound_positions[sound]));
                }
            }
            nuhspecial_s special;
            NuGScnGetSpecial(&special, scene, AnimParams[slot].instance_id);
            AnimParams[slot].platform_id = FindPlatInst(NuSpecialGetInstanceix(&special));
            if (__builtin_expect(version > 3, 1)) {
                AnimParams[slot].bounce_impulse = EdFileReadFloat();
                AnimParams[slot].bounce_spring = EdFileReadFloat();
                AnimParams[slot].bounce_damping = EdFileReadFloat();
            } else {
                AnimParams[slot].bounce_impulse = 0.0f;
                AnimParams[slot].bounce_spring = 0.0f;
                AnimParams[slot].bounce_damping = 0.0f;
            }
            if (AnimParams[slot].platform_id != -1)
                PlatInstBounce(AnimParams[slot].platform_id, AnimParams[slot].bounce_impulse,
                               AnimParams[slot].bounce_spring, AnimParams[slot].bounce_damping);
            AnimParams[slot].page = static_cast<i8>(page);
            ++edanim_params_used;
        }
        EdFileSetReadWrongEndianess(0);
        EdFileClose();
        edanim_page_used[page] = 1;
        edanim_page_scene[page] = scene;
        edanim_next_param = count;
        edbits_anim_page = page;
        edanim_particle_mode = 0;
        edanim_nearest = -1;
        edanim_nearest_param_id = -1;
        edanimDetermineNearestAnim(1.0f);
        return page;
    }

}

static __attribute__((used)) void edanimcbFileLoad(eduimenu_s *menu, eduiitem_s *, u32) {
    char path[256];
    char directory[256];
    char name[256];
    char extension[256];
    if (!edbits_level_save_directory[0])
        strcpy(directory, ".");
    else
        strcpy(directory, edbits_level_save_directory);
    if (!edbits_level_save_name[0])
        strcpy(name, "anims");
    else
        strcpy(name, edbits_level_save_name);
    if (!edbits_level_save_extension[0])
        strcpy(extension, "anm");
    else
        strcpy(extension, edbits_level_save_extension);
    sprintf(path, "%s\\%s.%s", directory, name, extension);
    edanimParamReset();
    i32 page = -1;
    if (NuFileExists(path)) {
        page = edanimLoadPage(path, edbits_base_scene);
    }
    edanimStartAllPages();
    if (page >= 0)
        eduiCreateMessageMenu(menu, const_cast<char *>("Loaded OK"), 1);
    else
        eduiCreateMessageMenu(menu, const_cast<char *>("File Load Error"), 0);
}

i32 edanimParamCreate(i32 instance_id) {
    if (edanim_params_used == 64) {
        return -1;
    }
    const i32 start = edanim_next_param;
    while (AnimParams[edanim_next_param].instance_id != -1) {
        edanim_next_param++;
        if (edanim_next_param >= 65)
            edanim_next_param = 0;
        if (edanim_next_param == start) {
            edanim_next_param = start;
            return -1;
        }
    }
    AnimParams[edanim_next_param].effect_count = 0;
    AnimParams[edanim_next_param].instance_id = instance_id;
    nuhspecial_s special;
    NuGScnGetSpecial(&special, edbits_base_scene, instance_id);
    AnimParams[edanim_next_param].platform_id = FindPlatInst(NuSpecialGetInstanceix(&special));
    AnimParams[edanim_next_param].bounce_impulse = 0.0f;
    AnimParams[edanim_next_param].bounce_spring = 0.0f;
    AnimParams[edanim_next_param].bounce_damping = 0.0f;
    if (AnimParams[edanim_next_param].platform_id != -1) {
        PlatInstBounce(AnimParams[edanim_next_param].platform_id, 0.0f, 0.0f, 0.0f);
    }
    AnimParams[edanim_next_param].page = static_cast<i8>(edbits_anim_page);
    edanim_page_used[edbits_anim_page] = 1;
    edanim_page_on[edbits_anim_page] = 1;
    if (!edanim_page_scene[edbits_anim_page]) {
        edanim_page_scene[edbits_anim_page] = edbits_base_scene;
    }
    const i32 created = edanim_next_param;
    edanim_next_param = created + 1;
    ++edanim_params_used;
    return created;
}

void edanimDoInput(nupad_s *pad) {
    if ((pad->digital_buttons & 0x100) == 0)
        edcamMove(pad);

    if ((pad->digital_buttons & 0x100) != 0) {
        if (edanim_sound_mode == 0 && (pad->digital_buttons_pressed & 0x80) != 0) {
            if (edanim_particle_mode != 0) {
                edanim_particle_mode = 0;
            } else if (edanim_nearest != -1 && edanim_nearest_param_id != -1) {
                edanim_particle_mode = 1;
                edanim_nearest_particle = -1;
            }
        }
        if (edanim_particle_mode != 0) {
            if (edanim_nearest_particle != -1) {

                if (pad->digital_buttons_pressed & 0x8) {
                    if (++edanim_nearest_particle == AnimParams[edanim_nearest_param_id].effect_count)
                        edanim_nearest_particle = 0;
                }
                if (pad->digital_buttons_pressed & 0x2) {
                    if (--edanim_nearest_particle == -1)
                        edanim_nearest_particle = AnimParams[edanim_nearest_param_id].effect_count - 1;
                }
            } else {
                edanimDetermineNearestParticle(-1.0f);
            }
            if (edanim_nearest_particle != -1) {
                nuhspecial_s special;
                NuGScnGetSpecial(&special, edbits_base_scene, edanim_nearest);

                NUVEC position;
                NUVEC *origin = NuSpecialGetPos(&special);
                NuVecAdd(&position, origin,
                         reinterpret_cast<NUVEC *>(
                             AnimParams[edanim_nearest_param_id].effect_positions[edanim_nearest_particle]));
                edcamSetPos(&position);
                edanim_emitrotz = AnimParams[edanim_nearest_param_id].effect_angles[edanim_nearest_particle];
                edanim_emitroty = AnimParams[edanim_nearest_param_id].effect_angle_ranges[edanim_nearest_particle];
                edanim_particle_type = AnimParams[edanim_nearest_param_id].effect_ids[edanim_nearest_particle];
            }
        } else {
            if ((pad->digital_buttons_pressed & 0x10) != 0) {
                if (edanim_sound_mode != 0) {
                    edanim_sound_mode = 0;
                } else if (edanim_nearest != -1 && edanim_nearest_param_id != -1) {
                    edanim_sound_mode = 1;
                    edanim_nearest_sound = -1;
                }
            }
            if (edanim_sound_mode == 0) {
                if (edanim_nearest != -1) {
                    if (pad->digital_buttons_pressed & 0x8) {
                        if (++edanim_nearest == NuGScnNumSpecials(edbits_base_scene))
                            edanim_nearest = 0;
                    }
                    if (pad->digital_buttons_pressed & 0x2) {
                        if (--edanim_nearest == -1)
                            edanim_nearest = NuGScnNumSpecials(edbits_base_scene) - 1;
                    }
                } else {
                    edanimDetermineNearestAnim(-1.0f);
                }
                if (edanim_nearest != -1) {
                    nuhspecial_s special;
                    NuGScnGetSpecial(&special, edbits_base_scene, edanim_nearest);
                    edcamSetPos(NuSpecialGetPos(&special));
                    edanim_nearest_param_id = -1;
                    for (u32 index = 0; index < 64; ++index) {
                        if (AnimParams[index].instance_id == edanim_nearest) {
                            edanim_nearest_param_id = index;
                            break;
                        }
                    }
                }
            } else {
                if (edanim_nearest_sound == -1) {
                    edanimDetermineNearestSound(-1.0f);
                } else {

                    if (pad->digital_buttons_pressed & 0x8) {
                        if (++edanim_nearest_sound == AnimParams[edanim_nearest_param_id].sound_count)
                            edanim_nearest_sound = 0;
                    }
                    if (pad->digital_buttons_pressed & 0x2) {
                        if (--edanim_nearest_sound == -1)
                            edanim_nearest_sound = AnimParams[edanim_nearest_param_id].sound_count - 1;
                    }
                }
                if (edanim_nearest_sound != -1) {
                    nuhspecial_s special;
                    NuGScnGetSpecial(&special, edbits_base_scene, edanim_nearest);

                    NUVEC position;
                    NUVEC *origin = NuSpecialGetPos(&special);
                    NuVecAdd(&position, origin,
                             reinterpret_cast<NUVEC *>(
                                 AnimParams[edanim_nearest_param_id].sound_positions[edanim_nearest_sound]));
                    edcamSetPos(&position);
                    edanim_sound_type = AnimParams[edanim_nearest_param_id].sound_ids[edanim_nearest_sound];
                }
            }
        }
    }

    if (edanim_nearest_param_id != -1) {
        for (i32 effect = 0; effect < AnimParams[edanim_nearest_param_id].effect_count;) {
            if ((AnimParams[edanim_nearest_param_id].effect_ids[effect] == -1 ||
                 debtab[AnimParams[edanim_nearest_param_id].effect_ids[effect]] == nullptr) &&
                AnimParams[edanim_nearest_param_id].effect_names[effect][0] != '\0') {
                AnimParams[edanim_nearest_param_id].effect_ids[effect] =
                    LookupDebrisEffect(AnimParams[edanim_nearest_param_id].effect_names[effect]);
                if (AnimParams[edanim_nearest_param_id].effect_ids[effect] == -1) {
                    edanimParticleDestroy(edanim_nearest_param_id, effect);
                    continue;
                }
            }
            ++effect;
        }
    }

    edcamGetPosAng(&edanim_cam_pos, &edanim_cam_ax, &edanim_cam_ay);
    if ((pad->digital_buttons & 0x100) == 0) {
        if (pad->digital_buttons_pressed & 0x80)
            edanim_active_menu = edanim_options_menu;
        if (pad->digital_buttons_pressed & 0x40) {
            if (edanim_particle_mode != 0) {
                edanimParticleCreate(&edanim_cam_pos);
            } else if (edanim_sound_mode != 0) {
                edanimSoundCreate(&edanim_cam_pos);
            } else if (edanim_nearest != -1 && edanim_nearest_param_id == -1) {
                edanim_nearest_param_id = edanimParamCreate(edanim_nearest);
            }
        }
        if (__builtin_expect(pad->digital_buttons & 0x20 != 0, 1)) {
            if (__builtin_expect(edanim_particle_mode != 0 && edanim_nearest_particle != -1, 0)) {
                edanimParticlePlace(edanim_nearest_particle, &edanim_cam_pos);
            } else if (edanim_nearest_sound != -1 && edanim_sound_mode != 0) {
                edanimSoundPlace(edanim_nearest_sound, &edanim_cam_pos);
            }
        }
        if (pad->digital_buttons_pressed & 0x10) {
            if (edanim_particle_mode != 0) {
                if (edanim_nearest_particle != -1) {
                    edanimParticleDestroy(edanim_nearest_param_id, edanim_nearest_particle);
                    edanim_nearest_particle = -1;
                }
            } else if (edanim_sound_mode != 0) {
                if (edanim_nearest_sound != -1) {
                    edanimSoundDestroy(edanim_nearest_param_id, edanim_nearest_sound);
                    edanim_nearest_sound = -1;
                }
            } else {
                if (edanim_nearest_param_id != -1)
                    edanimParamDestroy(edanim_nearest_param_id);
                edanim_nearest_param_id = -1;
                edanim_nearest = -1;
            }
        }
    }
    if (edanim_particle_mode != 0) {
        edanim_emitroty += pad->analog_left_pad_right - pad->analog_left_pad_left;
        const i32 raised = edanim_emitrotz + pad->analog_left_pad_up;
        const i32 rotation = (raised < 0 ? raised : 0) - pad->analog_left_pad_down;
        if (rotation <= -32768) {
            edanim_emitrotz = -32768;
        } else {
            edanim_emitrotz = rotation;
        }
    }
}

static i32 edanimProc(f32 delta_time, nupad_s *pad) {
    if (edanim_active_menu) {
        eduiMenuProcess(edanim_active_menu, delta_time, pad);
        return 0;
    }

    edanimDoInput(pad);
    if (edanim_particle_mode) {
        edanimDetermineNearestParticle(1.0f);
    } else if (edanim_sound_mode) {
        edanimDetermineNearestSound(1.0f);
    } else {
        edanimDetermineNearestAnim(1.0f);
    }

    if (pad->digital_buttons_pressed & 0x800) {
        edanim_particle_mode = 0;
        return 1;
    }
    return 0;
}

extern "C" {
    i32 PlatInstGetHit(i32 index) {
        if (CurTerr != NULL && index >= 0 && index < CurTerr->max_platforms)
            return (CurTerr->platforms[index].flags & 2) != 0;
        return 0;
    }

    void PlatInstCenter(i32 index, NUVEC *position) {
        if (CurTerr != NULL && index >= 0 && index < CurTerr->max_platforms)
            *position = CurTerr->groups[CurTerr->platforms[index].terrain_group_index].origin;
    }

    void PlatOnOff(i32 index, i32 enabled) {
        if (CurTerr != NULL && index >= 0 && index < CurTerr->max_platforms) {
            if (enabled != 0) {
                CurTerr->groups[CurTerr->platforms[index].terrain_group_index].chunk_type = 1;
                return;
            }
            CurTerr->groups[CurTerr->platforms[index].terrain_group_index].chunk_type = -1;
        }
    }

    i32 DeletePlatinst(i32 index) {
        if (index < 0)
            return 0;
        TERRSET *terrain = CurTerr;
        if (index >= terrain->max_platforms)
            return 0;
        TERRAIN_PLATFORM &platform = terrain->platforms[index];
        if (platform.scene_object == NULL)
            return 0;
        const i16 last_group = --terrain->group_count;
        const i32 index_count = --terrain->group_index_count;
        TERRAIN_GROUP &last = terrain->groups[last_group];
        terrain->platforms[last.scene_index].terrain_group_index = platform.terrain_group_index;
        terrain->groups[platform.terrain_group_index] = last;
        last.chunk_type = -1;
        platform.scene_object = NULL;
        TERRAIN_CELL &cell = terrain->cells[TERRAIN_PLATFORM_CELL];
        for (i16 i = 0; i < static_cast<i16>(cell.group_count); ++i) {
            if (terrain->group_indices[cell.first_group + i] == last_group) {
                terrain->group_indices[cell.first_group + i] = terrain->group_indices[index_count];
                break;
            }
        }
        --cell.group_count;
        ScanTerrIDRemovePlat(index);
        return 1;
    }

extern "C" i32 AddMSituExtraTerrRot(i32 source_index, NUMTX *matrix, NUMTX *previous, i32 rotating, TERRSET *source) {
    if (source == NULL)
        return -1;
    if (CurTerr == NULL) {
        CurTerr = source;
        for (i32 i = 0; i < CurTerr->removed_platform_count; ++i)
            DeletePlatinst(CurTerr->removed_platforms[i]);
        CurTerr->removed_platform_count = 0;
        curSphereter = 0;
    }
    TERRSET *terrain = CurTerr;
    i32 index_count = terrain->group_index_count;
    if (index_count >= terrain->max_group_indices)
        return -1;
    i16 group_index = terrain->group_count;
    if (group_index >= terrain->max_groups || matrix == NULL || (rotating != 0 && previous == NULL) ||
        source->removed_platform_count >= 32 || source->group_count <= source_index)
        return -1;
    TERRAIN_PLATFORM *platform = NULL;
    i32 index = -1;
    for (i32 i = 0; i < terrain->max_platforms; i++) {
        platform = &terrain->platforms[i];
        if (platform->scene_object == NULL) {
            index = i;
            break;
        }
    }
    if (index == -1)
        return -1;
    return InstallExtraTerrainPlatform(terrain, &source->groups[source_index], matrix, previous, rotating, index,
                                       *platform, group_index, index_count);
}

extern "C" void TerrainPlatformOldUpdate(void) {
    if (CurTerr != NULL) {
        curPickInst = 0;
        for (i32 i = 0; i < CurTerr->removed_platform_count; ++i)
            DeletePlatinst(CurTerr->removed_platforms[i]);
        CurTerr->removed_platform_count = 0;
        curSphereter = 0;
        if (CurTerr->max_platforms <= 0)
            return;
        TERRAIN_PLATFORM *platform = CurTerr->platforms;
        TERRAIN_PLATFORM *end = platform + CurTerr->max_platforms;
        for (; platform != end; ++platform) {
            if (platform->scene_object != NULL)
                platform->previous_matrix = *static_cast<NUMTX *>(platform->scene_object);
        }
    }
}

    void UpdatePlatinst(i32 index, void *object) {
        if (index >= 0 && index < CurTerr->max_platforms)
            CurTerr->platforms[index].scene_object = object;
    }

}

